      "title": "Remove duplicates in-place from a sorted array and return the count of unique elements.",
      "canonicalName": "Remove duplicates from sorted array",
      "difficulty": "Easy",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Array prefix nums[0..slow] strictly maintains unique elements in their original relative order.\n- Mechanics: Fast pointer scans every element; whenever nums[fast] != nums[slow], increment slow and write nums[slow] = nums[fast].\n- Edge: Single-element arrays or arrays with all identical values require zero writes beyond initializing slow = 0.",
      "leetcode": "https://leetcode.com/problems/remove-duplicates-from-sorted-array/#:~:text=Input%3A%20nums%20%3D%20%5B0%2C,%2C%203%2C%20and%204%20respectively.",
      "tuf": "https://takeuforward.org/data-structure/remove-duplicates-in-place-from-sorted-array/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Class to hold the solution logic\nclass Solution {\npublic:\n    // Function to remove duplicates from sorted array in-place\n    int removeDuplicates(vector<int>& nums) {\n        // If array is empty, return 0 directly\n        if (nums.empty()) return 0;\n\n        // Pointer for the position of last unique element\n        int i = 0;\n\n        // Traverse the array starting from the second element\n        for (int j = 1; j < nums.size(); j++) {\n            // If current element is different from last unique element\n            if (nums[j] != nums[i]) {\n                // Move pointer for unique element forward\n                i++;\n                // Place the new unique element at the next position\n                nums[i] = nums[j];\n            }\n        }\n\n        // i is index of last unique element, count = i + 1\n        return i + 1;\n    }\n};\n\nint main() {\n    vector<int> nums = {0,0,1,1,1,2,2,3,3,4};\n\n    Solution sol;\n    int k = sol.removeDuplicates(nums);\n\n    cout << \"Unique count = \" << k << \"\\n\";\n    cout << \"Array after removing duplicates: \";\n    for (int x = 0; x < k; x++) {\n        cout << nums[x] << \" \";\n    }\n    cout << endl;\n}",
      "py": "# Class to hold the solution logic\nclass Solution:\n    # Function to remove duplicates from sorted array in-place\n    def removeDuplicates(self, nums):\n        # If list is empty, return 0\n        if not nums:\n            return 0\n\n        # Pointer for last unique element\n        i = 0\n\n        # Traverse list starting from second element\n        for j in range(1, len(nums)):\n            # If current element is different from last unique one\n            if nums[j] != nums[i]:\n                # Move pointer forward\n                i += 1\n                # Place the unique element in next position\n                nums[i] = nums[j]\n\n        # i is last index of unique element, count = i + 1\n        return i + 1\n\n\n# Example usage\nnums = [0,0,1,1,1,2,2,3,3,4]\nsol = Solution()\nk = sol.removeDuplicates(nums)\nprint(\"Unique count =\", k)\nprint(\"Array after removing duplicates:\", nums[:k])"
