      "title": "Delete the N-th node from the end of a singly linked list and return its head.",
      "canonicalName": "Remove Nth node from the back of the LL",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Maintain a strict invariant distance gap of N nodes between fast and slow pointers.\n- Mechanics: Advance fast N steps ahead, then advance both pointers concurrently until fast reaches list termination.\n- Edge: Prepend a sentinel dummy node before head to seamlessly handle deleting the initial head node.",
      "leetcode": "https://leetcode.com/problems/remove-nth-node-from-end-of-list/",
      "tuf": "https://takeuforward.org/data-structure/remove-n-th-node-from-the-end-of-a-linked-list/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Class representing a node in the linked list\nclass Node {\npublic:\n    int data;\n    Node* next;\n\n    // Constructor for Node with data and next node\n    Node(int data1, Node* next1) {\n        data = data1;\n        next = next1;\n    }\n\n    // Constructor for Node with only data (next = nullptr)\n    Node(int data1) {\n        data = data1;\n        next = nullptr;\n    }\n};\n\n// Class to hold the solution logic\nclass Solution {\npublic:\n    // Function to print the linked list\n    void printLL(Node* head) {\n        while (head != NULL) {\n            cout << head->data << \" \";\n            head = head->next;\n        }\n    }\n\n    // Function to delete the Nth node from the end \n    // using the optimized two-pointer method\n    Node* deleteNthNodeFromEnd(Node* head, int N) {\n        // Create a dummy node before head to handle edge cases\n        Node* dummy = new Node(0, head);\n\n        // Initialize slow and fast pointers at dummy\n        Node* slow = dummy;\n        Node* fast = dummy;\n\n        // Move fast pointer N+1 steps ahead to create a gap\n        for (int i = 0; i <= N; i++) {\n            fast = fast->next;\n        }\n\n        // Move both pointers until fast reaches the end\n        while (fast != NULL) {\n            slow = slow->next;\n            fast = fast->next;\n        }\n\n        // Slow is now at node before target → delete target node\n        slow->next = slow->next->next;\n\n        // Return updated head\n        return dummy->next;\n    }\n};\n\n// Main driver code\nint main() {\n    vector<int> arr = {1, 2, 3, 4, 5};\n    int N = 3;\n\n    // Create linked list manually\n    Node* head = new Node(arr[0]);\n    head->next = new Node(arr[1]);\n    head->next->next = new Node(arr[2]);\n    head->next->next->next = new Node(arr[3]);\n    head->next->next->next->next = new Node(arr[4]);\n\n    // Create Solution object\n    Solution sol;\n\n    // Delete the Nth node from the end\n    head = sol.deleteNthNodeFromEnd(head, N);\n\n    // Print the modified linked list\n    sol.printLL(head);\n}",
      "py": "# Class representing a node in the linked list\nclass Node:\n    def __init__(self, data1, next1=None):\n        self.data = data1\n        self.next = next1\n\n# Class to hold the solution logic\nclass Solution:\n    # Function to print the linked list\n    def printLL(self, head):\n        while head is not None:\n            print(head.data, end=\" \")\n            head = head.next\n\n    # Function to delete the Nth node from the end \n    # using the optimized two-pointer method\n    def deleteNthNodeFromEnd(self, head, N):\n        # Create a dummy node before head to handle edge cases\n        dummy = Node(0, head)\n\n        # Initialize slow and fast pointers at dummy\n        slow = dummy\n        fast = dummy\n\n        # Move fast pointer N+1 steps ahead to create a gap\n        for _ in range(N + 1):\n            fast = fast.next\n\n        # Move both pointers until fast reaches the end\n        while fast is not None:\n            slow = slow.next\n            fast = fast.next\n\n        # Slow is now at node before target → delete target node\n        slow.next = slow.next.next\n\n        # Return updated head\n        return dummy.next\n\n# Main driver code\nif __name__ == \"__main__\":\n    arr = [1, 2, 3, 4, 5]\n    N = 3\n\n    # Create linked list manually\n    head = Node(arr[0])\n    head.next = Node(arr[1])\n    head.next.next = Node(arr[2])\n    head.next.next.next = Node(arr[3])\n    head.next.next.next.next = Node(arr[4])\n\n    # Create Solution object\n    sol = Solution()\n\n    # Delete the Nth node from the end\n    head = sol.deleteNthNodeFromEnd(head, N)\n\n    # Print the modified linked list\n    sol.printLL(head)"
