      "title": "Reverse the sequence of words in a string, stripping excess spaces.",
      "canonicalName": "Reverse every word in a string",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Dual pointer boundaries isolate individual word segments within the character sequence.\n- Mechanics: Reverse the entire string, then reverse each word segment individually while shifting characters to eliminate redundant whitespace.\n- Edge: Handle leading, trailing, and multiple consecutive internal delimiter spaces without generating empty tokens.",
      "leetcode": "https://leetcode.com/problems/reverse-words-in-a-string/",
      "tuf": "https://takeuforward.org/data-structure/reverse-words-in-a-string/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to reverse the order of words \n    string reverseWords(string s) {\n        // Result string to store final output\n        string result = \"\";\n        \n        // Pointer starting from the last character\n        int i = s.size() - 1;\n        \n        // Traverse string from right to left\n        while (i >= 0) {\n            // Skip spaces at the current position\n            while (i >= 0 && s[i] == ' ') {\n                i--;\n            }\n            \n            // If pointer is out of bounds, break\n            if (i < 0) break;\n            \n            // Mark the end of the current word\n            int end = i;\n            \n            // Move left until a space or start of string is found\n            while (i >= 0 && s[i] != ' ') {\n                i--;\n            }\n            \n            // Extract the current word\n            string word = s.substr(i + 1, end - i);\n            \n            // Add space before appending next word if result is not empty\n            if (!result.empty()) {\n                result += \" \";\n            }\n            \n            // Append the word to the result\n            result += word;\n        }\n        \n        return result;\n    }\n};\n\n// Driver code\nint main() {\n    Solution obj;\n    string s = \" amazing coding skills \";\n    cout << obj.reverseWords(s) << endl;\n    return 0;\n}",
      "py": "class Solution:\n    # Function to reverse the order of words \n    def reverseWords(self, s: str) -> str:\n        # Result string\n        result = \"\"\n        \n        # Pointer starting from end\n        i = len(s) - 1\n        \n        # Traverse from right to left\n        while i >= 0:\n            # Skip spaces\n            while i >= 0 and s[i] == \" \":\n                i -= 1\n            \n            # If pointer out of bounds, break\n            if i < 0:\n                break\n            \n            # Mark end of word\n            end = i\n            \n            # Move left until space or start\n            while i >= 0 and s[i] != \" \":\n                i -= 1\n            \n            # Extract the word\n            word = s[i + 1:end + 1]\n            \n            # Add space if result is not empty\n            if result != \"\":\n                result += \" \"\n            \n            # Append word\n            result += word\n        \n        return result\n\n# Driver code\nif __name__ == \"__main__\":\n    obj = Solution()\n    s = \" amazing coding skills \"\n    print(obj.reverseWords(s))"
