      "title": "Compare two version numbers separated by dots, returning -1, 0, or 1.",
      "canonicalName": "Compare version numbers",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N + M)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Dual pointers advance synchronously through period-delimited numerical tokens across both strings.\n- Mechanics: Parse characters up to the next dot into integers, compare values, and advance pointers beyond the delimiter.\n- Edge: When one string ends early, treat all its subsequent implicit revisions as integer 0.",
      "leetcode": "",
      "tuf": "",
      "cpp": "class Solution {\npublic:\n    int compareVersion(string version1, string version2) {\n        int n = version1.length();\n        int m = version2.length();\n        int i = 0, j = 0;\n\n        while (i < n || j < m) {\n            long long num1 = 0;\n            long long num2 = 0;\n\n            // Parse revision for version1\n            while (i < n && version1[i] != '.') {\n                num1 = num1 * 10 + (version1[i] - '0');\n                i++;\n            }\n\n            // Parse revision for version2\n            while (j < m && version2[j] != '.') {\n                num2 = num2 * 10 + (version2[j] - '0');\n                j++;\n            }\n\n            // Compare parsed revisions\n            if (num1 < num2) {\n                return -1;\n            }\n            if (num1 > num2) {\n                return 1;\n            }\n\n            // Skip the '.' delimiter\n            if (i < n) i++;\n            if (j < m) j++;\n        }\n\n        return 0;\n    }\n};",
      "py": "class Solution:\n    def compareVersion(self, version1: str, version2: str) -> int:\n        n, m = len(version1), len(version2)\n        i, j = 0, 0\n\n        while i < n or j < m:\n            num1 = 0\n            num2 = 0\n\n            # Parse revision for version1\n            while i < n and version1[i] != '.':\n                num1 = num1 * 10 + int(version1[i])\n                i += 1\n\n            # Parse revision for version2\n            while j < m and version2[j] != '.':\n                num2 = num2 * 10 + int(version2[j])\n                j += 1\n\n            # Compare parsed revisions\n            if num1 < num2:\n                return -1\n            if num1 > num2:\n                return 1\n\n            # Skip the '.' delimiter\n            if i < n:\n                i += 1\n            if j < m:\n                j += 1\n\n        return 0"
