      "problemSeq": 6,
      "title": "Sort an array containing exclusively values 0, 1, and 2 in-place in linear time.",
      "canonicalName": "Sort an array of 0's 1's and 2's",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Dutch National Flag segments: [0..low-1]=0, [low..mid-1]=1, and [high+1..N-1]=2.\n- Mechanics: If nums[mid]==0 swap with low and increment both; if 1 increment mid; if 2 swap with high and decrement high.\n- Edge: Do not increment mid after swapping with high, as the newly swapped element at mid remains uninspected.",
      "leetcode": "https://leetcode.com/problems/sort-colors/",
      "tuf": "https://takeuforward.org/data-structure/sort-an-array-of-0s-1s-and-2s/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to sort array containing 0s, 1s, and 2s using Dutch National Flag Algorithm\n    void sortZeroOneTwo(vector<int>& nums) {\n        // Initialize three pointers: low, mid starting from 0, high from end of array\n        int low = 0, mid = 0, high = nums.size() - 1;\n\n        // Process elements until mid pointer crosses high pointer\n        while (mid <= high) {\n            // If current element is 0, swap with low and move both pointers forward\n            if (nums[mid] == 0) {\n                swap(nums[mid], nums[low]);\n                mid++;\n                low++;\n            }\n            // If current element is 1, it's already in correct place → move mid forward\n            else if (nums[mid] == 1) {\n                mid++;\n            }\n            // If current element is 2, swap with high and move only high pointer backward\n            else {\n                swap(nums[mid], nums[high]);\n                high--;\n            }\n        }\n    }\n};\n\n// Driver code\nint main() {\n    Solution obj;\n    vector<int> nums = {2, 0, 2, 1, 1, 0};\n\n    obj.sortZeroOneTwo(nums);\n\n    for (int val : nums)\n        cout << val << \" \";\n\n    return 0;\n}",
      "py": "class Solution:\n    # Function to sort list containing 0s, 1s, and 2s using Dutch National Flag Algorithm\n    def sortZeroOneTwo(self, nums):\n        # Initialize three pointers: low and mid at 0, high at end\n        low, mid, high = 0, 0, len(nums) - 1\n\n        # Traverse until mid crosses high\n        while mid <= high:\n            # If element is 0, swap with low, move both low and mid forward\n            if nums[mid] == 0:\n                nums[low], nums[mid] = nums[mid], nums[low]\n                low += 1\n                mid += 1\n            # If element is 1, just move mid forward\n            elif nums[mid] == 1:\n                mid += 1\n            # If element is 2, swap with high, move only high backward\n            else:\n                nums[mid], nums[high] = nums[high], nums[mid]\n                high -= 1\n\n# Driver code\nnums = [2, 0, 2, 1, 1, 0]\nobj = Solution()\nobj.sortZeroOneTwo(nums)\nprint(nums)"
