      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N + M)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Equalize traversal lengths across both lists via path redirection (a + c + b = b + c + a).\n- Mechanics: Traverse with two pointers; when either pointer reaches null, redirect it to the head of the opposing list.\n- Edge: If lists do not intersect, both pointers hit null simultaneously at the end of pass two, safely terminating.",
      "leetcode": "https://leetcode.com/problems/intersection-of-two-linked-lists/",
      "tuf": "https://takeuforward.org/data-structure/find-intersection-of-two-linked-lists/",
      "cpp": "#include<bits/stdc++.h>\nusing namespace std;\n\nclass node {\npublic:\n    int num;\n    node* next;\n    node(int val) {\n        num = val;\n        next = NULL;\n    }\n};\n\n// Utility function to insert node at the end of the linked list\nvoid insertNode(node* &head, int val) {\n    node* newNode = new node(val);\n    \n    if (head == NULL) {\n        head = newNode;\n        return;\n    }\n    \n    node* temp = head;\n    while (temp->next != NULL) temp = temp->next;\n    \n    temp->next = newNode;\n}\n\n// Utility function to get the difference in lengths of two linked lists\nint getDifference(node* head1, node* head2) {\n    int len1 = 0, len2 = 0;\n    while (head1 != NULL || head2 != NULL) {\n        if (head1 != NULL) {\n            ++len1;\n            head1 = head1->next;\n        }\n        if (head2 != NULL) {\n            ++len2;\n            head2 = head2->next;\n        }\n    }\n    return len1 - len2;  // If negative, length of list2 > length of list1, else vice-versa\n}\n\n// Utility function to check presence of intersection\nnode* intersectionPresent(node* head1, node* head2) {\n    int diff = getDifference(head1, head2);\n    \n    if (diff < 0) \n        while (diff++ != 0) head2 = head2->next;\n    else \n        while (diff-- != 0) head1 = head1->next;\n    \n    // Traverse both lists and compare node by node\n    while (head1 != NULL) {\n        if (head1 == head2) return head1;  // Intersection point found\n        head2 = head2->next;\n        head1 = head1->next;\n    }\n    return head1;  // Return NULL if no intersection\n}\n\n// Utility function to print linked list\nvoid printList(node* head) {\n    while (head->next != NULL) {\n        cout << head->num << \"->\";\n        head = head->next;\n    }\n    cout << head->num << endl;\n}\n\nint main() {\n    node* head = NULL;\n    insertNode(head, 1);\n    insertNode(head, 3);\n    insertNode(head, 1);\n    insertNode(head, 2);\n    insertNode(head, 4);\n    node* head1 = head;\n    head = head->next->next->next;  // Intersection point\n    node* headSec = NULL;\n    insertNode(headSec, 3);\n    node* head2 = headSec;\n    headSec->next = head;  // Creating intersection\n    \n    // Printing the lists\n    cout << \"List1: \";\n    printList(head1);\n    cout << \"List2: \";\n    printList(head2);\n    \n    // Checking if intersection is present\n    node* answerNode = intersectionPresent(head1, head2);\n    if (answerNode == NULL) \n        cout << \"No intersection\\n\";\n    else \n        cout << \"The intersection point is \" << answerNode->num << endl;\n    \n    return 0;\n}",
      "py": "class Node:\n    def __init__(self, val):\n        self.num = val\n        self.next = None\n\n# Utility function to insert node at the end of the linked list\ndef insertNode(head, val):\n    newNode = Node(val)\n    if not head:\n        head = newNode\n        return head\n    temp = head\n    while temp.next:\n        temp = temp.next\n    temp.next = newNode\n    return head\n\n# Utility function to get the difference in lengths of two linked lists\ndef getDifference(head1, head2):\n    len1, len2 = 0, 0\n    while head1 or head2:\n        if head1:\n            len1 += 1\n            head1 = head1.next\n        if head2:\n            len2 += 1\n            head2 = head2.next\n    return len1 - len2  # If negative, length of list2 > length of list1, else vice-versa\n\n# Utility function to check presence of intersection\ndef intersectionPresent(head1, head2):\n    diff = getDifference(head1, head2)\n\n    if diff < 0:\n        while diff != 0:\n            head2 = head2.next\n            diff += 1\n    else:\n        while diff != 0:\n            head1 = head1.next\n            diff -= 1\n\n    # Traverse both lists and compare node by node\n    while head1:\n        if head1 == head2:\n            return head1  # Intersection point found\n        head2 = head2.next\n        head1 = head1.next\n    return None  # No intersection found\n\n# Utility function to print linked list\ndef printList(head):\n    while head and head.next:\n        print(f\"{head.num}->\", end=\"\")\n        head = head.next\n    if head:\n        print(head.num, end=\"\")\n    print()\n\n# Driver code\nhead = Node(1)\ninsertNode(head, 3)\ninsertNode(head, 1)\ninsertNode(head, 2)\ninsertNode(head, 4)\nhead1 = head\nhead = head.next.next.next  # Intersection point\nheadSec = Node(3)\nhead2 = headSec\nheadSec.next = head  # Creating intersection\n\n# Printing the lists\nprint(\"List1: \", end=\"\")\nprintList(head1)\nprint(\"List2: \", end=\"\")\nprintList(head2)\n\n# Checking if intersection is present\nanswerNode = intersectionPresent(head1, head2)\nif answerNode is None:\n    print(\"No intersection\")\nelse:\n    print(f\"The intersection point is {answerNode.num}\")"
