      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Fast/slow pointers isolate the midpoint, converting the problem to symmetric prefix-suffix verification.\n- Mechanics: Locate midpoint with slow/fast pointers, reverse the second half in-place, and compare element-by-element from both heads.\n- Edge: Restore the original list structure post-verification if downstream operations require non-mutated inputs.",
      "leetcode": "https://leetcode.com/problems/palindrome-linked-list/",
      "tuf": "https://takeuforward.org/data-structure/check-if-given-linked-list-is-plaindrome/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Node class represents a node in a linked list\nclass Node {\npublic:\n    int data;       // Data stored in the node\n    Node* next;     // Pointer to the next node in the list\n\n    // Constructor with both data and next node as parameters\n    Node(int data1, Node* next1) {\n        data = data1;\n        next = next1;\n    }\n\n    // Constructor with only data as a parameter, sets next to nullptr\n    Node(int data1) {\n        data = data1;\n        next = nullptr;\n    }\n};\n\n// Function to reverse a linked list using the recursive approach\nNode* reverseLinkedList(Node* head) {\n    // Check if the list is empty or has only one node\n    if (head == NULL || head->next == NULL) {\n        return head;  // No change is needed; return the current head\n    }\n\n    // Recursive step: Reverse the remaining part of the list and get the new head\n    Node* newHead = reverseLinkedList(head->next);\n\n    // Store the next node in 'front' to reverse the link\n    Node* front = head->next;\n\n    // Update the 'next' pointer of 'front' to point to the current head\n    front->next = head;\n\n    // Set the 'next' pointer of the current head to null to break the original link\n    head->next = NULL;\n\n    // Return the new head obtained from the recursion\n    return newHead;\n}\n\n// Function to check if the linked list is a palindrome\nbool isPalindrome(Node* head) {\n    // Check if the linked list is empty or has only one node\n    if (head == NULL || head->next == NULL) {\n        return true;  // It's a palindrome by definition\n    }\n\n    // Initialize two pointers, slow and fast, to find the middle of the linked list\n    Node* slow = head;\n    Node* fast = head;\n\n    // Traverse the linked list to find the middle using slow and fast pointers\n    while (fast->next != NULL && fast->next->next != NULL) {\n        slow = slow->next;       // Move slow pointer one step at a time\n        fast = fast->next->next; // Move fast pointer two steps at a time\n    }\n\n    // Reverse the second half of the linked list starting from the middle\n    Node* newHead = reverseLinkedList(slow->next);\n\n    // Pointer to the first half\n    Node* first = head;\n\n    // Pointer to the reversed second half\n    Node* second = newHead;\n\n    // Compare data values of nodes from both halves\n    while (second != NULL) {\n        if (first->data != second->data) {\n            // If values do not match, the list is not a palindrome\n            reverseLinkedList(newHead);  // Reverse the second half back to its original state\n            return false;\n        }\n\n        first = first->next;  // Move the first pointer\n        second = second->next; // Move the second pointer\n    }\n\n    // Reverse the second half back to its original state\n    reverseLinkedList(newHead);\n\n    // The linked list is a palindrome\n    return true;\n}\n\n// Function to print the linked list\nvoid printLinkedList(Node* head) {\n    Node* temp = head;\n    while (temp != nullptr) {\n        cout << temp->data << \" \";  // Print the current node's data\n        temp = temp->next;          // Move to the next node\n    }\n    cout << endl;\n}\n\n// Driver function\nint main() {\n    // Create a linked list with values 1, 5, 2, 5, and 1 (15251, a palindrome)\n    Node* head = new Node(1);\n    head->next = new Node(5);\n    head->next->next = new Node(2);\n    head->next->next->next = new Node(5);\n    head->next->next->next->next = new Node(1);\n\n    // Print the original linked list\n    cout << \"Original Linked List: \";\n    printLinkedList(head);\n\n    // Check if the linked list is a palindrome\n    if (isPalindrome(head)) {\n        cout << \"The linked list is a palindrome.\" << endl;\n    } else {\n        cout << \"The linked list is not a palindrome.\" << endl;\n    }\n\n    return 0;\n}",
      "py": "# Node class represents a node in a linked list\nclass Node:\n    def __init__(self, data, next_node=None):\n        self.data = data       # Data stored in the node\n        self.next = next_node  # Pointer to the next node in the list\n\n# Function to reverse a linked list using the recursive approach\ndef reverse_linked_list(head):\n    if head is None or head.next is None:\n        return head  # No change is needed; return the current head\n\n    # Recursive step: Reverse the remaining part of the list and get the new head\n    new_head = reverse_linked_list(head.next)\n\n    # Store the next node in 'front' to reverse the link\n    front = head.next\n\n    # Update the 'next' pointer of 'front' to point to the current head\n    front.next = head\n\n    # Set the 'next' pointer of the current head to None to break the original link\n    head.next = None\n\n    return new_head  # Return the new head obtained from the recursion\n\n# Function to check if the linked list is a palindrome\ndef is_palindrome(head):\n    if head is None or head.next is None:\n        return True  # It's a palindrome by definition\n\n    slow = head\n    fast = head\n\n    # Traverse the linked list to find the middle using slow and fast pointers\n    while fast.next is not None and fast.next.next is not None:\n        slow = slow.next      # Move slow pointer one step at a time\n        fast = fast.next.next # Move fast pointer two steps at a time\n\n    # Reverse the second half of the linked list starting from the middle\n    new_head = reverse_linked_list(slow.next)\n\n    first = head\n    second = new_head\n\n    # Compare data values of nodes from both halves\n    while second is not None:\n        if first.data != second.data:\n            reverse_linked_list(new_head)  # Reverse the second half back to its original state\n            return False\n\n        first = first.next  # Move the first pointer\n        second = second.next  # Move the second pointer\n\n    # Reverse the second half back to its original state\n    reverse_linked_list(new_head)\n\n    return True  # The linked list is a palindrome\n\n# Function to print the linked list\ndef print_linked_list(head):\n    temp = head\n    while temp:\n        print(temp.data, end=\" \")  # Print the current node's data\n        temp = temp.next           # Move to the next node\n    print()\n\n# Driver code\nif __name__ == \"__main__\":\n    # Create a linked list with values 1, 5, 2, 5, and 1 (15251, a palindrome)\n    head = Node(1)\n    head.next = Node(5)\n    head.next.next = Node(2)\n    head.next.next.next = Node(5)\n    head.next.next.next.next = Node(1)\n\n    # Print the original linked list\n    print(\"Original Linked List: \", end=\"\")\n    print_linked_list(head)\n\n    # Check if the linked list is a palindrome\n    if is_palindrome(head):\n        print(\"The linked list is a palindrome.\")\n    else:\n        print(\"The linked list is not a palindrome.\")"
