      "title": "Find the node where a cycle begins in a singly linked list, or return null if no cycle exists.",
      "canonicalName": "Find the starting point in LL",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Distance from head to cycle entrance equals distance from collision node to cycle entrance modulo cycle length.\n- Mechanics: Detect collision via fast/slow pointers; reset slow to head while keeping fast at collision point, then step both by 1.\n- Edge: Ensure list contains a confirmed cycle before initializing the secondary search loop.",
      "leetcode": "https://leetcode.com/problems/linked-list-cycle-ii/",
      "tuf": "https://takeuforward.org/data-structure/starting-point-of-loop-in-a-linked-list/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass ListNode {\npublic:\n    int val;\n    ListNode* next;\n    ListNode(int x) {\n        val = x;\n        next = NULL;\n    }\n};\n\nclass Solution {\npublic:\n    // Function to detect the starting point of the loop using Floyd’s algorithm\n    ListNode* detectCycle(ListNode* head) {\n        // Initialize slow and fast pointers\n        ListNode* slow = head;\n        ListNode* fast = head;\n\n        // Traverse until fast and fast->next are not null\n        while (fast != NULL && fast->next != NULL) {\n            // Move slow by one step\n            slow = slow->next;\n\n            // Move fast by two steps\n            fast = fast->next->next;\n\n            // If they meet, loop is detected\n            if (slow == fast) {\n                // Reset slow to head\n                slow = head;\n\n                // Move both one step at a time to find starting point\n                while (slow != fast) {\n                    slow = slow->next;\n                    fast = fast->next;\n                }\n\n                // Return the start node of the loop\n                return slow;\n            }\n        }\n\n        // If no loop found, return NULL\n        return NULL;\n    }\n};\n\n// Driver code\nint main() {\n    // Create nodes\n    ListNode* head = new ListNode(3);\n    head->next = new ListNode(2);\n    head->next->next = new ListNode(0);\n    head->next->next->next = new ListNode(-4);\n\n    // Create a cycle: connect tail to index 1 node (value 2)\n    head->next->next->next->next = head->next;\n\n    Solution obj;\n    ListNode* result = obj.detectCycle(head);\n\n    if (result != NULL)\n        cout << \"Cycle starts at node with value: \" << result->val << endl;\n    else\n        cout << \"No cycle found.\" << endl;\n\n    return 0;\n}",
      "py": "class ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\nclass Solution:\n    # Function to detect the starting node of the loop using Floyd’s algorithm\n    def detectCycle(self, head):\n        # Initialize slow and fast pointers\n        slow = head\n        fast = head\n\n        # Traverse while fast and fast.next are not None\n        while fast and fast.next:\n            # Move slow one step\n            slow = slow.next\n\n            # Move fast two steps\n            fast = fast.next.next\n\n            # If they meet, there is a cycle\n            if slow == fast:\n                # Reset slow to head\n                slow = head\n\n                # Move both pointers one step to find entry point\n                while slow != fast:\n                    slow = slow.next\n                    fast = fast.next\n\n                # Return starting node of cycle\n                return slow\n\n        # No cycle found\n        return None\n\n# Driver code\nif __name__ == \"__main__\":\n    # Create linked list nodes\n    head = ListNode(3)\n    head.next = ListNode(2)\n    head.next.next = ListNode(0)\n    head.next.next.next = ListNode(-4)\n\n    # Create cycle (last node points to node with value 2)\n    head.next.next.next.next = head.next\n\n    obj = Solution()\n    result = obj.detectCycle(head)\n\n    if result:\n        print(\"Cycle starts at node with value:\", result.val)\n    else:\n        print(\"No cycle found.\")"
