      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Class to solve 3-sum problem\nclass Solution {\npublic:\n    // Function to find triplets with sum zero\n    vector<vector<int>> threeSum(vector<int>& arr, int n) {\n        // Sort the array\n        sort(arr.begin(), arr.end());\n        // Store final result\n        vector<vector<int>> ans;\n\n        // First loop for first element\n        for (int i = 0; i < n; i++) {\n            // Skip duplicates for first element\n            if (i > 0 && arr[i] == arr[i - 1]) continue;\n\n            // Two pointers\n            int left = i + 1, right = n - 1;\n\n            // Find pairs for current arr[i]\n            while (left < right) {\n                int sum = arr[i] + arr[left] + arr[right];\n\n                if (sum == 0) {\n                    ans.push_back({arr[i], arr[left], arr[right]});\n                    left++, right--;\n\n                    // Skip duplicates for left\n                    while (left < right && arr[left] == arr[left - 1]) left++;\n                    // Skip duplicates for right\n                    while (left < right && arr[right] == arr[right + 1]) right--;\n                }\n                else if (sum < 0) left++;\n                else right--;\n            }\n        }\n        return ans;\n    }\n};\n\n// Driver code\nint main() {\n    vector<int> arr = {-1, 0, 1, 2, -1, -4};\n    int n = arr.size();\n    Solution obj;\n    vector<vector<int>> res = obj.threeSum(arr, n);\n\n    for (auto &triplet : res) {\n        for (auto &num : triplet) cout << num << \" \";\n        cout << endl;\n    }\n    return 0;\n}",
      "py": "# Class to solve 3-sum problem\nclass Solution:\n    # Function to find triplets with sum zero\n    def threeSum(self, arr, n):\n        # Sort the array\n        arr.sort()\n        # Store final result\n        ans = []\n\n        # First loop for first element\n        for i in range(n):\n            # Skip duplicates for first element\n            if i > 0 and arr[i] == arr[i - 1]:\n                continue\n\n            # Two pointers\n            left, right = i + 1, n - 1\n\n            # Find pairs for current arr[i]\n            while left < right:\n                total = arr[i] + arr[left] + arr[right]\n\n                if total == 0:\n                    ans.append([arr[i], arr[left], arr[right]])\n                    left += 1\n                    right -= 1\n\n                    # Skip duplicates for left\n                    while left < right and arr[left] == arr[left - 1]:\n                        left += 1\n                    # Skip duplicates for right\n                    while left < right and arr[right] == arr[right + 1]:\n                        right -= 1\n\n                elif total < 0:\n                    left += 1\n                else:\n                    right -= 1\n        return ans\n\n# Driver code\nif __name__ == \"__main__\":\n    arr = [-1, 0, 1, 2, -1, -4]\n    n = len(arr)\n    obj = Solution()\n    res = obj.threeSum(arr, n)\n    for triplet in res:\n        print(triplet)"
