      "bounds": "Time Complexity: $\\mathcal{O}(N^3)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Nested loops fix two coordinates (i, j), reducing the remaining search space to linear two-pointer convergence.\n- Mechanics: Sort array; nest loops for i and j; sweep left and right inward on the remaining suffix to match remaining target.\n- Edge: Cast four-element sum expressions to 64-bit integer (long long) to prevent arithmetic integer overflow during accumulation.",
      "leetcode": "https://leetcode.com/problems/4sum/",
      "tuf": "https://takeuforward.org/data-structure/4-sum-find-quads-that-add-up-to-a-target-value/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to find all unique quadruplets\n    vector<vector<int>> fourSum(vector<int>& arr, int target) {\n        int n = arr.size();\n        vector<vector<int>> ans;\n\n        // Step 1: Sort array\n        sort(arr.begin(), arr.end());\n\n        // Step 2: First loop for first number\n        for (int i = 0; i < n; i++) {\n            // Skip duplicates for first number\n            if (i > 0 && arr[i] == arr[i - 1]) continue;\n\n            // Step 3: Second loop for second number\n            for (int j = i + 1; j < n; j++) {\n                // Skip duplicates for second number\n                if (j > i + 1 && arr[j] == arr[j - 1]) continue;\n\n                // Step 4: Two pointers for remaining two numbers\n                int left = j + 1, right = n - 1;\n                while (left < right) {\n                    long long sum = (long long)arr[i] + arr[j] +\n                                    arr[left] + arr[right];\n\n                    if (sum == target) {\n                        ans.push_back({arr[i], arr[j],\n                                       arr[left], arr[right]});\n\n                        // Move left pointer skipping duplicates\n                        while (left < right && arr[left] == arr[left + 1])\n                            left++;\n                        // Move right pointer skipping duplicates\n                        while (left < right && arr[right] == arr[right - 1])\n                            right--;\n\n                        left++;\n                        right--;\n                    }\n                    else if (sum < target) left++;\n                    else right--;\n                }\n            }\n        }\n        return ans;\n    }\n};\n\nint main() {\n    vector<int> arr = {1, 0, -1, 0, -2, 2};\n    int target = 0;\n\n    Solution obj;\n    vector<vector<int>> ans = obj.fourSum(arr, target);\n\n    for (auto quad : ans) {\n        for (int num : quad) cout << num << \" \";\n        cout << endl;\n    }\n    return 0;\n}",
      "py": "class Solution:\n    # Function to find all unique quadruplets\n    def fourSum(self, arr, target):\n        n = len(arr)\n        arr.sort()\n        ans = []\n\n        # Step 1: First loop for first number\n        for i in range(n):\n            if i > 0 and arr[i] == arr[i - 1]:\n                continue\n\n            # Step 2: Second loop for second number\n            for j in range(i + 1, n):\n                if j > i + 1 and arr[j] == arr[j - 1]:\n                    continue\n\n                # Step 3: Two pointers\n                left, right = j + 1, n - 1\n                while left < right:\n                    total = arr[i] + arr[j] + arr[left] + arr[right]\n\n                    if total == target:\n                        ans.append([arr[i], arr[j], arr[left], arr[right]])\n\n                        while left < right and arr[left] == arr[left + 1]:\n                            left += 1\n                        while left < right and arr[right] == arr[right - 1]:\n                            right -= 1\n\n                        left += 1\n                        right -= 1\n                    elif total < target:\n                        left += 1\n                    else:\n                        right -= 1\n        return ans\n\n\n# Driver code\narr = [1, 0, -1, 0, -2, 2]\ntarget = 0\n\nobj = Solution()\nprint(obj.fourSum(arr, target))"
