      "id": 13,
      "patternId": 1,
      "patternName": "Two Pointers and Partitioning",
      "problemSeq": 13,
      "title": "Rearrange numbers into the lexicographically next greater permutation in-place.",
      "canonicalName": "Next Permutation",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant: Suffix following the first descending element nums[i] < nums[i+1] from the right is strictly weakly decreasing.\n- Mechanics: Find largest i such that nums[i] < nums[i+1]; swap nums[i] with next smallest greater element in suffix; reverse suffix.\n- Edge: If no pivot dip exists (entire array descending), reversing the entire array produces the minimum lexicographical order.",
      "leetcode": "https://leetcode.com/problems/next-permutation/",
      "tuf": "https://takeuforward.org/data-structure/next_permutation-find-next-lexicographically-greater-permutation/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Solution class\nclass Solution {\npublic:\n    // Function to find next permutation\n    void nextPermutation(vector<int>& nums) {\n        // Set index to -1\n        int index = -1;\n\n        // Find the first decreasing element from end\n        for (int i = nums.size() - 2; i >= 0; i--) {\n            // If a smaller element found\n            if (nums[i] < nums[i + 1]) {\n                // Store index\n                index = i;\n                break;\n            }\n        }\n\n        // If no such index found\n        if (index == -1) {\n            // Reverse the entire array\n            reverse(nums.begin(), nums.end());\n            return;\n        }\n\n        // Find element just greater than nums[index]\n        for (int i = nums.size() - 1; i > index; i--) {\n            // Swap the two\n            if (nums[i] > nums[index]) {\n                swap(nums[i], nums[index]);\n                break;\n            }\n        }\n\n        // Reverse the part after index\n        reverse(nums.begin() + index + 1, nums.end());\n    }\n};\n\n// Main function\nint main() {\n    // Input array\n    vector<int> nums = {1, 2, 3};\n\n    // Create object\n    Solution sol;\n\n    // Call the function\n    sol.nextPermutation(nums);\n\n    // Print result\n    for (int num : nums) {\n        cout << num << \" \";\n    }\n    cout << endl;\n\n    return 0;\n}",
      "py": "# Solution class\nclass Solution:\n    # Function to find next permutation\n    def nextPermutation(self, nums):\n        # Set index\n        index = -1\n\n        # Find decreasing point\n        for i in range(len(nums) - 2, -1, -1):\n            # If smaller found\n            if nums[i] < nums[i + 1]:\n                index = i\n                break\n\n        # If no such index\n        if index == -1:\n            # Reverse whole list\n            nums.reverse()\n            return\n\n        # Find just greater element\n        for i in range(len(nums) - 1, index, -1):\n            if nums[i] > nums[index]:\n                # Swap them\n                nums[i], nums[index] = nums[index], nums[i]\n                break\n\n        # Reverse part after index\n        nums[index + 1:] = reversed(nums[index + 1:])\n\n# Main driver\ndef main():\n    # Input list\n    nums = [1, 2, 3]\n\n    # Create object\n    sol = Solution()\n\n    # Call function\n    sol.nextPermutation(nums)\n\n    # Print result\n    print(\" \".join(map(str, nums)))\n\n# Run main\nmain()"
