      "id": 19,
      "patternId": 2,
      "patternName": "Sliding Window",
      "problemSeq": 2,
      "title": "Find the maximum profit achievable by choosing a single day to buy one stock and a subsequent day to sell it.",
      "canonicalName": "Stock Buy and Sell",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Window $[L, R]$ maintains the global prefix minimum buy price at index $L$.\n- If $nums[R] > nums[L]$, update profit with $nums[R] - nums[L]$; otherwise, snap $L = R$.\n- Monotonic reset of $L$ to $R$ permanently discards prior higher buy candidates in $\\mathcal{O}(1)$ space.",
      "leetcode": "https://leetcode.com/problems/best-time-to-buy-and-sell-stock/",
      "tuf": "https://takeuforward.org/data-structure/stock-buy-and-sell/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to calculate maximum profit using single pass\n    int stockbuySell(vector<int>& prices) {\n        // Initialize the minimum price to a large number\n        int minPrice = INT_MAX;\n\n        // Initialize the maximum profit to 0\n        int maxProfit = 0;\n\n        // Traverse each price in the array\n        for (int price : prices) {\n            // If current price is less than minPrice, update minPrice\n            if (price < minPrice) {\n                minPrice = price;\n            }\n            // Else calculate profit and update maxProfit if it's greater\n            else {\n                maxProfit = max(maxProfit, price - minPrice);\n            }\n        }\n\n        // Return the maximum profit found\n        return maxProfit;\n    }\n};\n\n// Driver code\nint main() {\n    Solution obj;\n    vector<int> prices = {7, 1, 5, 3, 6, 4};\n\n    cout << obj.stockbuySell(prices) << endl;\n\n    return 0;\n}",
      "py": "class Solution:\n    # Function to calculate maximum profit using single pass\n    def stockbuySell(self, prices):\n        # Initialize the minimum price to a large number\n        min_price = float('inf')\n\n        # Initialize the maximum profit to 0\n        max_profit = 0\n\n        # Traverse each price in the array\n        for price in prices:\n            # If current price is less than min_price, update min_price\n            if price < min_price:\n                min_price = price\n            # Else calculate profit and update max_profit if it's greater\n            else:\n                max_profit = max(max_profit, price - min_price)\n\n        # Return the maximum profit found\n        return max_profit\n\n# Driver code\nobj = Solution()\nprices = [7, 1, 5, 3, 6, 4]\nprint(obj.stockbuySell(prices))"
