      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Solution class to find next greater elements\nclass Solution {\npublic:\n    // Function to find next greater elements\n    vector<int> nextGreater(vector<int>& nums) {\n        // Stack to store elements\n        stack<int> st;\n\n        // Result array of same size\n        int n = nums.size();\n        vector<int> res(n);\n\n        // Traverse from right to left\n        for (int i = n - 1; i >= 0; i--) {\n\n            // Pop all smaller or equal elements\n            while (!st.empty() && st.top() <= nums[i]) {\n                st.pop();\n            }\n\n            // If stack is empty, no greater element\n            if (st.empty()) res[i] = -1;\n\n            // Else top of stack is the answer\n            else res[i] = st.top();\n\n            // Push current element\n            st.push(nums[i]);\n        }\n\n        // Return the result\n        return res;\n    }\n};\n\n// Main function\nint main() {\n    vector<int> nums = {4, 5, 2, 10};\n    Solution sol;\n    vector<int> ans = sol.nextGreater(nums);\n\n    for (int x : ans) {\n        cout << x << \" \";\n    }\n\n    cout << endl;\n    return 0;\n}",
      "py": "# Solution class to find next greater elements\nclass Solution:\n    # Function to find next greater elements\n    def nextGreater(self, nums):\n        # Stack to store elements\n        stack = []\n\n        # Result array of same size\n        n = len(nums)\n        res = [0] * n\n\n        # Traverse from right to left\n        for i in range(n - 1, -1, -1):\n\n            # Pop all smaller or equal elements\n            while stack and stack[-1] <= nums[i]:\n                stack.pop()\n\n            # If stack is empty, no greater element\n            if not stack:\n                res[i] = -1\n\n            # Else top of stack is the answer\n            else:\n                res[i] = stack[-1]\n\n            # Push current element\n            stack.append(nums[i])\n\n        # Return the result\n        return res\n\n# Main function\ndef main():\n    nums = [4, 5, 2, 10]\n    sol = Solution()\n    ans = sol.nextGreater(nums)\n    print(\" \".join(map(str, ans)))\n\nmain()"
