      "patternName": "Monotonic Stack and Queue",
      "problemSeq": 9,
      "title": "Find the first strictly smaller element to the right for each element in an array.",
      "canonicalName": "Next Smaller Element",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(N)$",
      "mantra": "- Maintain a monotonic increasing stack while scanning the array from right to left.\n- Evict all stack elements $\\ge A[i]$ to expose the nearest strictly smaller element.\n- Assign $-1$ if stack is empty after eviction; otherwise record stack top, then push $A[i]$.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/next-smaller-element",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> nextSmallerElement(vector<int>& arr) {\n        int n = arr.size();\n\n        // Stack to store potential next smaller elements\n        stack<int> st;\n\n        // Answer array initialized with -1\n        vector<int> ans(n, -1);\n\n        // Traverse the array from right to left\n        for (int i = n - 1; i >= 0; i--) {\n\n            // Pop elements from stack while they are >= current element\n            while (!st.empty() && st.top() >= arr[i]) {\n                st.pop();\n            }\n\n            // If stack is not empty, top is the next smaller element\n            if (!st.empty()) {\n                ans[i] = st.top();\n            }\n\n            // Push current element to stack\n            st.push(arr[i]);\n        }\n\n        // Return result\n        return ans;\n    }\n};\n\nint main() {\n    vector<int> arr = {1, 3, 2, 4};\n    Solution sol;\n\n    // Get result\n    vector<int> ans = sol.nextSmallerElement(arr);\n\n    // Print result\n    cout << \"The next smaller elements are: \";\n    for (int val : ans) {\n        cout << val << \" \";\n    }\n\n    return 0;\n}",
      "py": "class Solution:\n    def nextSmallerElement(self, arr):\n        n = len(arr)\n\n        # Stack to store potential next smaller elements\n        st = []\n\n        # Initialize result array with -1\n        ans = [-1] * n\n\n        # Traverse from right to left\n        for i in range(n - 1, -1, -1):\n\n            # Pop elements that are not smaller\n            while st and st[-1] >= arr[i]:\n                st.pop()\n\n            # If stack not empty, top is next smaller\n            if st:\n                ans[i] = st[-1]\n\n            # Push current element to stack\n            st.append(arr[i])\n\n        # Return result\n        return ans\n\n# Driver code\narr = [1, 3, 2, 4]\nsol = Solution()\n\n# Get result\nans = sol.nextSmallerElement(arr)\n\n# Print result\nprint(\"The next smaller elements are:\", *ans)"
