      "id": 34,
      "patternId": 3,
      "patternName": "Monotonic Stack and Queue",
      "problemSeq": 11,
      "title": "Find the area of the largest rectangle that can be formed within a given histogram's bar heights.",
      "canonicalName": "Largest rectangle in a histogram",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(N)$",
      "mantra": "- Maintain monotonic increasing bar indices; popping identifies a bar's maximum expansion width.\n- On eviction by a shorter bar, evicted height spans from current index (right bound) to new top (left bound).\n- Append a zero-height sentinel to flush remaining bars out of the stack at termination.",
      "leetcode": "https://leetcode.com/problems/largest-rectangle-in-histogram/",
      "tuf": "https://takeuforward.org/data-structure/area-of-largest-rectangle-in-histogram/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\n  public:\n    int largestRectangleArea(vector<int> &histo) {\n        stack<int> st; // Stack to store indices of the histogram bars\n        int maxA = 0;  // Variable to keep track of the maximum area\n        int n = histo.size();\n\n        // Loop through each bar including an imaginary bar at the end\n        for (int i = 0; i <= n; i++) {\n            // While current bar is smaller than the top of the stack or we reached the end\n            while (!st.empty() && (i == n || histo[st.top()] >= histo[i])) {\n                int height = histo[st.top()]; // Get the height of the bar at top of the stack\n                st.pop(); // Remove that bar\n\n                int width;\n                if (st.empty()) {\n                    width = i; // All bars before were higher\n                } else {\n                    width = i - st.top() - 1; // Width between current index and index at top of stack\n                }\n\n                // Calculate area and update maximum area\n                maxA = max(maxA, width * height);\n            }\n            // Push current index into stack\n            st.push(i);\n        }\n        return maxA;\n    }\n};\n\nint main() {\n    vector<int> histo = {2, 1, 5, 6, 2, 3, 1}; // Input histogram\n    Solution obj;\n    cout << \"The largest area in the histogram is \" << obj.largestRectangleArea(histo) << endl;\n    return 0;\n}",
      "py": "class Solution:\n    def largestRectangleArea(self, heights):\n        stack = []\n        max_area = 0\n        n = len(heights)\n\n        for i in range(n + 1):\n            # Treat height as 0 when i == n (imaginary bar)\n            current_height = heights[i] if i < n else 0\n\n            while stack and (i == n or heights[stack[-1]] >= current_height):\n                height = heights[stack.pop()]  #pop from the stack\n\n                if not stack:\n                    width = i  #take width as i if not in stack else i-stack[-1]-1\n                else:\n                    width = i - stack[-1] - 1\n\n                max_area = max(max_area, height * width)  #calculate the max area \n\n            stack.append(i)\n\n        return max_area #return the max area\n\n# Driver code\nhisto = [2, 1, 5, 6, 2, 3, 1]\nsol = Solution()\nprint(\"The largest area in the histogram is\", sol.largestRectangleArea(histo))"
