      "mantra": "- Invariant Delta: Pre-target pairs begin on even indices; post-target pairs begin on odd indices.\n- Mechanics: Compare $arr[mid]$ with $arr[mid \\oplus 1]$; matching values confirm target lies in the right partition ($low = mid + 1$).\n- Edge/Trap: XOR bisection ($mid \\oplus 1$) handles both even and odd indices without boundary branching.",
      "leetcode": "https://leetcode.com/problems/single-element-in-a-sorted-array/",
      "tuf": "https://takeuforward.org/data-structure/search-single-element-in-a-sorted-array/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n\n// Function to find the single non-duplicate element using binary search\nint singleNonDuplicate(vector<int>& arr) {\n    // Get the size of the array\n    int n = arr.size();\n\n    // Edge case: only one element in the array\n    if (n == 1) return arr[0];\n\n    // Edge case: first element is the unique one\n    if (arr[0] != arr[1]) return arr[0];\n\n    // Edge case: last element is the unique one\n    if (arr[n - 1] != arr[n - 2]) return arr[n - 1];\n\n    // Initialize binary search bounds (exclude first and last index)\n    int low = 1, high = n - 2;\n\n    // Perform binary search\n    while (low <= high) {\n        // Calculate middle index\n        int mid = (low + high) / 2;\n\n        // Check if middle element is the unique one\n        if (arr[mid] != arr[mid + 1] && arr[mid] != arr[mid - 1]) {\n            return arr[mid];\n        }\n\n        // If mid is in the left half (pairing is valid)\n        if ((mid % 2 == 1 && arr[mid] == arr[mid - 1]) ||\n            (mid % 2 == 0 && arr[mid] == arr[mid + 1])) {\n            // Move to the right half\n            low = mid + 1;\n        }\n        // If mid is in the right half (pairing broken earlier)\n        else {\n            // Move to the left half\n            high = mid - 1;\n        }\n    }\n\n    // Dummy return (not reachable if input is valid)\n    return -1;\n   }\n};\n\n// Driver code\nint main() {\n    // Input array with all elements appearing twice except one\n    vector<int> arr = {1, 1, 2, 2, 3, 3, 4, 5, 5, 6, 6};\n\n    // Call the function and store the result\n    Solution obj;\n    \n    int ans = obj.singleNonDuplicate(arr);\n\n    // Print the result\n    cout << \"The single element is: \" << ans << \"\\n\";\n\n    return 0;\n}",
      "py": "class Solution:\n      # Function to find the single non-duplicate element using binary search\n    def singleNonDuplicate(self, arr):\n        # Get the size of the array\n        n = len(arr)\n\n        # Edge case: only one element in the array\n        if n == 1:\n            return arr[0]\n\n        # Edge case: first element is the unique one\n        if arr[0] != arr[1]:\n            return arr[0]\n\n        # Edge case: last element is the unique one\n        if arr[n - 1] != arr[n - 2]:\n            return arr[n - 1]\n\n        # Initialize binary search bounds\n        low, high = 1, n - 2\n\n        # Perform binary search\n        while low <= high:\n            # Calculate middle index\n            mid = (low + high) // 2\n\n            # Check if middle element is the unique one\n            if arr[mid] != arr[mid + 1] and arr[mid] != arr[mid - 1]:\n                return arr[mid]\n\n            # If mid is in the left half (pairing is valid)\n            if (mid % 2 == 1 and arr[mid] == arr[mid - 1]) or \\\n               (mid % 2 == 0 and arr[mid] == arr[mid + 1]):\n                # Move to the right half\n                low = mid + 1\n            else:\n                # Move to the left half\n                high = mid - 1\n\n        # Dummy return (not reachable if input is valid)\n        return -1\n\n# Driver code\nif __name__ == \"__main__\":\n    # Input array with all elements appearing twice except one\n    arr = [1, 1, 2, 2, 3, 3, 4, 5, 5, 6, 6]\n\n    # Create an object of Solution class\n    obj = Solution()\n\n    # Call the function and store the result\n    ans = obj.singleNonDuplicate(arr)\n\n    # Print the result\n    print(\"The single element is:\", ans)"
