      "patternName": "Binary Search and Divide and Conquer",
      "problemSeq": 7,
      "title": "Assign k cows to stall positions such that the minimum distance between any two cows is maximized.",
      "canonicalName": "Aggressive Cows",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(N \\log N + N \\log(\\max - \\min))$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant Delta: Distance feasibility predicate is monotonic over range $[1, \\text{stall}[N-1] - \\text{stall}[0]]$.\n- Mechanics: Sort stall positions; greedily place cows at coordinates separated by at least $mid$ distance.\n- Edge/Trap: If $k$ cows fit at distance $mid$, record $mid$ and expand search rightwards via $low = mid + 1$.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/aggressive-cows-detailed-solution/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Class to solve Aggressive Cows problem\nclass Solution {\npublic:\n    // Function to check if we can place all cows with at least 'd' distance\n    bool canPlace(vector<int>& stalls, int cows, int d) {\n        // Place first cow at the first stall\n        int count = 1;\n        int lastPos = stalls[0];\n\n        // Loop through all stalls\n        for (int i = 1; i < stalls.size(); i++) {\n            // Check if this stall is at least 'd' away from last placed cow\n            if (stalls[i] - lastPos >= d) {\n                // Place the cow here\n                count++;\n                // Update last placed cow position\n                lastPos = stalls[i];\n            }\n            // If all cows are placed successfully\n            if (count >= cows) return true;\n        }\n        // Return false if we could not place all cows\n        return false;\n    }\n\n    // Function to maximize minimum distance between cows\n    int aggressiveCows(vector<int>& stalls, int cows) {\n        // Sort the stalls\n        sort(stalls.begin(), stalls.end());\n\n        // Define search space\n        int low = 1;\n        int high = stalls.back() - stalls.front();\n        int ans = 0;\n\n        // Apply binary search\n        while (low <= high) {\n            // Find mid distance\n            int mid = low + (high - low) / 2;\n\n            // If placing cows is possible with mid distance\n            if (canPlace(stalls, cows, mid)) {\n                // Store this as potential answer\n                ans = mid;\n                // Try to find larger minimum distance\n                low = mid + 1;\n            }\n            else {\n                // Otherwise try smaller distance\n                high = mid - 1;\n            }\n        }\n        // Return the largest minimum distance\n        return ans;\n    }\n};\n\n// Driver function\nint main() {\n    // Input stalls\n    vector<int> stalls = {1, 2, 8, 4, 9};\n    // Number of cows\n    int cows = 3;\n\n    // Create object\n    Solution obj;\n    // Print result\n    cout << obj.aggressiveCows(stalls, cows) << endl;\n    return 0;\n}",
      "py": "class Solution:\n    # Function to check if cows can be placed with distance d\n    def canPlace(self, stalls, cows, d):\n        # Place first cow at first stall\n        count = 1\n        lastPos = stalls[0]\n\n        # Loop through stalls\n        for i in range(1, len(stalls)):\n            # If stall is at least d away from last placed cow\n            if stalls[i] - lastPos >= d:\n                # Place cow here\n                count += 1\n                # Update last position\n                lastPos = stalls[i]\n            # If all cows placed\n            if count >= cows:\n                return True\n        # Could not place all cows\n        return False\n\n    # Function to maximize minimum distance\n    def aggressiveCows(self, stalls, cows):\n        # Sort stalls\n        stalls.sort()\n\n        # Define search space\n        low = 1\n        high = stalls[-1] - stalls[0]\n        ans = 0\n\n        # Binary search\n        while low <= high:\n            # Find mid distance\n            mid = (low + high) // 2\n\n            # If placement possible\n            if self.canPlace(stalls, cows, mid):\n                # Store answer\n                ans = mid\n                # Try larger distance\n                low = mid + 1\n            else:\n                # Try smaller distance\n                high = mid - 1\n\n        # Return result\n        return ans\n\n\n# Driver code\nstalls = [1, 2, 8, 4, 9]\ncows = 3\nobj = Solution()\nprint(obj.aggressiveCows(stalls, cows))"
