      "id": 43,
      "patternId": 4,
      "patternName": "Binary Search and Divide and Conquer",
      "problemSeq": 8,
      "title": "Find the median value of a row-wise sorted matrix of odd total dimensions.",
      "canonicalName": "Matrix Median",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(R \\log C \\cdot \\log(\\max - \\min))$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant Delta: Binary search over absolute value range $[\\min, \\max]$ rather than matrix index positions.\n- Mechanics: Count elements $\\le mid$ across all rows via binary search; require total count $> (R \\cdot C) / 2$.\n- Edge/Trap: Domain is discrete values, not array elements; converge until $low > high$ where $low$ yields the exact median.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/median-of-row-wise-sorted-matrix/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to count elements less than or equal to mid in a row\n    int countLessEqual(vector<int>& row, int mid) {\n        // Using upper_bound to find count efficiently\n        return upper_bound(row.begin(), row.end(), mid) - row.begin();\n    }\n\n    // Function to find median\n    int findMedian(vector<vector<int>>& matrix) {\n        // Number of rows and columns\n        int rows = matrix.size();\n        int cols = matrix[0].size();\n\n        // Minimum possible element in matrix\n        int low = matrix[0][0];\n\n        // Maximum possible element in matrix\n        int high = matrix[0][cols - 1];\n        for (int i = 1; i < rows; i++) {\n            low = min(low, matrix[i][0]);\n            high = max(high, matrix[i][cols - 1]);\n        }\n\n        // Binary search over the value range\n        while (low < high) {\n            int mid = (low + high) / 2;\n\n            // Count elements ≤ mid\n            int count = 0;\n            for (int i = 0; i < rows; i++) {\n                count += countLessEqual(matrix[i], mid);\n            }\n\n            // If count is less than half, median is greater\n            if (count < (rows * cols + 1) / 2)\n                low = mid + 1;\n            else\n                high = mid;\n        }\n\n        // Final low is the median\n        return low;\n    }\n};\n\nint main() {\n    Solution obj;\n    vector<vector<int>> matrix = {\n        {1, 3, 5},\n        {2, 6, 9},\n        {3, 6, 9}\n    };\n    cout << \"Median: \" << obj.findMedian(matrix) << endl;\n    return 0;\n}",
      "py": "import bisect\n\nclass Solution:\n    # Function to count elements <= mid using bisect\n    def countLessEqual(self, row, mid):\n        return bisect.bisect_right(row, mid)\n\n    # Function to find median\n    def findMedian(self, matrix):\n        rows = len(matrix)\n        cols = len(matrix[0])\n\n        # Get the smallest and largest elements\n        low = min(row[0] for row in matrix)\n        high = max(row[-1] for row in matrix)\n\n        # Binary search on value space\n        while low < high:\n            mid = (low + high) // 2\n            count = 0\n\n            # Count elements ≤ mid\n            for row in matrix:\n                count += self.countLessEqual(row, mid)\n\n            if count < (rows * cols + 1) // 2:\n                low = mid + 1\n            else:\n                high = mid\n\n        return low\n\n# Driver code\nmatrix = [\n    [1, 3, 5],\n    [2, 6, 9],\n    [3, 6, 9]\n]\nobj = Solution()\nprint(\"Median:\", obj.findMedian(matrix))"
