      "title": "Find the median of two sorted arrays of lengths m and n in logarithmic time.",
      "canonicalName": "Median of 2 sorted arrays",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(\\log(\\min(m, n)))$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant Delta: Partition both arrays simultaneously such that left half contains $\\lfloor (m + n + 1) / 2 \\rfloor$ elements.\n- Mechanics: Binary search partition cut $i$ on smaller array; compute cut $j$ and verify $\\max(L_1, L_2) \\le \\min(R_1, R_2)$.\n- Edge/Trap: Always bisect the smaller array to guarantee $O(\\log(\\min(m, n)))$ and prevent negative partition indices.",
      "leetcode": "",
      "tuf": "",
      "cpp": "#include <vector>\n#include <algorithm>\n#include <climits>\n\nclass Solution {\npublic:\n    double findMedianSortedArrays(std::vector<int>& nums1, std::vector<int>& nums2) {\n        // Ensure binary search is performed on the smaller array\n        if (nums1.size() > nums2.size()) {\n            return findMedianSortedArrays(nums2, nums1);\n        }\n\n        int m = nums1.size();\n        int n = nums2.size();\n        int low = 0, high = m;\n        int leftTotal = (m + n + 1) / 2;\n\n        while (low <= high) {\n            int cut1 = low + (high - low) / 2;\n            int cut2 = leftTotal - cut1;\n\n            int l1 = (cut1 == 0) ? INT_MIN : nums1[cut1 - 1];\n            int r1 = (cut1 == m) ? INT_MAX : nums1[cut1];\n\n            int l2 = (cut2 == 0) ? INT_MIN : nums2[cut2 - 1];\n            int r2 = (cut2 == n) ? INT_MAX : nums2[cut2];\n\n            if (l1 <= r2 && l2 <= r1) {\n                // Correct partition found\n                if ((m + n) % 2 == 1) {\n                    return std::max(l1, l2);\n                } else {\n                    return (std::max(l1, l2) + std::min(r1, r2)) / 2.0;\n                }\n            } else if (l1 > r2) {\n                // Too many elements taken from nums1\n                high = cut1 - 1;\n            } else {\n                // Too few elements taken from nums1\n                low = cut1 + 1;\n            }\n        }\n\n        return 0.0;\n    }\n};",
      "py": "class Solution:\n    def findMedianSortedArrays(self, nums1: list[int], nums2: list[int]) -> float:\n        # Ensure binary search is performed on the smaller array\n        if len(nums1) > len(nums2):\n            return self.findMedianSortedArrays(nums2, nums1)\n\n        m, n = len(nums1), len(nums2)\n        low, high = 0, m\n        left_total = (m + n + 1) // 2\n\n        while low <= high:\n            cut1 = (low + high) // 2\n            cut2 = left_total - cut1\n\n            l1 = float('-inf') if cut1 == 0 else nums1[cut1 - 1]\n            r1 = float('inf') if cut1 == m else nums1[cut1]\n\n            l2 = float('-inf') if cut2 == 0 else nums2[cut2 - 1]\n            r2 = float('inf') if cut2 == n else nums2[cut2]\n\n            if l1 <= r2 and l2 <= r1:\n                # Correct partition found\n                if (m + n) % 2 == 1:\n                    return float(max(l1, l2))\n                else:\n                    return (max(l1, l2) + min(r1, r2)) / 2.0\n            elif l1 > r2:\n                # Too many elements taken from nums1\n                high = cut1 - 1\n            else:\n                # Too few elements taken from nums1\n                low = cut1 + 1\n\n        return 0.0"
