      "tuf": "https://takeuforward.org/data-structure/k-th-element-of-two-sorted-arrays/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    int kthElement(vector<int>& a, vector<int>& b, int k) {\n        int m = a.size();\n        int n = b.size();\n\n        // Ensure a is smaller array for optimization\n        if (m > n) {\n            // Swap a and b\n            return kthElement(b, a, k); \n        }\n        \n        // Length of the left half\n        int left = k; \n\n        // Apply binary search\n        int low = max(0, k - n), high = min(k, m);\n        while (low <= high) {\n            int mid1 = (low + high) >> 1;\n            int mid2 = left - mid1;\n\n            // Initialize l1, l2, r1, r2\n            int l1 = (mid1 > 0) ? a[mid1 - 1] : INT_MIN;\n            int l2 = (mid2 > 0) ? b[mid2 - 1] : INT_MIN;\n            int r1 = (mid1 < m) ? a[mid1] : INT_MAX;\n            int r2 = (mid2 < n) ? b[mid2] : INT_MAX;\n\n            // Check if we have found the answer\n            if (l1 <= r2 && l2 <= r1) {\n                return max(l1, l2);\n            } \n            else if (l1 > r2) {\n                // Eliminate the right half\n                high = mid1 - 1;\n            } \n            else {\n                // Eliminate the left half\n                low = mid1 + 1;\n            }\n        }\n        \n         // Dummy return statement \n        return -1;\n    }\n};\n\nint main() {\n    vector<int> a = {2, 3, 6, 7, 9};\n    vector<int> b = {1, 4, 8, 10};\n    int k = 5;\n    \n    //Create an instance of Solution class\n    Solution solution;\n    \n    //Print the answer\n    cout << \"The \" << k << \"-th element of two sorted arrays is: \"\n         << solution.kthElement(a, b, k) << '\\n';\n\n    return 0;\n}",
      "py": "class Solution:\n    def kthElement(self, a, b, k):\n        m = len(a)\n        n = len(b)\n\n        # Ensure a is smaller array for optimization\n        if m > n:\n            # Swap a and b\n            return self.kthElement(b, a, k)\n        \n        # Length of the left half\n        left = k\n\n        # Apply binary search\n        low = max(0, k - n)\n        high = min(k, m)\n        while low <= high:\n            mid1 = (low + high) >> 1\n            mid2 = left - mid1\n\n            # Initialize l1, l2, r1, r2\n            l1 = a[mid1 - 1] if mid1 > 0 else float('-inf')\n            l2 = b[mid2 - 1] if mid2 > 0 else float('-inf')\n            r1 = a[mid1] if mid1 < m else float('inf')\n            r2 = b[mid2] if mid2 < n else float('inf')\n\n            # Check if we have found the answer\n            if l1 <= r2 and l2 <= r1:\n                return max(l1, l2)\n            elif l1 > r2:\n                # Eliminate the right half\n                high = mid1 - 1\n            else:\n                # Eliminate the left half\n                low = mid1 + 1\n        \n        # Dummy return statement\n        return -1\n\na = [2, 3, 6, 7, 9]\nb = [1, 4, 8, 10]\nk = 5\n\n# Create an instance of Solution class\nsolution = Solution()\n\n# Print the answer\nprint(f\"The {k}-th element of two sorted arrays is: {solution.kthElement(a, b, k)}\")"
