      "id": 50,
      "patternId": 5,
      "patternName": "Prefix Aggregations and Hashing",
      "problemSeq": 3,
      "title": "Convert a Roman numeral string into its integer value.",
      "canonicalName": "Roman to Integer",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Prefix-lookahead invariant: subtract value if smaller than successor, else add.\n- Scan left to right, comparing current mapped numeral with the next symbol.\n- Process the final character unconditionally as an addition.",
      "leetcode": "https://leetcode.com/problems/roman-to-integer/",
      "tuf": "https://takeuforward.org/data-structure/roman-numerals-to-integer",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    int romanToInt(string s) {\n        int res = 0;\n\n        // Map of Roman numerals to their integer values\n        unordered_map<char, int> roman = {\n            {'I', 1}, {'V', 5}, {'X', 10},\n            {'L', 50}, {'C', 100}, {'D', 500}, {'M', 1000}\n        };\n\n        // Iterate through the string, except the last character\n        for (int i = 0; i < s.size() - 1; i++) {\n            // Subtract if current numeral is less than the next\n            if (roman[s[i]] < roman[s[i + 1]]) {\n                res -= roman[s[i]];\n            } else {\n                // Otherwise, add the current value\n                res += roman[s[i]];\n            }\n        }\n\n        // Add the value of the last character\n        return res + roman[s.back()];\n    }\n};\n\nint main() {\n    Solution sol;\n    string s = \"MCMXCIV\"; \n    int result = sol.romanToInt(s);\n    \n    // Print the result\n    cout << \"Integer value: \" << result << endl;\n\n    return 0;\n}",
      "py": "class Solution:\n    def romanToInt(self, s: str) -> int:\n        # Create a mapping of Roman numerals to integers\n        roman = {\n            'I': 1, 'V': 5, 'X': 10,\n            'L': 50, 'C': 100, 'D': 500, 'M': 1000\n        }\n        \n        res = 0\n        \n        # Loop through the string, except the last character\n        for i in range(len(s) - 1):\n            # Subtract if current value is less than next\n            if roman[s[i]] < roman[s[i + 1]]:\n                res -= roman[s[i]]\n            else:\n                # Otherwise, add the value\n                res += roman[s[i]]\n        \n        # Add the value of the last character\n        return res + roman[s[-1]]\n\nif __name__ == \"__main__\":\n    sol = Solution()\n    s = \"MCMXCIV\"  \n    result = sol.romanToInt(s)\n    print(\"Integer value:\", result)"
