      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Solution class to find the (r, c) element of Pascal's Triangle\nclass Solution {\npublic:\n    // Function to compute binomial coefficient (nCr)\n    long long findPascalElement(int r, int c) {\n        // Element is C(r-1, c-1)\n        int n = r - 1;\n        int k = c - 1;\n\n        long long result = 1;\n\n        // Compute C(n, k) using iterative formula\n        for (int i = 0; i < k; i++) {\n            result *= (n - i);\n            result /= (i + 1);\n        }\n\n        return result;\n    }\n};\n\nint main() {\n    Solution sol;\n    int r = 5, c = 3;\n    cout << sol.findPascalElement(r, c);\n    return 0;\n}",
      "py": "# Solution class to find the (r, c) element of Pascal's Triangle\nclass Solution:\n    # Function to compute binomial coefficient (nCr)\n    def findPascalElement(self, r, c):\n        # Element is C(r-1, c-1)\n        n = r - 1\n        k = c - 1\n\n        result = 1\n\n        # Compute C(n, k) using iterative formula\n        for i in range(k):\n            result *= (n - i)\n            result //= (i + 1)\n\n        return result\n\n\n# Main code to test the solution\nif __name__ == \"__main__\":\n    sol = Solution()\n    r, c = 5, 3\n    print(sol.findPascalElement(r, c))"
