      "id": 52,
      "patternId": 5,
      "patternName": "Prefix Aggregations and Hashing",
      "problemSeq": 5,
      "title": "Find the element appearing strictly more than $\\lfloor N/2 \\rfloor$ times in an array.",
      "canonicalName": "Majority Element-I",
      "difficulty": "Easy",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Boyer-Moore voting cancels opposing values; majority element maintains net positive balance.\n- Maintain candidate and counter; reassign candidate when counter drops to zero.\n- A second verification pass is unnecessary only when majority existence is guaranteed.",
      "leetcode": "https://leetcode.com/problems/majority-element/",
      "tuf": "https://takeuforward.org/data-structure/find-the-majority-element-that-occurs-more-than-n-2-times/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to find the majority element in an array\n    int majorityElement(vector<int>& nums) {\n        \n        // Size of the given array\n        int n = nums.size();\n        \n        // Count\n        int cnt = 0;\n        \n        // Element\n        int el; \n        \n        // Applying the algorithm\n        for (int i = 0; i < n; i++) {\n            if (cnt == 0) {\n                cnt = 1;\n                el = nums[i];\n            } else if (el == nums[i]) {\n                cnt++;\n            } else {\n                cnt--;\n            }\n        }\n        \n        /* Checking if the stored element\n         is the majority element*/\n        int cnt1 = 0;\n        for (int i = 0; i < n; i++) {\n            if (nums[i] == el) {\n                cnt1++;\n            }\n        }\n        \n        //return element if it is a majority element\n        if (cnt1 > (n / 2)) {\n            return el;\n        }\n        \n        //return -1 if no such element found\n        return -1;\n    }\n};\n\nint main() {\n    vector<int> arr = {2, 2, 1, 1, 1, 2, 2};\n    \n    // Create an instance of Solution class\n    Solution sol;\n\n    int ans = sol.majorityElement(arr);\n    \n    // Print the majority element found\n    cout << \"The majority element is: \" << ans << endl;\n    \n    return 0;\n}",
      "py": "from typing import List\n\nclass Solution:\n    # Function to find the majority element in an array\n    def majorityElement(self, nums: List[int]) -> int:\n        \n        # Size of the given array\n        n = len(nums)\n        \n        # Count\n        cnt = 0\n        \n        # Element\n        el = 0\n        \n        # Applying the algorithm\n        for num in nums:\n            if cnt == 0:\n                cnt = 1\n                el = num\n            elif el == num:\n                cnt += 1\n            else:\n                cnt -= 1\n        \n        \"\"\" Checking if the stored element\n        is the majority element\"\"\"\n        cnt1 = nums.count(el)\n        \n        # Return element if it is a majority element\n        if cnt1 > (n // 2):\n            return el\n        \n        # Return -1 if no such element found\n        return -1\n\n# Test the solution with the given example\narr = [2, 2, 1, 1, 1, 2, 2]\n\n# Create an instance of Solution class\nsol = Solution()\n\nans = sol.majorityElement(arr)\n\n# Print the majority element found\nprint(f\"The majority element is: {ans}\")"
