      "patternName": "Prefix Aggregations and Hashing",
      "problemSeq": 6,
      "title": "Find all elements in an array appearing strictly more than $\\lfloor N/3 \\rfloor$ times.",
      "canonicalName": "Majority Element-II",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Extended Boyer-Moore: tracking up to two distinct candidates preserves $> \\lfloor N/3 \\rfloor$ frequencies.\n- Maintain two candidate-counter pairs, decrementing both only on a mismatch with both.\n- A second verification pass is strictly mandatory to confirm counts exceed $\\lfloor N/3 \\rfloor$.",
      "leetcode": "https://leetcode.com/problems/majority-element-ii/",
      "tuf": "https://takeuforward.org/data-structure/majority-elementsn-3-times-find-the-elements-that-appears-more-than-n-3-times-in-the-array/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to find majority elements in an array\n    vector<int> majorityElementTwo(vector<int>& nums) {\n        \n        // Size of the array\n        int n = nums.size(); \n\n        // Counts for elements el1 and el2\n        int cnt1 = 0, cnt2 = 0;\n        \n        /*Initialize Element 1 and \n        Element 2 with INT_MIN value*/\n        int el1 = INT_MIN, el2 = INT_MIN;\n\n        /*Find the potential candidates using\n        Boyer Moore's Voting Algorithm*/\n        for (int i = 0; i < n; i++) {\n            \n            if (cnt1 == 0 && el2 != nums[i]) {\n                cnt1 = 1;\n                // Initialize el1 as nums[i]\n                el1 = nums[i]; \n            }\n            else if (cnt2 == 0 && el1 != nums[i]) {\n                cnt2 = 1;\n                // Initialize el2 as nums[i]\n                el2 = nums[i]; \n            } \n            else if (nums[i] == el1) {\n                // Increment count for el1\n                cnt1++;\n            } \n            else if (nums[i] == el2) {\n                // Increment count for el2\n                cnt2++; \n            } \n            else {\n                // Decrement count for el1\n                cnt1--; \n                 // Decrement count for el2\n                cnt2--;\n            }\n        }\n\n        //Validate the candidates by counting occurrences in nums\n        //Reset counts for el1 and el2\n        cnt1 = 0, cnt2 = 0; \n        \n        for (int i = 0; i < n; i++) {\n            if (nums[i] == el1) {\n                // Count occurrences of el1\n                cnt1++; \n            }\n            if (nums[i] == el2) {\n                 // Count occurrences of el2\n                cnt2++;\n            }\n        }\n\n        /* Determine the minimum count\n        required for a majority element*/\n        int mini = n / 3 + 1;\n        \n        // List of answers\n        vector<int> result; \n\n        /*Add elements to the result vector\n        if they appear more than n/3 times*/\n        if (cnt1 >= mini) {\n            result.push_back(el1);\n        }\n        if (cnt2 >= mini && el1 != el2) {\n            // Avoid adding duplicate if el1 == el2\n            result.push_back(el2); \n        }\n\n        // Uncomment the following line if you want to sort the answer array\n        // sort(result.begin(), result.end()); // TC --> O(2*log2) ~ O(1);\n\n        //return the majority elements\n        return result;\n    }\n};\n\nint main() {\n    vector<int> arr = {11, 33, 33, 11, 33, 11};\n    \n    // Create an instance of Solution class\n    Solution sol;\n  \n    vector<int> ans = sol.majorityElementTwo(arr);\n    \n    // Print the majority elements found\n    cout << \"The majority elements are: \";\n    for (auto it : ans) {\n        cout << it << \" \";\n    }\n    cout << \"\\n\";\n    \n    return 0;\n}",
      "py": "from typing import List\n\nclass Solution:\n    # Function to find majority elements in an array\n    def majorityElementTwo(self, nums: List[int]) -> List[int]:\n        \n        # Size of the array\n        n = len(nums)\n\n        # Counts for elements el1 and el2\n        cnt1, cnt2 = 0, 0\n        \n        \"\"\"Initialize Element 1 and \n        Element 2 with INT_MIN value\"\"\"\n        el1, el2 = float('-inf'), float('-inf')\n\n        \"\"\"Find the potential candidates using\n        Boyer Moore's Voting Algorithm\"\"\"\n        for num in nums:\n            if cnt1 == 0 and el2 != num:\n                cnt1 = 1\n                # Initialize el1 as num\n                el1 = num \n            elif cnt2 == 0 and el1 != num:\n                cnt2 = 1\n                # Initialize el2 as num\n                el2 = num \n            elif num == el1:\n                # Increment count for el1\n                cnt1 += 1\n            elif num == el2:\n                # Increment count for el2\n                cnt2 += 1 \n            else:\n                # Decrement count for el1\n                cnt1 -= 1 \n                 # Decrement count for el2\n                cnt2 -= 1\n\n        #Validate the candidates by counting occurrences in nums\n        #Reset counts for el1 and el2\n        cnt1, cnt2 = 0, 0 \n        \n        for num in nums:\n            if num == el1:\n                # Count occurrences of el1\n                cnt1 += 1 \n            if num == el2:\n                 # Count occurrences of el2\n                cnt2 += 1\n\n        \"\"\" Determine the minimum count\n        required for a majority element\"\"\"\n        mini = n // 3 + 1\n        \n        # List of answers\n        result = []\n\n        \"\"\"Add elements to the result list\n        if they appear more than n/3 times\"\"\"\n        if cnt1 >= mini:\n            result.append(el1)\n            \n        if cnt2 >= mini and el1 != el2:\n            # Avoid adding duplicate if el1 == el2\n            result.append(el2)\n\n        # Uncomment the following line if you want to sort the answer list\n        # result.sort() # TC --> O(2*log2) ~ O(1);\n\n        #return the majority elements\n        return result\n\nif __name__ == \"__main__\":\n    arr = [11, 33, 33, 11, 33, 11]\n    \n    # Create an instance of Solution class\n    sol = Solution()\n  \n    ans = sol.majorityElementTwo(arr)\n    \n    # Print the majority elements found\n    print(\"The majority elements are:\", *ans)"
