      "title": "Find the missing and repeating numbers in an array of size $N$ containing values from $1$ to $N$.",
      "canonicalName": "Find the repeating and missing number",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant Delta: Map values to indices using sign inversion, or resolve via linear and quadratic sum differences.\n- Mechanics: Compute $S - S_n = A - B$ and $S^2 - S_n^2 = A^2 - B^2$; solve simultaneous equations for $A$ and $B$.\n- Edge/Trap: Sum of squares exceeds 32-bit integer limits; cast calculations to 64-bit integers.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/find-the-repeating-and-missing-numbers/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to find repeating and missing numbers\n    vector<int> findMissingRepeatingNumbers(vector<int>& nums) {\n        \n        // Size of the array\n        long long n = nums.size(); \n\n        // Sum of first n natural numbers\n        long long SN = (n * (n + 1)) / 2;\n        \n        // Sum of squares of first n natural numbers\n        long long S2N = (n * (n + 1) * (2 * n + 1)) / 6;\n\n        /*Calculate actual sum (S) and sum \n        of squares (S2) of array elements*/\n        long long S = 0, S2 = 0;\n        for (int i = 0; i < n; i++) {\n            S += nums[i];\n            S2 += (long long)nums[i] * (long long)nums[i];\n        }\n\n        //Compute the difference values\n        long long val1 = S - SN; \n        \n        // S2 - S2n = X^2 - Y^2\n        long long val2 = S2 - S2N; \n\n        //Calculate X + Y using X + Y = (X^2 - Y^2) / (X - Y)\n        val2 = val2 / val1;\n\n        /* Calculate X and Y from X + Y and X - Y\n         X = ((X + Y) + (X - Y)) / 2\n         Y = X - (X - Y)*/\n        long long x = (val1 + val2) / 2;\n        long long y = x - val1;\n\n        // Return the results as {repeating, missing}\n        return {(int)x, (int)y};\n    }\n};\n\nint main() {\n    vector<int> nums = {3, 1, 2, 5, 4, 6, 7, 5};\n    \n    // Create an instance of Solution class\n    Solution sol;\n\n    vector<int> result = sol.findMissingRepeatingNumbers(nums);\n    \n    // Print the repeating and missing numbers found\n    cout << \"The repeating and missing numbers are: {\" << result[0] << \", \" << result[1] << \"}\\n\";\n    \n    return 0;\n}",
      "py": "class Solution:\n    # Function to find repeating and missing numbers\n    def findMissingRepeatingNumbers(self, nums):\n        \n        # Size of the array\n        n = len(nums)\n\n        # Sum of first n natural numbers\n        SN = (n * (n + 1)) // 2\n\n        # Sum of squares of first n natural numbers\n        S2N = (n * (n + 1) * (2 * n + 1)) // 6\n\n        \"\"\" Calculate actual sum (S) and sum \n            of squares (S2) of array elements \"\"\"\n        S = 0\n        S2 = 0\n        for num in nums:\n            S += num\n            S2 += num * num\n\n        # Compute the difference values\n        val1 = S - SN\n\n        # S2 - S2n = X^2 - Y^2\n        val2 = S2 - S2N\n\n        # Calculate X + Y using X + Y = (X^2 - Y^2) / (X - Y)\n        val2 = val2 // val1\n\n        \"\"\" Calculate X and Y from X + Y and X - Y\n            X = ((X + Y) + (X - Y)) / 2\n            Y = X - (X - Y) \"\"\"\n        x = (val1 + val2) // 2\n        y = x - val1\n\n        # Return the results as [repeating, missing]\n        return [int(x), int(y)]\n\nnums = [3, 1, 2, 5, 4, 6, 7, 5]\n\n# Create an instance of Solution class\nsol = Solution()\n\nresult = sol.findMissingRepeatingNumbers(nums)\n\n# Print the repeating and missing numbers found\nprint(f\"The repeating and missing numbers are: {{{result[0]}, {result[1]}}}\")"
