      "title": "Design and implement a Least Recently Used (LRU) cache with $\\mathcal{O}(1)$ get and put operations.",
      "canonicalName": "LRU Cache",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(1)$ | Space Complexity: $\\mathcal{O}(C)$",
      "mantra": "- Invariant Delta: Hash map maps keys to doubly linked list nodes for $\\mathcal{O}(1)$ splicing and repositioning.\n- Mechanics: On access, unlink node and insert directly after dummy head; on eviction, remove node before dummy tail.\n- Edge/Trap: Use permanent dummy head and tail sentinel nodes to eliminate null checks during link rewiring.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/program-for-least-recently-used-lru-page-replacement-algorithm",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Class representing the LRU Cache\nclass LRUCache {\npublic:\n    // Doubly linked list node class\n    class Node {\n    public:\n        int key;\n        int val;\n        Node* next;\n        Node* prev;\n        // Constructor to initialize node\n        Node(int _key, int _val) {\n            key = _key;\n            val = _val;\n        }\n    };\n\n    // Head and tail dummy nodes\n    Node* head = new Node(-1, -1);\n    Node* tail = new Node(-1, -1);\n\n    // Capacity of cache\n    int cap;\n    // Hash map to store key-node mapping\n    unordered_map<int, Node*> m;\n\n    // Constructor to initialize LRU cache\n    LRUCache(int capacity) {\n        cap = capacity;\n        head->next = tail;\n        tail->prev = head;\n    }\n\n    // Function to add a node right after head\n    void addNode(Node* newNode) {\n        Node* temp = head->next;\n        newNode->next = temp;\n        newNode->prev = head;\n        head->next = newNode;\n        temp->prev = newNode;\n    }\n\n    // Function to remove a given node from list\n    void deleteNode(Node* delNode) {\n        Node* delPrev = delNode->prev;\n        Node* delNext = delNode->next;\n        delPrev->next = delNext;\n        delNext->prev = delPrev;\n    }\n\n    // Function to get value from cache\n    int get(int key_) {\n        // If key exists in cache\n        if (m.find(key_) != m.end()) {\n            Node* resNode = m[key_];\n            int res = resNode->val;\n            // Remove old mapping\n            m.erase(key_);\n            // Move accessed node to front\n            deleteNode(resNode);\n            addNode(resNode);\n            // Update map\n            m[key_] = head->next;\n            return res;\n        }\n        // If not found\n        return -1;\n    }\n\n    // Function to put key-value into cache\n    void put(int key_, int value) {\n        // If key already exists\n        if (m.find(key_) != m.end()) {\n            Node* existingNode = m[key_];\n            m.erase(key_);\n            deleteNode(existingNode);\n        }\n        // If capacity reached\n        if (m.size() == cap) {\n            m.erase(tail->prev->key);\n            deleteNode(tail->prev);\n        }\n        // Insert new node at front\n        addNode(new Node(key_, value));\n        m[key_] = head->next;\n    }\n};\n\n// Driver code\nint main() {\n    // Create cache with capacity 2\n    LRUCache cache(2);\n\n    // Put values in cache\n    cache.put(1, 1);\n    cache.put(2, 2);\n\n    // Get value for key 1\n    cout << cache.get(1) << endl; \n\n    // Insert another key (evicts key 2)\n    cache.put(3, 3);\n\n    // Key 2 should be evicted\n    cout << cache.get(2) << endl; \n\n    // Insert another key (evicts key 1)\n    cache.put(4, 4);\n\n    // Key 1 should be evicted\n    cout << cache.get(1) << endl; \n\n    // Key 3 should be present\n    cout << cache.get(3) << endl; \n\n    // Key 4 should be present\n    cout << cache.get(4) << endl; \n\n    return 0;\n}",
      "py": "# Class representing the LRU Cache\nclass LRUCache:\n    # Doubly linked list node class\n    class Node:\n        # Constructor to initialize node\n        def __init__(self, _key, _val):\n            self.key = _key\n            self.val = _val\n            self.next = None\n            self.prev = None\n\n    # Constructor to initialize LRU cache\n    def __init__(self, capacity: int):\n        # Head and tail dummy nodes\n        self.head = self.Node(-1, -1)\n        self.tail = self.Node(-1, -1)\n        self.head.next = self.tail\n        self.tail.prev = self.head\n\n        # Capacity of cache\n        self.cap = capacity\n        # Hash map to store key-node mapping\n        self.m = {}\n\n    # Function to add a node right after head\n    def addNode(self, newNode):\n        temp = self.head.next\n        newNode.next = temp\n        newNode.prev = self.head\n        self.head.next = newNode\n        temp.prev = newNode\n\n    # Function to remove a given node from list\n    def deleteNode(self, delNode):\n        delPrev = delNode.prev\n        delNext = delNode.next\n        delPrev.next = delNext\n        delNext.prev = delPrev\n\n    # Function to get value from cache\n    def get(self, key_):\n        # If key exists in cache\n        if key_ in self.m:\n            resNode = self.m[key_]\n            res = resNode.val\n            # Remove old mapping\n            del self.m[key_]\n            # Move accessed node to front\n            self.deleteNode(resNode)\n            self.addNode(resNode)\n            # Update map\n            self.m[key_] = self.head.next\n            return res\n        # If not found\n        return -1\n\n    # Function to put key-value into cache\n    def put(self, key_, value):\n        # If key already exists\n        if key_ in self.m:\n            existingNode = self.m[key_]\n            del self.m[key_]\n            self.deleteNode(existingNode)\n        # If capacity reached\n        if len(self.m) == self.cap:\n            del self.m[self.tail.prev.key]\n            self.deleteNode(self.tail.prev)\n        # Insert new node at front\n        self.addNode(self.Node(key_, value))\n        self.m[key_] = self.head.next\n\n\n# Driver code\nif __name__ == \"__main__\":\n    # Create cache with capacity 2\n    cache = LRUCache(2)\n\n    # Put values in cache\n    cache.put(1, 1)\n    cache.put(2, 2)\n\n    # Get value for key 1\n    print(cache.get(1))\n\n    # Insert another key (evicts key 2)\n    cache.put(3, 3)\n\n    # Key 2 should be evicted\n    print(cache.get(2))\n\n    # Insert another key (evicts key 1)\n    cache.put(4, 4)\n\n    # Key 1 should be evicted\n    print(cache.get(1))\n\n    # Key 3 should be present\n    print(cache.get(3))\n\n    # Key 4 should be present\n    print(cache.get(4))"
