      "bounds": "Time Complexity: $\\mathcal{O}(N \\cdot 2^N)$ | Space Complexity: $\\mathcal{O}(N)$",
      "mantra": "- Sort input array; append state vector to results at every recursive node invocation.\n- Skip loop index when $i > start$ and $nums[i] == nums[i - 1]$ to suppress redundant sibling branches.\n- Ensure identical values can still be consumed across recursion depth, but never across breadth.",
      "leetcode": "https://leetcode.com/problems/subsets-ii/",
      "tuf": "https://takeuforward.org/data-structure/subset-ii-print-all-the-unique-subsets/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to generate all unique subsets\n    void backtrack(int start, vector<int>& nums, vector<int>& current, vector<vector<int>>& result) {\n        // Add the current subset to result\n        result.push_back(current);\n\n        // Iterate over the array from 'start' index\n        for (int i = start; i < nums.size(); i++) {\n            // Skip duplicates: if current number is same as previous and not at the start index\n            if (i > start && nums[i] == nums[i - 1]) continue;\n\n            // Include nums[i] in current subset\n            current.push_back(nums[i]);\n\n            // Recurse for next index\n            backtrack(i + 1, nums, current, result);\n\n            // Backtrack: remove last added element\n            current.pop_back();\n        }\n    }\n\n    // Main function to get unique subsets\n    vector<vector<int>> subsetsWithDup(vector<int>& nums) {\n        // Sort the array to handle duplicates\n        sort(nums.begin(), nums.end());\n\n        vector<vector<int>> result;\n        vector<int> current;\n\n        // Start backtracking from index 0\n        backtrack(0, nums, current, result);\n\n        return result;\n    }\n};\n\n// Driver code\nint main() {\n    Solution obj;\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) cin >> nums[i];\n\n    vector<vector<int>> ans = obj.subsetsWithDup(nums);\n    for (auto subset : ans) {\n        cout << \"[\";\n        for (int i = 0; i < subset.size(); i++) {\n            cout << subset[i];\n            if (i != subset.size() - 1) cout << \",\";\n        }\n        cout << \"] \";\n    }\n    cout << endl;\n    return 0;\n}",
      "py": "class Solution:\n    # Function to generate all unique subsets\n    def backtrack(self, start, nums, current, result):\n        # Add a copy of current subset\n        result.append(list(current))\n\n        # Iterate from 'start' index\n        for i in range(start, len(nums)):\n            # Skip duplicates\n            if i > start and nums[i] == nums[i - 1]:\n                continue\n\n            # Include nums[i]\n            current.append(nums[i])\n\n            # Recurse\n            self.backtrack(i + 1, nums, current, result)\n\n            # Backtrack\n            current.pop()\n\n    def subsetsWithDup(self, nums):\n        nums.sort()  # Sort to handle duplicates\n        result = []\n        self.backtrack(0, nums, [], result)\n        return result\n\n\n# Driver code\nif __name__ == \"__main__\":\n    n = int(input())\n    nums = list(map(int, input().split()))\n    obj = Solution()\n    ans = obj.subsetsWithDup(nums)\n    for subset in ans:\n        print(subset, end=\" \")\n    print()"
