      "bounds": "Time Complexity: $\\mathcal{O}(N^{target / \\min(nums)})$ | Space Complexity: $\\mathcal{O}(target / \\min(nums))$",
      "mantra": "- Unbounded reuse invariant: recurse on the identical index $i$ while reducing remaining target by $nums[i]$.\n- Terminate branch when $target == 0$; prune immediately when $target < 0$ or index reaches $N$.\n- Sorting input candidates allows breaking out of loop early whenever $nums[i] > target$.",
      "leetcode": "https://leetcode.com/problems/combination-sum/",
      "tuf": "https://takeuforward.org/data-structure/combination-sum-1/",
      "cpp": "#include<bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\n  public:\n    // Function to find all combinations of numbers that sum up to the target\n    void findCombination(int ind, int target, vector<int>& arr, vector<vector<int>>& ans, vector<int>& ds) {\n        // Base case: if we have considered all elements in the array\n        if (ind == arr.size()) {\n            // If the target is zero, we have found a valid combination\n            if (target == 0) {\n                ans.push_back(ds);  // Add the current combination to the result\n            }\n            return;\n        }\n\n        // Recursive case: pick the element if it's less than or equal to the target\n        if (arr[ind] <= target) {\n            ds.push_back(arr[ind]);  // Add the current element to the combination\n            findCombination(ind, target - arr[ind], arr, ans, ds);  // Continue with the same index to allow repeated elements\n            ds.pop_back();  // Backtrack by removing the last added element\n        }\n\n        // Skip the current element and move to the next index\n        findCombination(ind + 1, target, arr, ans, ds);\n    }\n\n  public:\n    // Main function to get all combinations\n    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {\n        vector<vector<int>> ans;  // To store the result\n        vector<int> ds;  // To store a current combination\n        findCombination(0, target, candidates, ans, ds);  // Start the recursive search\n        return ans;  // Return all valid combinations\n    }\n};\n\nint main() {\n    Solution obj;\n    vector<int> v {2, 3, 6, 7};  // Candidate numbers\n    int target = 7;  // Target sum\n\n    // Get all combinations\n    vector<vector<int>> ans = obj.combinationSum(v, target);\n\n    // Output the combinations\n    cout << \"Combinations are: \" << endl;\n    for (int i = 0; i < ans.size(); i++) {\n        for (int j = 0; j < ans[i].size(); j++) {\n            cout << ans[i][j] << \" \";  // Print each element of the combination\n        }\n        cout << endl;  // Print a newline after each combination\n    }\n\n    return 0;\n}",
      "py": "class Solution:\n\n    # Function to find all combinations recursively\n    def findCombination(self, ind, target, arr, ans, ds):\n        # Base case: if we have considered all elements in the array\n        if ind == len(arr):\n            # If the target is zero, we have found a valid combination\n            if target == 0:\n                ans.append(list(ds))  # Add the current combination to the result\n            return\n\n        # Recursive case: pick the element if it's less than or equal to the target\n        if arr[ind] <= target:\n            ds.append(arr[ind])  # Add the current element to the combination\n            self.findCombination(ind, target - arr[ind], arr, ans, ds)  # Continue with the same index to allow repeated elements\n            ds.pop()  # Backtrack by removing the last added element\n\n        # Skip the current element and move to the next index\n        self.findCombination(ind + 1, target, arr, ans, ds)\n\n    # Main function to get all combinations\n    def combinationSum(self, candidates, target):\n        ans = []  # To store the result\n        ds = []  # To store a current combination\n        self.findCombination(0, target, candidates, ans, ds)  # Start the recursive search\n        return ans  # Return all valid combinations\n\n# Driver code\nif __name__ == \"__main__\":\n    obj = Solution()\n    v = [2, 3, 6, 7]  # Candidate numbers\n    target = 7  # Target sum\n\n    # Get all combinations\n    ans = obj.combinationSum(v, target)\n\n    # Output the combinations\n    print(\"Combinations are: \")\n    for combination in ans:\n        print(\" \".join(map(str, combination)))  # Print each element of the combination"
