      "problemSeq": 1,
      "title": "Maximize the number of children receiving a cookie where child i requires minimum size g[i] and each cookie has size s[j].",
      "canonicalName": "Assign Cookies",
      "difficulty": "Easy",
      "bounds": "Time Complexity: $\\mathcal{O}(N \\log N + M \\log M)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Invariant Delta: Dual monotonic sweep pairing the smallest sufficient cookie to the smallest greedy factor.\n- Mechanics: Sort both arrays; advance the cookie pointer unconditionally, advancing the child pointer only on match.\n- Edge/Trap: Cookie array exhaustion before satisfying all children; loop terminates when either pointer hits boundary.",
      "leetcode": "https://leetcode.com/problems/assign-cookies/",
      "tuf": "https://takeuforward.org/data-structure/assign-cookies",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to find the maximum number of content students\n    int findContentChildren(vector<int>& student, vector<int>& cookie) {\n        // Sort both arrays to apply the greedy strategy\n        sort(student.begin(), student.end());\n        sort(cookie.begin(), cookie.end());\n\n        int studentIndex = 0; \n        int cookieIndex = 0;  \n\n        // Try to assign cookies until any one list is fully processed\n        while (studentIndex < student.size() && cookieIndex < cookie.size()) {\n            // If the cookie satisfies the student's greed\n            if (cookie[cookieIndex] >= student[studentIndex]) {\n                studentIndex++; \n            }\n            // Move to next cookie in both cases\n            cookieIndex++; \n        }\n\n        // Number of students satisfied is equal to studentIndex\n        return studentIndex;\n    }\n};\n\nint main() {\n    vector<int> student = {1, 2, 3};\n    vector<int> cookie = {1, 1};\n\n    // Create Solution object\n    Solution solver;\n\n    // Get the number of content students and print it\n    int result = solver.findContentChildren(student, cookie);\n    cout << \"Maximum number of content students: \" << result << endl;\n\n    return 0;\n}",
      "py": "class Solution:\n    # Function to find the maximum number of content students\n    def findContentChildren(self, student, cookie):\n        # Sort both arrays to apply the greedy strategy\n        student.sort()\n        cookie.sort()\n\n        studentIndex = 0\n        cookieIndex = 0\n\n        # Try to assign cookies until any one list is fully processed\n        while studentIndex < len(student) and cookieIndex < len(cookie):\n            # If the cookie satisfies the student's greed\n            if cookie[cookieIndex] >= student[studentIndex]:\n                studentIndex += 1\n            # Move to next cookie in both cases\n            cookieIndex += 1\n\n        # Number of students satisfied is equal to studentIndex\n        return studentIndex\n\n# Main execution\nstudent = [1, 2, 3]\ncookie = [1, 1]\n\n# Create Solution object\nsolver = Solution()\n\n# Get the number of content students and print it\nresult = solver.findContentChildren(student, cookie)\nprint(\"Maximum number of content students:\", result)"
