      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Node structure for\n// the binary tree\nstruct Node {\n    int data;\n    Node* left;\n    Node* right;\n    // Constructor to initialize\n    // the node with a value\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\n// Solution class containing traversal functions\nclass Solution {\npublic:\n    // Function to perform preorder traversal\n    // of the tree and store values in 'arr'\n    void preorder(Node* root, vector<int> &arr){\n        // If the current node is NULL\n        // (base case for recursion), return\n        if(root == nullptr){\n            return;\n        }\n        // Push the current node's\n        // value into the vector\n        arr.push_back(root->data);\n        // Recursively traverse\n        // the left subtree\n        preorder(root->left, arr);\n        // Recursively traverse \n        // the right subtree\n        preorder(root->right, arr);\n    }\n\n    // Function to initiate preorder traversal\n    // and return the resulting vector\n    vector<int> preOrder(Node* root){\n        // Create an empty vector to\n        // store preorder traversal values\n        vector<int> arr;\n        // Call the preorder traversal function\n        preorder(root, arr);\n        // Return the resulting vector\n        // containing preorder traversal values\n        return arr;\n    }\n};\n\n// Main function\nint main()\n{\n    // Creating a sample binary tree\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->right = new Node(3);\n    root->left->left = new Node(4);\n    root->left->right = new Node(5);\n\n    // Create object of Solution class\n    Solution sol;\n\n    // Getting preorder traversal\n    vector<int> result = sol.preOrder(root);\n\n    // Displaying the preorder traversal result\n    cout << \"Preorder Traversal: \";\n    // Output each value in the\n    // preorder traversal result\n    for(int val : result) {\n        cout << val << \" \";\n    }\n    cout << endl;\n\n    return 0;\n}",
      "py": "# Node structure for\n# the binary tree\nclass Node:\n    # Constructor to initialize\n    # the node with a value\n    def __init__(self, val):\n        self.data = val\n        self.left = None\n        self.right = None\n\n# Solution class to perform preorder traversal\nclass Solution:\n\n    # Function to perform preorder traversal\n    # of the tree and store values in 'arr'\n    def preorder(self, root, arr):\n        # If the current node is NULL\n        # (base case for recursion), return\n        if root is None:\n            return\n        # Push the current node's\n        # value into the vector\n        arr.append(root.data)\n        # Recursively traverse\n        # the left subtree\n        self.preorder(root.left, arr)\n        # Recursively traverse \n        # the right subtree\n        self.preorder(root.right, arr)\n\n    # Function to initiate preorder traversal\n    # and return the resulting list\n    def preOrder(self, root):\n        # Create an empty list to\n        # store preorder traversal values\n        arr = []\n        # Call the preorder traversal function\n        self.preorder(root, arr)\n        # Return the resulting list\n        # containing preorder traversal values\n        return arr\n\n# Main function\nif __name__ == \"__main__\":\n\n    # Creating a sample binary tree\n    root = Node(1)\n    root.left = Node(2)\n    root.right = Node(3)\n    root.left.left = Node(4)\n    root.left.right = Node(5)\n\n    # Getting preorder traversal\n    sol = Solution()\n    result = sol.preOrder(root)\n\n    # Displaying the preorder traversal result\n    print(\"Preorder Traversal: \", end=\"\")\n    # Output each value in the\n    # preorder traversal result\n    for val in result:\n        print(val, end=\" \")\n    print()"
