      "mantra": "- Left-Right-Root traversal visits all descendants prior to parent, forming the basis of subtree DP.\n- Use two stacks, or one stack tracking a last_visited pointer to detect upward returns.\n- Ensure right child is fully processed before popping and recording current root.",
      "leetcode": "https://leetcode.com/problems/binary-tree-postorder-traversal/",
      "tuf": "https://takeuforward.org/data-structure/iterative-postorder-traversal-of-binary-tree-using-2-stack",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Node structure for the binary tree\nstruct Node {\n    int data;   // Value of the node\n    Node* left; // Pointer to the left child\n    Node* right; // Pointer to the right child\n    \n    // Constructor to initialize the node with a value\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\n// Function to return the postOrder traversal of a binary tree using two stacks\nvector<int> postOrder(Node* root) {\n    vector<int> postorder; // Vector to store the postorder traversal\n\n    // If the tree is empty, return an empty traversal\n    if(root == NULL){\n        return postorder;\n    }\n\n    // Two stacks for iterative traversal\n    stack<Node*> st1, st2;\n\n    // Push the root node onto the first stack\n    st1.push(root);\n\n    // Iterative traversal to populate st2 with nodes in postorder\n    while(!st1.empty()){\n        // Get the top node from st1\n        root = st1.top();\n        st1.pop();\n\n        // Push the node onto st2\n        st2.push(root);\n\n        // Push left child onto st1 if exists\n        if(root->left != NULL){\n            st1.push(root->left);\n        }\n\n        // Push right child onto st1 if exists\n        if(root->right != NULL){\n            st1.push(root->right);\n        }\n    }\n\n    // Populate the postorder traversal vector by popping st2\n    while(!st2.empty()){\n        postorder.push_back(st2.top()->data);\n        st2.pop();\n    }\n\n    // Return the postorder traversal\n    return postorder;\n}\n\n// Function to print the elements of a vector\nvoid printVector(const vector<int>& vec) {\n    // Iterate through the vector and print each element\n    for (int num : vec) {\n        cout << num << \" \";\n    }\n    cout << endl;\n}\n\n// Main function\nint main()\n{\n    // Creating a sample binary tree\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->right = new Node(3);\n    root->left->left = new Node(4);\n    root->left->right = new Node(5);\n\n    // Getting postorder traversal\n    vector<int> result = postOrder(root);\n\n    // Printing the postorder traversal result\n    cout << \"Postorder traversal: \";\n    printVector(result);\n\n    return 0;\n}",
      "py": "# Define a TreeNode class for the binary tree\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x  # The value of the node\n        self.left = None  # Pointer to the left child\n        self.right = None  # Pointer to the right child\n\n# Function to perform postorder traversal of a binary tree iteratively\ndef postOrder(root):\n    postorder = []  # List to store the postorder traversal result\n\n    # If the tree is empty, return an empty traversal\n    if root is None:\n        return postorder\n\n    # Two stacks for iterative traversal\n    st1 = []  # First stack\n    st2 = []  # Second stack to store nodes in postorder\n\n    # Push the root node onto the first stack\n    st1.append(root)\n\n    # Iterative traversal to populate st2 with nodes in postorder\n    while st1:\n        root = st1.pop()  # Get the top node from st1\n        st2.append(root)  # Push the node onto st2\n\n        # Push left child onto st1 if exists\n        if root.left:\n            st1.append(root.left)\n\n        # Push right child onto st1 if exists\n        if root.right:\n            st1.append(root.right)\n\n    # Populate the postorder traversal list by popping st2\n    while st2:\n        postorder.append(st2.pop().val)  # Add the node's value to the postorder result\n\n    # Return the postorder traversal result\n    return postorder\n\n# Driver code\nif __name__ == \"__main__\":\n    # Creating a sample binary tree\n    root = TreeNode(1)\n    root.left = TreeNode(2)\n    root.right = TreeNode(3)\n    root.left.left = TreeNode(4)\n    root.left.right = TreeNode(5)\n\n    # Getting the postorder traversal\n    result = postOrder(root)\n\n    # Displaying the postorder traversal result\n    print(\"Postorder traversal:\", result)"
