      "mantra": "- Recursive mirror check verifies left subtree is a structural reflection of right subtree.\n- Evaluate helper function on paired nodes: left.val == right.val, comparing (t1.left, t2.right) and (t1.right, t2.left).\n- Both branches must return null simultaneously for valid reflection symmetry.",
      "leetcode": "https://leetcode.com/problems/symmetric-tree/",
      "tuf": "https://takeuforward.org/data-structure/check-for-symmetrical-binary-tree/",
      "cpp": "#include <iostream>\nusing namespace std;\n\n// Node structure for the binary tree\nstruct Node {\n    int data;\n    Node* left;\n    Node* right;\n    // Constructor to initialize\n    // the node with a value\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\nclass Solution {\nprivate:\n    // Function to check if\n    // two subtrees are symmetric\n    bool isSymmetricUtil(Node* root1, Node* root2) {\n        // Check if either subtree is NULL\n        if (root1 == NULL || root2 == NULL) {\n            // If one subtree is NULL, the other\n            // must also be NULL for symmetry\n            return root1 == root2;\n        }\n        // Check if the data in the current nodes is equal\n        // and recursively check for symmetry in subtrees\n        return (root1->data == root2->data)\n            && isSymmetricUtil(root1->left, root2->right)\n            && isSymmetricUtil(root1->right, root2->left);\n    }\n\npublic:\n    // Public function to check if the\n    // entire binary tree is symmetric\n    bool isSymmetric(Node* root) {\n        // Check if the tree is empty\n        if (!root) {\n            // An empty tree is\n            // considered symmetric\n            return true;\n        }\n        // Call the utility function\n        // to check symmetry of subtrees\n        return isSymmetricUtil(root->left, root->right);\n    }\n};\n\n\n// Function to print the Inorder\n// Traversal of the Binary Tree\nvoid printInorder(Node* root){\n    if(!root){\n        return;\n    }\n    printInorder(root->left);\n    cout << root->data << \" \";\n    printInorder(root->right);\n}\n\n\nint main() {\n    // Creating a sample binary tree\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->right = new Node(2);\n    root->left->left = new Node(3);\n    root->right->right = new Node(3);\n    root->left->right = new Node(4);\n    root->right->left = new Node(4);\n\n    Solution solution;\n    \n    cout << \"Binary Tree (Inorder): \";\n    printInorder(root);\n    cout << endl;\n\n    bool res;\n    res = solution.isSymmetric(root);\n    \n    if(res){\n        cout << \"This Tree is Symmetrical\" << endl;\n    }\n    else{\n        cout << \"This Tree is NOT Symmetrical\" << endl;\n    }\n\n    return 0;\n}",
      "py": "# Node class for the binary tree\nclass Node:\n    def __init__(self, val):\n        self.data = val\n        self.left = None\n        self.right = None\n\n# Solution class to find the\n# maximum depth of a binary tree\nclass Solution:\n    # Function to find the\n    # maximum depth of a binary tree\n    def maxDepth(self, root):\n        # If the root is None\n        # (empty tree), depth is 0\n        if root is None:\n            return 0\n        \n        # Recursive call to find the\n        # maximum depth of the left subtree\n        lh = self.maxDepth(root.left)\n        \n        # Recursive call to find the\n        # maximum depth of the right subtree\n        rh = self.maxDepth(root.right)\n        \n        # Return the maximum depth of the\n        # tree, adding 1 for the current node\n        return 1 + max(lh, rh)\n\n# Main function\nif __name__ == \"__main__\":\n    # Creating a sample binary tree\n    root = Node(1)\n    root.left = Node(2)\n    root.right = Node(3)\n    root.left.left = Node(4)\n    root.left.right = Node(5)\n    root.left.right.right = Node(6)\n    root.left.right.right.right = Node(7)\n    \n    solution = Solution()\n    depth = solution.maxDepth(root)\n    \n    print(\"Maximum depth of the binary tree:\", depth)"
