      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(H)$",
      "mantra": "- Modified preorder traversal (Root, Right, Left) visits rightmost nodes first per depth level.\n- Append node value to result list if and only if depth == res.size().\n- Left view follows symmetrically using standard Root, Left, Right preorder.",
      "leetcode": "https://leetcode.com/problems/binary-tree-right-side-view/",
      "tuf": "https://takeuforward.org/data-structure/right-left-view-of-binary-tree/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// TreeNode definition\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(NULL), right(NULL) {}\n};\n\nclass Solution {\npublic:\n    // Recursive function to get left view\n    void leftDFS(TreeNode* node, int level, vector<int>& res) {\n        // Base case: null node\n        if (!node) return;\n\n        // If this is the first node at the current level\n        if (res.size() == level)\n            res.push_back(node->val);\n\n        // Explore left subtree first\n        leftDFS(node->left, level + 1, res);\n\n        // Then explore right subtree\n        leftDFS(node->right, level + 1, res);\n    }\n\n    // Recursive function to get right view\n    void rightDFS(TreeNode* node, int level, vector<int>& res) {\n        if (!node) return;\n\n        if (res.size() == level)\n            res.push_back(node->val);\n\n        // Explore right subtree first\n        rightDFS(node->right, level + 1, res);\n\n        // Then explore left subtree\n        rightDFS(node->left, level + 1, res);\n    }\n\n    vector<int> leftView(TreeNode* root) {\n        vector<int> res;\n        leftDFS(root, 0, res);\n        return res;\n    }\n\n    vector<int> rightView(TreeNode* root) {\n        vector<int> res;\n        rightDFS(root, 0, res);\n        return res;\n    }\n};\n\n// Driver code\nint main() {\n    TreeNode* root = new TreeNode(1);\n    root->left = new TreeNode(2);\n    root->right = new TreeNode(3);\n    root->left->right = new TreeNode(4);\n    root->left->right->right = new TreeNode(5);\n    root->left->right->right->right = new TreeNode(6);\n\n    Solution sol;\n    vector<int> left = sol.leftView(root);\n    vector<int> right = sol.rightView(root);\n\n    cout << \"Left View: \";\n    for (int val : left) cout << val << \" \";\n    cout << \"\\nRight View: \";\n    for (int val : right) cout << val << \" \";\n    return 0;\n}",
      "py": "# TreeNode class for binary tree nodes\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\nclass Solution:\n    # Recursive function to get left view\n    def leftDFS(self, node, level, res):\n        # Base case\n        if not node:\n            return\n\n        # If we are visiting the level for the first time\n        if len(res) == level:\n            res.append(node.val)\n\n        # Recurse to left child\n        self.leftDFS(node.left, level + 1, res)\n\n        # Recurse to right child\n        self.leftDFS(node.right, level + 1, res)\n\n    # Recursive function to get right view\n    def rightDFS(self, node, level, res):\n        if not node:\n            return\n\n        if len(res) == level:\n            res.append(node.val)\n\n        # Recurse to right child\n        self.rightDFS(node.right, level + 1, res)\n\n        # Recurse to left child\n        self.rightDFS(node.left, level + 1, res)\n\n    # Wrapper function for left view\n    def leftView(self, root):\n        res = []\n        self.leftDFS(root, 0, res)\n        return res\n\n    # Wrapper function for right view\n    def rightView(self, root):\n        res = []\n        self.rightDFS(root, 0, res)\n        return res\n\n# Driver code\nif __name__ == \"__main__\":\n    # Create the binary tree\n    root = TreeNode(1)\n    root.left = TreeNode(2)\n    root.right = TreeNode(3)\n    root.left.right = TreeNode(4)\n    root.left.right.right = TreeNode(5)\n    root.left.right.right.right = TreeNode(6)\n\n    sol = Solution()\n\n    # Get left and right view\n    left = sol.leftView(root)\n    right = sol.rightView(root)\n\n    # Print left view\n    print(\"Left View:\", left)\n\n    # Print right view\n    print(\"Right View:\", right)"
