      "title": "Return the bottom view of a binary tree from leftmost to rightmost column.",
      "canonicalName": "Bottom view of BT",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(N)$",
      "mantra": "- Track vertical coordinate x in BFS queue; child transitions are x - 1 and x + 1.\n- BFS guarantees that nodes processed later at column x overwrite earlier, higher nodes.\n- Iterate over ordered column keys from min_col to max_col to assemble output.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/bottom-view-of-a-binary-tree/",
      "cpp": "#include <iostream>\n#include <vector>\n#include <set>\n#include <queue>\n#include <map>\n\nusing namespace std;\n\n// Node structure for the binary tree\nstruct Node {\n    int data;\n    Node* left;\n    Node* right;\n    // Constructor to initialize\n    // the node with a value\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\nclass Solution{\npublic:\n    // Function to return the\n    // bottom view of the binary tree\n    vector<int> bottomView(Node* root){\n        // Vector to store the result\n        vector<int> ans;\n        \n        // Check if the tree is empty\n        if(root == NULL){\n            return ans;\n        }\n        \n        // Map to store the bottom view nodes\n        // based on their vertical positions\n        map<int, int> mpp;\n        \n        // Queue for BFS traversal, each\n        // element is a pair containing node\n        // and its vertical position\n        queue<pair<Node*, int>> q;\n        \n        // Push the root node with its vertical\n        // position (0) into the queue\n        q.push({root, 0});\n        \n        // BFS traversal\n        while(!q.empty()){\n            // Retrieve the node and its vertical\n            // position from the front of the queue\n            auto it = q.front();\n            q.pop();\n            Node* node = it.first;\n            int line = it.second;\n            \n            // Update the map with the node's data\n            // for the current vertical position\n            mpp[line] = node->data;\n            \n            // Process left child\n            if(node->left != NULL){\n                // Push the left child with a decreased\n                // vertical position into the queue\n                q.push({node->left, line - 1});\n            }\n            \n            // Process right child\n            if(node->right != NULL){\n                // Push the right child with an increased\n                // vertical position into the queue\n                q.push({node->right, line + 1});\n            }\n        }\n        \n        // Transfer values from the\n        // map to the result vector\n        for(auto it : mpp){\n            ans.push_back(it.second);\n        }\n        \n        return ans;\n    }\n};\n\nint main() {\n    // Creating a sample binary tree\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->left->left = new Node(4);\n    root->left->right = new Node(10);\n    root->left->left->right = new Node(5);\n    root->left->left->right->right = new Node(6);\n    root->right = new Node(3);\n    root->right->right = new Node(10);\n    root->right->left = new Node(9);\n\n    Solution solution;\n\n    // Get the Bottom View traversal\n    vector<int> bottomView =\n                    solution.bottomView(root);\n\n    // Print the result\n    cout << \"Bottom View Traversal: \"<< endl;\n    for(auto node: bottomView){\n        cout << node << \" \";\n    }\n\n    return 0;\n}",
      "py": "from queue import Queue\nfrom collections import deque, defaultdict\n\n# Node class to represent the binary tree\nclass Node:\n    def __init__(self, val):\n        self.data = val\n        self.left = None\n        self.right = None\n\nclass Solution:\n    def bottomView(self, root):\n        \"\"\"\n        Function to return the\n        bottom view of the binary tree\n        \"\"\"\n        # Vector to store the result\n        ans = []\n\n        # Check if the tree is empty\n        if root is None:\n            return ans\n\n        # Map to store the bottom view nodes\n        # based on their vertical positions\n        mpp = defaultdict(int)\n\n        # Queue for BFS traversal, each\n        # element is a pair containing node\n        # and its vertical position\n        q = Queue()\n\n        # Push the root node with its vertical\n        # position (0) into the queue\n        q.put((root, 0))\n\n        # BFS traversal\n        while not q.empty():\n            # Retrieve the node and its vertical\n            # position from the front of the queue\n            it = q.get()\n            node, line = it[0], it[1]\n\n            # Update the map with the node's data\n            # for the current vertical position\n            mpp[line] = node.data\n\n            # Process left child\n            if node.left:\n                # Push the left child with a decreased\n                # vertical position into the queue\n                q.put((node.left, line - 1))\n\n            # Process right child\n            if node.right:\n                # Push the right child with an increased\n                # vertical position into the queue\n                q.put((node.right, line + 1))\n\n        # Transfer values from the\n        # map to the result vector\n        for key, value in sorted(mpp.items()):\n            ans.append(value)\n\n        return ans\n\n# Creating a sample binary tree\nroot = Node(1)\nroot.left = Node(2)\nroot.left.left = Node(4)\nroot.left.right = Node(10)\nroot.left.left.right = Node(5)\nroot.left.left.right.right = Node(6)\nroot.right = Node(3)\nroot.right.right = Node(10)\nroot.right.left = Node(9)\n\n# Creating a Solution object\nsolution = Solution()\n\n# Get the Bottom View traversal\nbottomView = solution.bottomView(root)\n\n# Print the result\nprint(\"Bottom View Traversal:\")\nfor node in bottomView:\n    print(node, end=\" \")"
