      "title": "Return the top view of a binary tree from leftmost to rightmost column.",
      "canonicalName": "Top View of BT",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(N)$",
      "mantra": "- BFS queue tracks (node, column) coordinate pairs level-by-level.\n- Insert into hash map strictly if column x has not been previously observed.\n- Upper nodes are visited first due to FIFO BFS order, ensuring correct top-down occlusion.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/top-view-of-a-binary-tree/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Structure representing each node of the binary tree\nstruct Node {\n    // Value stored in the node\n    int data;\n    // Pointer to the left child\n    Node* left;\n    // Pointer to the right child\n    Node* right;\n    // Constructor to initialize a node with a value\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\n// Class containing the logic for top view\nclass Solution {\npublic:\n    // Function to return the top view of the binary tree\n    vector<int> topView(Node* root) {\n        // Create a vector to store the final answer\n        vector<int> ans;\n\n        // If the tree is empty, return an empty result\n        if (root == NULL) {\n            return ans;\n        }\n\n        // Create a map to store vertical level -> node value (only first encountered)\n        map<int, int> mpp;\n\n        // Create a queue for BFS that stores {node, vertical_level}\n        queue<pair<Node*, int>> q;\n\n        // Push the root node with vertical level 0\n        q.push({root, 0});\n\n        // Start BFS traversal\n        while (!q.empty()) {\n            // Extract the front element of the queue\n            auto it = q.front();\n            q.pop();\n\n            // Get the node and its vertical position\n            Node* node = it.first;\n            int line = it.second;\n\n            // If this vertical position is being visited for the first time, store it\n            if (mpp.find(line) == mpp.end()) {\n                mpp[line] = node->data;\n            }\n\n            // If there is a left child, push it with vertical level - 1\n            if (node->left != NULL) {\n                q.push({node->left, line - 1});\n            }\n\n            // If there is a right child, push it with vertical level + 1\n            if (node->right != NULL) {\n                q.push({node->right, line + 1});\n            }\n        }\n\n        // Traverse the map and store values in the answer vector\n        for (auto it : mpp) {\n            ans.push_back(it.second);\n        }\n\n        // Return the result\n        return ans;\n    }\n};\n\n// Driver code\nint main() {\n    // Create the sample binary tree\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->left->left = new Node(4);\n    root->left->right = new Node(10);\n    root->left->left->right = new Node(5);\n    root->left->left->right->right = new Node(6);\n    root->right = new Node(3);\n    root->right->right = new Node(10);\n    root->right->left = new Node(9);\n\n    // Create a Solution object\n    Solution solution;\n\n    // Get the top view\n    vector<int> result = solution.topView(root);\n\n    // Print the top view traversal\n    cout << \"Top View Traversal: \";\n    for (auto node : result) {\n        cout << node << \" \";\n    }\n    return 0;\n}",
      "py": "# Class representing a single node of the binary tree\nclass Node:\n    # Constructor to initialize node with value\n    def __init__(self, val):\n        self.data = val\n        self.left = None\n        self.right = None\n\n# Class containing the logic for top view\nclass Solution:\n    # Function to return the top view of the binary tree\n    def topView(self, root):\n        # Create a list to store final answer\n        ans = []\n\n        # If tree is empty, return empty list\n        if root is None:\n            return ans\n\n        # Dictionary to store vertical_level -> node value\n        mpp = {}\n\n        # Queue for BFS storing (node, vertical_level)\n        from collections import deque\n        q = deque()\n\n        # Push the root with vertical level 0\n        q.append((root, 0))\n\n        # Start BFS traversal\n        while q:\n            # Pop the front element from queue\n            node, line = q.popleft()\n\n            # If vertical level is first time visited, store value\n            if line not in mpp:\n                mpp[line] = node.data\n\n            # If left child exists, push with vertical level - 1\n            if node.left:\n                q.append((node.left, line - 1))\n\n            # If right child exists, push with vertical level + 1\n            if node.right:\n                q.append((node.right, line + 1))\n\n        # Extract values from dictionary in sorted order of vertical levels\n        for key in sorted(mpp.keys()):\n            ans.append(mpp[key])\n\n        # Return the result\n        return ans\n\n# Driver code\nif __name__ == \"__main__\":\n    # Create the sample binary tree\n    root = Node(1)\n    root.left = Node(2)\n    root.left.left = Node(4)\n    root.left.right = Node(10)\n    root.left.left.right = Node(5)\n    root.left.left.right.right = Node(6)\n    root.right = Node(3)\n    root.right.right = Node(10)\n    root.right.left = Node(9)\n\n    # Create Solution object\n    solution = Solution()\n\n    # Get the top view\n    result = solution.topView(root)\n\n    # Print the result\n    print(\"Top View Traversal:\", *result)"
