      "title": "Return the vertical order traversal of a binary tree sorted by column, row, and value.",
      "canonicalName": "Vertical Order Traversal",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N \\log N)$ | Space Complexity: $\\mathcal{O}(N)$",
      "mantra": "- Map 2D coordinates: map col -> (map row -> multiset<int>) during DFS or BFS traversal.\n- Multiset automatically handles deterministic tie-breaking for overlapping nodes at identical (col, row).\n- Flatten nested maps left-to-right across columns and top-to-bottom across rows.",
      "leetcode": "https://leetcode.com/problems/vertical-order-traversal-of-a-binary-tree/",
      "tuf": "https://takeuforward.org/data-structure/vertical-order-traversal-of-binary-tree/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// This structure defines a node in the binary tree\nstruct Node {\n    // This stores the value of the node\n    int data;\n    // Pointer to the left child\n    Node* left;\n    // Pointer to the right child\n    Node* right;\n\n    // Constructor initializes node with value\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\n// This class contains the solution logic\nclass Solution {\npublic:\n    // Function to perform vertical order traversal\n    vector<vector<int>> findVertical(Node* root) {\n        // A map is used to store nodes grouped by vertical and level\n        map<int, map<int, multiset<int>>> nodes;\n\n        // A queue is used for BFS, storing node and its coordinates\n        queue<pair<Node*, pair<int, int>>> todo;\n\n        // Push the root node with vertical = 0 and level = 0\n        todo.push({root, {0, 0}});\n\n        // Perform BFS traversal\n        while (!todo.empty()) {\n            // Get the front element in queue\n            auto p = todo.front();\n            todo.pop();\n\n            // Extract node\n            Node* temp = p.first;\n            // Extract vertical (x)\n            int x = p.second.first;\n            // Extract level (y)\n            int y = p.second.second;\n\n            // Insert the node into map by vertical and level\n            nodes[x][y].insert(temp->data);\n\n            // If left child exists, push with updated coordinates\n            if (temp->left) {\n                todo.push({temp->left, {x - 1, y + 1}});\n            }\n\n            // If right child exists, push with updated coordinates\n            if (temp->right) {\n                todo.push({temp->right, {x + 1, y + 1}});\n            }\n        }\n\n        // Final answer vector\n        vector<vector<int>> ans;\n\n        // Iterate through verticals in map\n        for (auto p : nodes) {\n            vector<int> col;\n            // Collect all nodes in order of levels\n            for (auto q : p.second) {\n                col.insert(col.end(), q.second.begin(), q.second.end());\n            }\n            // Push the column into result\n            ans.push_back(col);\n        }\n\n        // Return final vertical order traversal\n        return ans;\n    }\n};\n\n// Helper function to print result\nvoid printResult(const vector<vector<int>>& result) {\n    for (auto level : result) {\n        for (auto node : level) {\n            cout << node << \" \";\n        }\n        cout << endl;\n    }\n    cout << endl;\n}\n\n// Driver code\nint main() {\n    // Create sample binary tree\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->left->left = new Node(4);\n    root->left->right = new Node(10);\n    root->left->left->right = new Node(5);\n    root->left->left->right->right = new Node(6);\n    root->right = new Node(3);\n    root->right->right = new Node(10);\n    root->right->left = new Node(9);\n\n    // Create solution object\n    Solution solution;\n\n    // Call vertical order traversal\n    vector<vector<int>> verticalTraversal = solution.findVertical(root);\n\n    // Print result\n    cout << \"Vertical Traversal:\" << endl;\n    printResult(verticalTraversal);\n\n    return 0;\n}",
      "py": "# This class defines a node in the binary tree\nclass Node:\n    def __init__(self, val):\n        self.data = val\n        self.left = None\n        self.right = None\n\n# This class contains the solution logic\nclass Solution:\n    # Function to perform vertical order traversal\n    def findVertical(self, root):\n        # Dictionary to store nodes by vertical and level\n        nodes = {}\n\n        # Queue for BFS traversal\n        from collections import deque, defaultdict\n        todo = deque()\n        todo.append((root, 0, 0))\n\n        # BFS loop\n        while todo:\n            temp, x, y = todo.popleft()\n\n            # Insert into dictionary\n            if x not in nodes:\n                nodes[x] = {}\n            if y not in nodes[x]:\n                nodes[x][y] = []\n            nodes[x][y].append(temp.data)\n\n            # Left child\n            if temp.left:\n                todo.append((temp.left, x - 1, y + 1))\n            # Right child\n            if temp.right:\n                todo.append((temp.right, x + 1, y + 1))\n\n        # Prepare final result\n        ans = []\n        for x in sorted(nodes.keys()):\n            col = []\n            for y in sorted(nodes[x].keys()):\n                col.extend(sorted(nodes[x][y]))\n            ans.append(col)\n\n        return ans\n\n# Function to print result\ndef printResult(result):\n    for level in result:\n        print(\" \".join(map(str, level)))\n    print()\n\n# Driver code\nif __name__ == \"__main__\":\n    # Create sample binary tree\n    root = Node(1)\n    root.left = Node(2)\n    root.left.left = Node(4)\n    root.left.right = Node(10)\n    root.left.left.right = Node(5)\n    root.left.left.right.right = Node(6)\n    root.right = Node(3)\n    root.right.right = Node(10)\n    root.right.left = Node(9)\n\n    # Create solution object\n    solution = Solution()\n\n    # Call function\n    verticalTraversal = solution.findVertical(root)\n\n    # Print result\n    print(\"Vertical Traversal:\")\n    printResult(verticalTraversal)"
