      "title": "Determine if a binary tree is height-balanced.",
      "canonicalName": "Check for balanced binary tree",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(H)$",
      "mantra": "- A node is balanced iff |left_h - right_h| <= 1 and both subtrees are balanced.\n- Bottom-up DFS returns -1 sentinel immediately upon detecting an unbalanced child.\n- Early pruning cascades -1 to root, terminating computation without visiting redundant nodes.",
      "leetcode": "https://leetcode.com/problems/balanced-binary-tree/",
      "tuf": "https://takeuforward.org/data-structure/check-if-the-binary-tree-is-balanced-binary-tree/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Node structure for the binary tree\nstruct Node {\n    int data;       // Data stored in the node\n    Node* left;     // Pointer to the left child\n    Node* right;    // Pointer to the right child\n\n    // Constructor to initialize the node with a value\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\nclass Solution {\n\npublic:\n    // Function to check if a binary tree is balanced\n    bool isBalanced(Node* root) {\n        // Check if the tree's height difference between subtrees is less than 2\n        // If not, return false; otherwise, return true\n        return dfsHeight(root) != -1;\n    }\n\n    // Recursive function to calculate the height of the tree\n    int dfsHeight(Node* root) {\n        // Base case: if the current node is NULL, return 0 (height of an empty tree)\n        if (root == NULL) return 0;\n\n        // Recursively calculate the height of the left subtree\n        int leftHeight = dfsHeight(root->left);\n\n        // If the left subtree is unbalanced, propagate the unbalance status\n        if (leftHeight == -1) \n            return -1;\n\n        // Recursively calculate the height of the right subtree\n        int rightHeight = dfsHeight(root->right);\n\n        // If the right subtree is unbalanced, propagate the unbalance status\n        if (rightHeight == -1) \n            return -1;\n\n        // Check if the difference in height between left and right subtrees is greater than 1\n        // If it's greater, the tree is unbalanced, return -1 to propagate the unbalance status\n        if (abs(leftHeight - rightHeight) > 1)  \n            return -1;\n\n        // Return the maximum height of left and right subtrees, adding 1 for the current node\n        return max(leftHeight, rightHeight) + 1;\n    }\n};\n\n// Main function\nint main() {\n    // Creating a sample binary tree\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->right = new Node(3);\n    root->left->left = new Node(4);\n    root->left->right = new Node(5);\n    root->left->right->right = new Node(6);\n    root->left->right->right->right = new Node(7);\n\n    // Creating an instance of the Solution class\n    Solution solution;\n\n    // Checking if the tree is balanced\n    if (solution.isBalanced(root)) {\n        cout << \"The tree is balanced.\" << endl;\n    } else {\n        cout << \"The tree is not balanced.\" << endl;\n    }\n\n    return 0;\n}",
      "py": "# Node class to represent a node in a binary tree\nclass Node:\n    def __init__(self, val):\n        self.data = val\n        self.left = None\n        self.right = None\n\nclass Solution:\n\n    # Function to check if a binary tree is balanced\n    def isBalanced(self, root):\n        # Check if the tree's height difference between subtrees is less than 2\n        # If not, return false; otherwise, return true\n        return self.dfsHeight(root) != -1\n\n    # Recursive function to calculate the height of the tree\n    def dfsHeight(self, root):\n        # Base case: if the current node is NULL, return 0 (height of an empty tree)\n        if root is None:\n            return 0\n\n        # Recursively calculate the height of the left subtree\n        leftHeight = self.dfsHeight(root.left)\n\n        # If the left subtree is unbalanced, propagate the unbalance status\n        if leftHeight == -1:\n            return -1\n\n        # Recursively calculate the height of the right subtree\n        rightHeight = self.dfsHeight(root.right)\n\n        # If the right subtree is unbalanced, propagate the unbalance status\n        if rightHeight == -1:\n            return -1\n\n        # Check if the difference in height between left and right subtrees is greater than 1\n        # If it's greater, the tree is unbalanced, return -1 to propagate the unbalance status\n        if abs(leftHeight - rightHeight) > 1:\n            return -1\n\n        # Return the maximum height of left and right subtrees plus 1 (for the current node)\n        return max(leftHeight, rightHeight) + 1\n\n# Driver code\nif __name__ == \"__main__\":\n    # Creating a sample binary tree\n    root = Node(1)\n    root.left = Node(2)\n    root.right = Node(3)\n    root.left.left = Node(4)\n    root.left.right = Node(5)\n    root.left.right.right = Node(6)\n    root.left.right.right.right = Node(7)\n\n    # Creating an instance of the Solution class\n    solution = Solution()\n\n    # Checking if the tree is balanced\n    if solution.isBalanced(root):\n        print(\"The tree is balanced.\")\n    else:\n        print(\"The tree is not balanced.\")"
