      "title": "Return the zigzag level-order traversal of a binary tree.",
      "canonicalName": "Zig Zag or Spiral Traversal",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(N)$",
      "mantra": "- Standard BFS level-order using boolean flag to alternate left-to-right vs right-to-left fill.\n- Pre-allocate level vector of size equal to queue length; populate indices directly via (flag ? i : size - 1 - i).\n- Invert boolean flag after processing each complete level horizon.",
      "leetcode": "https://leetcode.com/problems/binary-tree-zigzag-level-order-traversal/",
      "tuf": "https://takeuforward.org/data-structure/zig-zag-traversal-of-binary-tree/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Structure to represent a binary tree node\nstruct TreeNode {\n    int val;                // Value of the node\n    TreeNode* left;         // Pointer to left child\n    TreeNode* right;        // Pointer to right child\n    // Constructor to initialize node with a given value\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nclass Solution {\npublic:\n    // Function to perform zigzag (spiral) level order traversal of a binary tree\n    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {\n        // Vector to store the final zigzag traversal result\n        vector<vector<int>> result;\n        // If the tree is empty, return an empty result\n        if (!root) return result;\n\n        // Queue to store nodes level by level (BFS)\n        queue<TreeNode*> q;\n        q.push(root);\n\n        // Boolean flag to control traversal direction: true for left-to-right, false for right-to-left\n        bool leftToRight = true;\n\n        // Loop until all levels are processed\n        while (!q.empty()) {\n            // Get the number of nodes at the current level\n            int size = q.size();\n\n            // Temporary vector to store the current level's values in correct zigzag order\n            vector<int> level(size);\n\n            // Process each node in the current level\n            for (int i = 0; i < size; i++) {\n                // Get the front node from the queue\n                TreeNode* node = q.front();\n                q.pop();\n\n                // Determine index where this node's value should be placed based on traversal direction\n                int index = leftToRight ? i : size - 1 - i;\n                level[index] = node->val;\n\n                // If left child exists, add it to the queue\n                if (node->left) q.push(node->left);\n                // If right child exists, add it to the queue\n                if (node->right) q.push(node->right);\n            }\n\n            // After finishing this level, toggle the direction for the next level\n            leftToRight = !leftToRight;\n\n            // Add this level's data to the final result\n            result.push_back(level);\n        }\n\n        // Return the zigzag traversal result\n        return result;\n    }\n};\n\nint main() {\n    // Create binary tree:\n    //        1\n    //      /   \\\n    //     2     3\n    //    / \\     \\\n    //   4   5     6\n    TreeNode* root = new TreeNode(1);\n    root->left = new TreeNode(2);\n    root->right = new TreeNode(3);\n    root->left->left = new TreeNode(4);\n    root->left->right = new TreeNode(5);\n    root->right->right = new TreeNode(6);\n\n    // Create Solution object\n    Solution sol;\n\n    // Get zigzag traversal result\n    vector<vector<int>> ans = sol.zigzagLevelOrder(root);\n\n    // Print result in desired format\n    cout << \"[\";\n    for (auto &level : ans) {\n        cout << \"[\";\n        for (int i = 0; i < level.size(); i++) {\n            cout << level[i];\n            if (i != level.size() - 1) cout << \", \";\n        }\n        cout << \"]\";\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}",
      "py": "from collections import deque\n\n# Class to represent a binary tree node\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x          # Value of the node\n        self.left = None      # Pointer to left child\n        self.right = None     # Pointer to right child\n\nclass Solution:\n    # Function to perform zigzag (spiral) level order traversal\n    def zigzagLevelOrder(self, root):\n        # List to store the final zigzag traversal result\n        result = []\n\n        # If tree is empty, return empty list\n        if not root:\n            return result\n\n        # Queue for BFS traversal\n        q = deque([root])\n\n        # Boolean flag to control traversal direction\n        leftToRight = True\n\n        # Loop until all levels are processed\n        while q:\n            # Get the number of nodes at the current level\n            size = len(q)\n\n            # Temporary list to store current level's values\n            level = [0] * size\n\n            # Process each node in the current level\n            for i in range(size):\n                # Get the front node from queue\n                node = q.popleft()\n\n                # Determine index where this value should be stored\n                index = i if leftToRight else size - 1 - i\n                level[index] = node.val\n\n                # Add left child to queue if it exists\n                if node.left:\n                    q.append(node.left)\n                # Add right child to queue if it exists\n                if node.right:\n                    q.append(node.right)\n\n            # Flip direction for the next level\n            leftToRight = not leftToRight\n\n            # Add current level to result\n            result.append(level)\n\n        # Return zigzag traversal result\n        return result\n\n# Driver code\nif __name__ == \"__main__\":\n    # Create binary tree:\n    #        1\n    #      /   \\\n    #     2     3\n    #    / \\     \\\n    #   4   5     6\n    root = TreeNode(1)\n    root.left = TreeNode(2)\n    root.right = TreeNode(3)\n    root.left.left = TreeNode(4)\n    root.left.right = TreeNode(5)\n    root.right.right = TreeNode(6)\n\n    # Create solution object\n    sol = Solution()\n\n    # Get zigzag traversal\n    ans = sol.zigzagLevelOrder(root)\n\n    # Print result\n    print(ans)"
