      "title": "Return the anticlockwise boundary traversal of a binary tree starting from the root.",
      "canonicalName": "Boundary Traversal",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(H)$",
      "mantra": "- Decompose into three disjoint traversals: left boundary, leaf nodes via inorder, and reversed right boundary.\n- Root node is added first; exclude leaf nodes during left and right boundary traversals.\n- Right boundary nodes are collected and reversed before concatenating to result.",
      "leetcode": "https://leetcode.com/problems/boundary-of-binary-tree/",
      "tuf": "https://takeuforward.org/data-structure/boundary-traversal-of-a-binary-tree/",
      "cpp": "#include <iostream>\n#include <vector>\n\nusing namespace std;\n\n// Node structure for the binary tree\nstruct Node {\n    int data;\n    Node* left;\n    Node* right;\n    // Constructor to initialize\n    // the node with a value\n    Node(int val) : data(val), left(nullptr), right(nullptr) {}\n};\n\nclass Solution {\npublic:\n    // Function to check\n    // if a node is a leaf\n    bool isLeaf(Node* root) {\n        return !root->left && !root->right;\n    }\n\n    // Function to add the\n    // left boundary of the tree\n    void addLeftBoundary(Node* root, vector<int>& res) {\n        Node* curr = root->left;\n        while (curr) {\n            // If the current node is not a leaf,\n            // add its value to the result\n            if (!isLeaf(curr)) {\n                res.push_back(curr->data);\n            }\n            // Move to the left child if it exists,\n            // otherwise move to the right child\n            if (curr->left) {\n                curr = curr->left;\n            } else {\n                curr = curr->right;\n            }\n        }\n    }\n\n    // Function to add the\n    // right boundary of the tree\n    void addRightBoundary(Node* root, vector<int>& res) {\n        Node* curr = root->right;\n        vector<int> temp;\n        while (curr) {\n            // If the current node is not a leaf,\n            // add its value to a temporary vector\n            if (!isLeaf(curr)) {\n                temp.push_back(curr->data);\n            }\n            // Move to the right child if it exists,\n            // otherwise move to the left child\n            if (curr->right) {\n                curr = curr->right;\n            } else {\n                curr = curr->left;\n            }\n        }\n        // Reverse and add the values from\n        // the temporary vector to the result\n        for (int i = temp.size() - 1; i >= 0; --i) {\n            res.push_back(temp[i]);\n        }\n    }\n\n    // Function to add the\n    // leaves of the tree\n    void addLeaves(Node* root, vector<int>& res) {\n        // If the current node is a\n        // leaf, add its value to the result\n        if (isLeaf(root)) {\n            res.push_back(root->data);\n            return;\n        }\n        // Recursively add leaves of\n        // the left and right subtrees\n        if (root->left) {\n            addLeaves(root->left, res);\n        }\n        if (root->right) {\n            addLeaves(root->right, res);\n        }\n    }\n\n    // Main function to perform the\n    // boundary traversal of the binary tree\n    vector<int> printBoundary(Node* root) {\n        vector<int> res;\n        if (!root) {\n            return res;\n        }\n        // If the root is not a leaf,\n        // add its value to the result\n        if (!isLeaf(root)) {\n            res.push_back(root->data);\n        }\n\n        // Add the left boundary, leaves,\n        // and right boundary in order\n        addLeftBoundary(root, res);\n        addLeaves(root, res);\n        addRightBoundary(root, res);\n\n        return res;\n    }\n};\n\n// Helper function to\n// print the result\nvoid printResult(const vector<int>& result) {\n    for (int val : result) {\n        cout << val << \" \";\n    }\n    cout << endl;\n}\n\nint main() {\n    // Creating a sample binary tree\n    Node* root = new Node(1);\n    root->left = new Node(2);\n    root->right = new Node(3);\n    root->left->left = new Node(4);\n    root->left->right = new Node(5);\n    root->right->left = new Node(6);\n    root->right->right = new Node(7);\n\n    Solution solution;\n\n    // Get the boundary traversal\n    vector<int> result = solution.printBoundary(root);\n\n    // Print the result\n    cout << \"Boundary Traversal: \";\n    printResult(result);\n\n    return 0;\n}",
      "py": "class Node:\n    def __init__(self, val):\n        self.data = val\n        self.left = None\n        self.right = None\n\nclass Solution:\n    def isLeaf(self, root):\n        \"\"\"\n        Function to check if a node is a leaf\n        \"\"\"\n        return not root.left and not root.right\n\n    def addLeftBoundary(self, root, res):\n        \"\"\"\n        Function to add the left boundary of the tree\n        \"\"\"\n        curr = root.left\n        while curr:\n            if not self.isLeaf(curr):\n                # If the current node is not a leaf,\n                # add its value to the result\n                res.append(curr.data)\n            # Move to the left child if it exists,\n            # otherwise move to the right child\n            if curr.left:\n                curr = curr.left\n            else:\n                curr = curr.right\n\n    def addRightBoundary(self, root, res):\n        \"\"\"\n        Function to add the right boundary of the tree\n        \"\"\"\n        curr = root.right\n        temp = []\n        while curr:\n            if not self.isLeaf(curr):\n                # If the current node is not a leaf,\n                # add its value to a temporary vector\n                temp.append(curr.data)\n            # Move to the right child if it exists,\n            # otherwise move to the left child\n            if curr.right:\n                curr = curr.right\n            else:\n                curr = curr.left\n        # Reverse and add the values from\n        # the temporary vector to the result\n        for i in range(len(temp) - 1, -1, -1):\n            res.append(temp[i])\n\n    def addLeaves(self, root, res):\n        \"\"\"\n        Function to add the leaves of the tree\n        \"\"\"\n        if self.isLeaf(root):\n            # If the current node is a leaf,\n            # add its value to the result\n            res.append(root.data)\n            return\n        # Recursively add leaves of\n        # the left and right subtrees\n        if root.left:\n            self.addLeaves(root.left, res)\n        if root.right:\n            self.addLeaves(root.right, res)\n\n    def printBoundary(self, root):\n        \"\"\"\n        Main function to perform the\n        boundary traversal of the binary tree\n        \"\"\"\n        res = []\n        if not root:\n            return res\n        # If the root is not a leaf,\n        # add its value to the result\n        if not self.isLeaf(root):\n            res.append(root.data)\n\n        # Add the left boundary, leaves,\n        # and right boundary in order\n        self.addLeftBoundary(root, res)\n        self.addLeaves(root, res)\n        self.addRightBoundary(root, res)\n\n        return res\n\n# Helper function to\n# print the result\ndef printResult(result):\n    for val in result:\n        print(val, end=\" \")\n    print()\n\n# Creating a sample binary tree\nroot = Node(1)\nroot.left = Node(2)\nroot.right = Node(3)\nroot.left.left = Node(4)\nroot.left.right = Node(5)\nroot.right.left = Node(6)\nroot.right.right = Node(7)\n\nsolution = Solution()\n\n# Get the boundary traversal\nresult = solution.printBoundary(root)\n\n# Print the result\nprint(\"Boundary Traversal:\", end=\" \")\nprintResult(result)"
