      "title": "Find the lowest common ancestor (LCA) of two given nodes in a binary tree.",
      "canonicalName": "LCA in BT",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(H)$",
      "mantra": "- Post-order DFS: if root equals p or q, return root directly.\n- If left and right child recursive calls return non-null, root is the LCA bifurcation point.\n- Otherwise, propagate the non-null child result upward.",
      "leetcode": "https://leetcode.com/problems/lowest-common-ancestor-of-a-binary-tree/",
      "tuf": "https://takeuforward.org/data-structure/lowest-common-ancestor-for-two-given-nodes/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int data;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int val) : data(val), left(NULL), right(NULL) {}\n};\n\nclass Solution {\npublic:\n    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n        // Base case\n        if (root == NULL || root == p || root == q) {\n            return root;\n        }\n        \n        // Search in left and right subtrees\n        TreeNode* left = lowestCommonAncestor(root->left, p, q);\n        TreeNode* right = lowestCommonAncestor(root->right, p, q);\n        \n        // Result\n        if (left == NULL) {\n            return right;\n        } else if (right == NULL) {\n            return left;\n        } else { // Both left and right are not null, we found our result\n            return root;\n        }\n    }\n};\n\nint main() {\n    // Construct a simple binary tree\n    TreeNode* root = new TreeNode(3);\n    root->left = new TreeNode(5);\n    root->right = new TreeNode(1);\n    root->left->left = new TreeNode(6);\n    root->left->right = new TreeNode(2);\n    root->right->left = new TreeNode(0);\n    root->right->right = new TreeNode(8);\n\n    Solution solution;\n    TreeNode* p = root->left; // Node with value 5\n    TreeNode* q = root->right; // Node with value 1\n\n    TreeNode* lca = solution.lowestCommonAncestor(root, p, q);\n    cout << \"Lowest Common Ancestor: \" << lca->data << endl;\n\n    return 0;\n}",
      "py": "# Definition for a binary tree node.\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.data = val\n        self.left = left\n        self.right = right\n\nclass Solution:\n    def lowestCommonAncestor(self, root, p, q):\n        # Base case\n        if root is None or root == p or root == q:\n            return root\n        \n        # Search in left and right subtrees\n        left = self.lowestCommonAncestor(root.left, p, q)\n        right = self.lowestCommonAncestor(root.right, p, q)\n        \n        # Result\n        if left is None:\n            return right\n        elif right is None:\n            return left\n        else: # Both left and right are not null, we found our result\n            return root\n\nif __name__ == \"__main__\":\n    # Construct a simple binary tree\n    root = TreeNode(3)\n    root.left = TreeNode(5)\n    root.right = TreeNode(1)\n    root.left.left = TreeNode(6)\n    root.left.right = TreeNode(2)\n    root.right.left = TreeNode(0)\n    root.right.right = TreeNode(8)\n\n    solution = Solution()\n    p = root.left  # Node with value 5\n    q = root.right  # Node with value 1\n\n    lca = solution.lowestCommonAncestor(root, p, q)\n    print(\"Lowest Common Ancestor:\", lca.data)"
