      "id": 121,
      "patternId": 10,
      "patternName": "Hierarchical Tree Traversals and Subtree DP",
      "problemSeq": 21,
      "title": "Convert a binary tree so every node equals the sum of its children's values, only increasing values.",
      "canonicalName": "Children Sum Property in Binary Tree",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(H)$",
      "mantra": "- Top-down expansion: if parent val > child sum, propagate parent value down to both children.\n- Recurse into left and right subtrees to ensure deep invariant validity.\n- Bottom-up reconstruction: set current node value to exact sum of children values on unwind.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/check-for-children-sum-property-in-a-binary-tree/",
      "cpp": "#include <iostream>\nusing namespace std;\n// TreeNode structure\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\n\n\nclass Solution {\npublic:\n    // Function to change the values of the nodes\n    // based on the sum of its children's values.\n    void changeTree(TreeNode* root) {\n        // Base case: If the current node\n        // is NULL, return and do nothing.\n        if (root == NULL) {\n            return;\n        }\n\n        // Calculate the sum of the values of\n        // the left and right children, if they exist.\n        int child = 0;\n        if (root->left) {\n            child += root->left->val;\n        }\n        if (root->right) {\n            child += root->right->val;\n        }\n\n        // Compare the sum of children with\n        // the current node's value and update\n        if (child >= root->val) {\n            root->val = child;\n        } else {\n            // If the sum is smaller, update the\n            // child with the current node's value.\n            if (root->left) {\n                root->left->val = root->val;\n            } else if (root->right) {\n                root->right->val = root->val;\n            }\n        }\n\n        // Recursively call the function\n        // on the left and right children.\n        changeTree(root->left);\n        changeTree(root->right);\n\n        // Calculate the total sum of the\n        // values of the left and right\n        // children, if they exist.\n        int tot = 0;\n        if (root->left) {\n            tot += root->left->val;\n        }\n        if (root->right) {\n            tot += root->right->val;\n        }\n\n        // If either left or right child\n        // exists, update the current node's\n        // value with the total sum.\n        if (root->left or root->right) {\n            root->val = tot;\n        }\n    }\n};\n\n\n// Function to print the inorder\n// traversal of the tree\nvoid inorderTraversal(TreeNode* root) {\n    if (root == nullptr) {\n        return;\n    }\n    inorderTraversal(root->left);\n    cout << root->val << \" \";\n    inorderTraversal(root->right);\n}\n\nint main() {\n    // Create the binary tree\n    TreeNode* root = new TreeNode(3);\n    root->left = new TreeNode(5);\n    root->right = new TreeNode(1);\n    root->left->left = new TreeNode(6);\n    root->left->right = new TreeNode(2);\n    root->right->left = new TreeNode(0);\n    root->right->right = new TreeNode(8);\n    root->left->right->left = new TreeNode(7);\n    root->left->right->right = new TreeNode(4);\n\n    Solution sol;\n\n    // Print the inorder traversal\n    // of tree before modification\n    cout << \"Binary Tree before modification: \";\n    inorderTraversal(root);\n    cout << endl;\n\n    // Call the changeTree function\n    // to modify the binary tree\n    sol.changeTree(root);\n\n    // Print the inorder traversal\n    // after modification\n    cout << \"Binary Tree after Children Sum Property: \" ;\n    inorderTraversal(root);\n    cout << endl;\n\n    return 0;\n}",
      "py": "class TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\n\nclass Solution:\n    def changeTree(self, root):\n        # Base case: If the current node\n        # is None, return and do nothing.\n        if root is None:\n            return\n\n        # Calculate the sum of the values of\n        # the left and right children, if they exist.\n        child = 0\n        if root.left:\n            child += root.left.val\n        if root.right:\n            child += root.right.val\n\n        # Compare the sum of children with\n        # the current node's value and update\n        if child >= root.val:\n            root.val = child\n        else:\n            # If the sum is smaller, update the\n            # child with the current node's value.\n            if root.left:\n                root.left.val = root.val\n            elif root.right:\n                root.right.val = root.val\n\n        # Recursively call the function\n        # on the left and right children.\n        self.changeTree(root.left)\n        self.changeTree(root.right)\n\n        # Calculate the total sum of the\n        # values of the left and right\n        # children, if they exist.\n        tot = 0\n        if root.left:\n            tot += root.left.val\n        if root.right:\n            tot += root.right.val\n\n        # If either left or right child\n        # exists, update the current node's\n        # value with the total sum.\n        if root.left or root.right:\n            root.val = tot\n\n\n# Function to print the inorder\n# traversal of the tree\ndef inorderTraversal(root):\n    if root is None:\n        return\n    inorderTraversal(root.left)\n    print(root.val, end=\" \")\n    inorderTraversal(root.right)\n\n\n# Create the binary tree\nroot = TreeNode(3)\nroot.left = TreeNode(5)\nroot.right = TreeNode(1)\nroot.left.left = TreeNode(6)\nroot.left.right = TreeNode(2)\nroot.right.left = TreeNode(0)\nroot.right.right = TreeNode(8)\nroot.left.right.left = TreeNode(7)\nroot.left.right.right = TreeNode(4)\n\nsol = Solution()\n\n# Print the inorder traversal\n# of tree before modification\nprint(\"Binary Tree before modification:\", end=\" \")\ninorderTraversal(root)\nprint()\n\n# Call the changeTree function\n# to modify the binary tree\nsol.changeTree(root)\n\n# Print the inorder traversal\n# after modification\nprint(\"Binary Tree after Children Sum Property:\", end=\" \")\ninorderTraversal(root)\nprint()"
