      "title": "Find the maximum path sum between any two nodes in a binary tree.",
      "canonicalName": "Maximum path sum",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(H)$",
      "mantra": "- Subtree DP invariant: max path through root u is u.val + max(0, left) + max(0, right).\n- Clamp child contributions to 0 via max(0, dfs) to ignore negative-sum branches.\n- Return u.val + max(0, max(left, right)) to parent caller as single extendable path.",
      "leetcode": "https://leetcode.com/problems/binary-tree-maximum-path-sum/",
      "tuf": "https://takeuforward.org/data-structure/maximum-sum-path-in-binary-tree/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Tree Node Definition\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n\n    TreeNode(int x) {\n        val = x;\n        left = NULL;\n        right = NULL;\n    }\n};\n\nclass Solution {\npublic:\n    // Function to find max path sum in the tree\n    int maxPathSum(TreeNode* root) {\n        int maxSum = INT_MIN;\n        dfs(root, maxSum);\n        return maxSum;\n    }\n\n    // Helper function for recursive DFS\n    int dfs(TreeNode* node, int &maxSum) {\n        if (!node) return 0;\n\n        // Recursively find left and right max path sums\n        int left = max(0, dfs(node->left, maxSum));\n        int right = max(0, dfs(node->right, maxSum));\n\n        // Update global max sum considering node as turning point\n        maxSum = max(maxSum, left + right + node->val);\n\n        // Return the best one-sided path sum\n        return max(left, right) + node->val;\n    }\n};\n\n// Driver Code\nint main() {\n    TreeNode* root = new TreeNode(-10);\n    root->left = new TreeNode(9);\n    root->right = new TreeNode(20);\n    root->right->left = new TreeNode(15);\n    root->right->right = new TreeNode(7);\n\n    Solution obj;\n    cout << \"Maximum Path Sum: \"\n         << obj.maxPathSum(root) << endl;\n\n    return 0;\n}",
      "py": "# Tree Node Definition\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\nclass Solution:\n    # Main function to call\n    def maxPathSum(self, root):\n        self.max_sum = float('-inf')\n        self.dfs(root)\n        return self.max_sum\n\n    # Recursive DFS helper\n    def dfs(self, node):\n        if not node:\n            return 0\n\n        # Recursively find left and right max path sum\n        left = max(0, self.dfs(node.left))\n        right = max(0, self.dfs(node.right))\n\n        # Update max sum if path through node is better\n        self.max_sum = max(\n            self.max_sum,\n            left + right + node.val\n        )\n\n        # Return one-sided path\n        return max(left, right) + node.val\n\n# Driver Code\nif __name__ == \"__main__\":\n    # Build test tree\n    root = TreeNode(-10)\n    root.left = TreeNode(9)\n    root.right = TreeNode(20)\n    root.right.left = TreeNode(15)\n    root.right.right = TreeNode(7)\n\n    sol = Solution()\n    print(\"Maximum Path Sum:\",\n          sol.maxPathSum(root))"
