      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// TreeNode structure\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n\n    // Constructor to initialize a node\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nclass Solution {\npublic:\n    // Function to build the binary tree from preorder and inorder\n    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {\n        // Map to store the index of each value in inorder\n        map<int, int> inMap;\n\n        // Fill the map with inorder values and their indices\n        for (int i = 0; i < inorder.size(); i++) {\n            inMap[inorder[i]] = i;\n        }\n\n        // Call the recursive helper function\n        return build(preorder, 0, preorder.size() - 1, inorder, 0, inorder.size() - 1, inMap);\n    }\n\nprivate:\n    // Recursive function to build tree using preorder and inorder segments\n    TreeNode* build(vector<int>& preorder, int preStart, int preEnd,\n                    vector<int>& inorder, int inStart, int inEnd, map<int, int>& inMap) {\n        \n        // Base condition\n        if (preStart > preEnd || inStart > inEnd) return nullptr;\n\n        // The first element in preorder is root\n        TreeNode* root = new TreeNode(preorder[preStart]);\n\n        // Find the root index in inorder\n        int inRoot = inMap[root->val];\n\n        // Number of elements in left subtree\n        int numsLeft = inRoot - inStart;\n\n        // Recursively build left and right subtrees\n        root->left = build(preorder, preStart + 1, preStart + numsLeft,\n                           inorder, inStart, inRoot - 1, inMap);\n        root->right = build(preorder, preStart + numsLeft + 1, preEnd,\n                            inorder, inRoot + 1, inEnd, inMap);\n\n        return root;\n    }\n};\n\n// Inorder traversal to print tree\nvoid printInorder(TreeNode* root) {\n    if (!root) return;\n    printInorder(root->left);\n    cout << root->val << \" \";\n    printInorder(root->right);\n}\n\nint main() {\n    vector<int> inorder = {9, 3, 15, 20, 7};\n    vector<int> preorder = {3, 9, 20, 15, 7};\n\n    Solution sol;\n    TreeNode* root = sol.buildTree(preorder, inorder);\n\n    cout << \"Inorder of Unique Binary Tree Created:\\n\";\n    printInorder(root);\n    cout << endl;\n\n    return 0;\n}",
      "py": "# TreeNode structure\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\n# Solution class\nclass Solution:\n    def buildTree(self, preorder, inorder):\n        # Create a hashmap to store inorder indices\n        in_map = {val: idx for idx, val in enumerate(inorder)}\n\n        # Helper function to build tree recursively\n        def build(preStart, preEnd, inStart, inEnd):\n            if preStart > preEnd or inStart > inEnd:\n                return None\n\n            # Root from preorder\n            root_val = preorder[preStart]\n            root = TreeNode(root_val)\n\n            # Find index in inorder\n            inRoot = in_map[root_val]\n            numsLeft = inRoot - inStart\n\n            # Recurse on left and right\n            root.left = build(preStart + 1, preStart + numsLeft, inStart, inRoot - 1)\n            root.right = build(preStart + numsLeft + 1, preEnd, inRoot + 1, inEnd)\n\n            return root\n\n        return build(0, len(preorder) - 1, 0, len(inorder) - 1)\n\n# Inorder print\ndef printInorder(root):\n    if not root:\n        return\n    printInorder(root.left)\n    print(root.val, end=\" \")\n    printInorder(root.right)\n\n# Driver\nif __name__ == \"__main__\":\n    inorder = [9, 3, 15, 20, 7]\n    preorder = [3, 9, 20, 15, 7]\n\n    sol = Solution()\n    root = sol.buildTree(preorder, inorder)\n\n    print(\"Inorder of Unique Binary Tree Created:\")\n    printInorder(root)\n    print()"
