      "mantra": "- Rightmost element in postorder is root; partition inorder array to determine subtree boundaries.\n- Decrement postorder root index; construct right subtree prior to left subtree.\n- Precomputed inorder value-to-index map guarantees optimal O(N) boundary partitioning.",
      "leetcode": "https://leetcode.com/problems/construct-binary-tree-from-inorder-and-postorder-traversal/",
      "tuf": "https://takeuforward.org/data-structure/construct-binary-tree-from-inorder-and-postorder-traversal/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// TreeNode structure\nstruct TreeNode {\n    int val;\n    TreeNode *left, *right;\n\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nclass Solution {\npublic:\n    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {\n        if (inorder.size() != postorder.size()) return nullptr;\n\n        // Map each value in inorder to its index\n        map<int, int> hm;\n        for (int i = 0; i < inorder.size(); i++) {\n            hm[inorder[i]] = i;\n        }\n\n        // Call recursive builder\n        return build(inorder, 0, inorder.size() - 1,\n                     postorder, 0, postorder.size() - 1, hm);\n    }\n\nprivate:\n    TreeNode* build(vector<int>& inorder, int is, int ie,\n                    vector<int>& postorder, int ps, int pe, map<int, int>& hm) {\n        if (ps > pe || is > ie) return nullptr;\n\n        // Last element in postorder is root\n        TreeNode* root = new TreeNode(postorder[pe]);\n\n        // Find root index in inorder\n        int inRoot = hm[postorder[pe]];\n        int numsLeft = inRoot - is;\n\n        // Recursively build left and right subtrees\n        root->left = build(inorder, is, inRoot - 1,\n                           postorder, ps, ps + numsLeft - 1, hm);\n\n        root->right = build(inorder, inRoot + 1, ie,\n                            postorder, ps + numsLeft, pe - 1, hm);\n\n        return root;\n    }\n};\n\n// Inorder printer\nvoid printInorder(TreeNode* root) {\n    if (!root) return;\n    printInorder(root->left);\n    cout << root->val << \" \";\n    printInorder(root->right);\n}\n\n// Driver\nint main() {\n    vector<int> inorder = {40, 20, 50, 10, 60, 30};\n    vector<int> postorder = {40, 50, 20, 60, 30, 10};\n\n    cout << \"Inorder Vector: \";\n    for (int x : inorder) cout << x << \" \";\n    cout << \"\\nPostorder Vector: \";\n    for (int x : postorder) cout << x << \" \";\n    cout << endl;\n\n    Solution sol;\n    TreeNode* root = sol.buildTree(inorder, postorder);\n\n    cout << \"Inorder of Unique Binary Tree Created:\\n\";\n    printInorder(root);\n    cout << endl;\n\n    return 0;\n}",
      "py": "class TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\nclass Solution:\n    def buildTree(self, inorder, postorder):\n        if len(inorder) != len(postorder):\n            return None\n        hm = {val: idx for idx, val in enumerate(inorder)}\n        return self._build(inorder, 0, len(inorder) - 1,\n                           postorder, 0, len(postorder) - 1, hm)\n\n    def _build(self, inorder, is_, ie, postorder, ps, pe, hm):\n        if ps > pe or is_ > ie:\n            return None\n        root_val = postorder[pe]\n        root = TreeNode(root_val)\n        inRoot = hm[root_val]\n        numsLeft = inRoot - is_\n        root.left = self._build(inorder, is_, inRoot - 1,\n                                postorder, ps, ps + numsLeft - 1, hm)\n        root.right = self._build(inorder, inRoot + 1, ie,\n                                 postorder, ps + numsLeft, pe - 1, hm)\n        return root\n\ndef printInorder(root):\n    if not root:\n        return\n    printInorder(root.left)\n    print(root.val, end=\" \")\n    printInorder(root.right)\n\nif __name__ == \"__main__\":\n    inorder = [40, 20, 50, 10, 60, 30]\n    postorder = [40, 50, 20, 60, 30, 10]\n    print(\"Inorder Vector:\", inorder)\n    print(\"Postorder Vector:\", postorder)\n\n    sol = Solution()\n    root = sol.buildTree(inorder, postorder)\n    print(\"Inorder of Unique Binary Tree Created:\")\n    printInorder(root)\n    print()"
