      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Connect inorder predecessor's right pointer to current node to establish temporary return thread.\n- If predecessor.right is null, create thread and move left; if thread exists, sever thread, visit node, move right.\n- Eliminates call stack and auxiliary structures while preserving original tree topology.",
      "leetcode": "https://leetcode.com/problems/binary-tree-inorder-traversal/",
      "tuf": "https://takeuforward.org/data-structure/morris-inorder-traversal-of-a-binary-tree/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// TreeNode structure\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nclass Solution {\npublic:\n    // Function to perform iterative Morris\n    // inorder traversal of a binary tree\n    vector<int> getInorder(TreeNode* root) {\n        // Vector to store the\n        // inorder traversal result\n        vector<int> inorder;\n        // Pointer to the current node,\n        // starting from the root\n        TreeNode* cur = root;\n        \n        // Loop until the current\n        // node is not NULL\n        while (cur != NULL) {\n            // If the current node's\n            // left child is NULL\n            if (cur->left == NULL) {\n                // Add the value of the current\n                // node to the inorder vector\n                inorder.push_back(cur->val);\n                // Move to the right child\n                cur = cur->right;\n            } else {\n                // If the left child is not NULL,\n                // find the predecessor (rightmost node\n                // in the left subtree)\n                TreeNode* prev = cur->left;\n                while (prev->right && prev->right != cur) {\n                    prev = prev->right;\n                }\n                \n                // If the predecessor's right child\n                // is NULL, establish a temporary link\n                // and move to the left child\n                if (prev->right == NULL) {\n                    prev->right = cur;\n                    cur = cur->left;\n                } else {\n                    // If the predecessor's right child\n                    // is already linked, remove the link,\n                    // add current node to inorder vector,\n                    // and move to the right child\n                    prev->right = NULL;\n                    inorder.push_back(cur->val);\n                    cur = cur->right;\n                }\n            }\n        }\n        \n        // Return the inorder\n        // traversal result\n        return inorder;\n    }\n};\n\n\nint main() {\n\n    TreeNode* root = new TreeNode(1);\n    root->left = new TreeNode(2);\n    root->right = new TreeNode(3);\n    root->left->left = new TreeNode(4);\n    root->left->right = new TreeNode(5);\n    root->left->right->right = new TreeNode(6);\n\n    Solution sol;\n    \n    vector<int> inorder = sol.getInorder(root);\n\n    cout << \"Binary Tree Morris Inorder Traversal: \";\n    for(int i = 0; i< inorder.size(); i++){\n        cout << inorder[i] << \" \";\n    }\n    cout << endl;\n\n    return 0;\n}",
      "py": "# TreeNode structure\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\nclass Solution:\n    def getInorder(self, root):\n        # Vector to store the\n        # inorder traversal result\n        inorder = []\n        # Pointer to the current node,\n        # starting from the root\n        cur = root\n\n        # Loop until the current\n        # node is not None\n        while cur is not None:\n            # If the current node's\n            # left child is None\n            if cur.left is None:\n                # Add the value of the current\n                # node to the inorder list\n                inorder.append(cur.val)\n                # Move to the right child\n                cur = cur.right\n            else:\n                # If the left child is not None,\n                # find the predecessor (rightmost node\n                # in the left subtree)\n                prev = cur.left\n                while prev.right and prev.right != cur:\n                    prev = prev.right\n\n                # If the predecessor's right child\n                # is None, establish a temporary link\n                # and move to the left child\n                if prev.right is None:\n                    prev.right = cur\n                    cur = cur.left\n                else:\n                    # If the predecessor's right child\n                    # is already linked, remove the link,\n                    # add the current node to inorder list,\n                    # and move to the right child\n                    prev.right = None\n                    inorder.append(cur.val)\n                    cur = cur.right\n\n        # Return the inorder\n        # traversal result\n        return inorder\n\n\nif __name__ == \"__main__\":\n    root = TreeNode(1)\n    root.left = TreeNode(2)\n    root.right = TreeNode(3)\n    root.left.left = TreeNode(4)\n    root.left.right = TreeNode(5)\n    root.left.right.right = TreeNode(6)\n\n    sol = Solution()\n\n    inorder = sol.getInorder(root)\n\n    print(\"Binary Tree Morris Inorder Traversal:\", end=\" \")\n    for val in inorder:\n        print(val, end=\" \")\n    print()"
