      "title": "Find and return the node with value equal to key in a BST, or null if it does not exist.",
      "canonicalName": "Search in BST",
      "difficulty": "Easy",
      "bounds": "Time Complexity: $\\mathcal{O}(H)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Compare target with current node value to bisect the tree.\n- Step left if target is smaller, step right if larger, return node on match.\n- Return null immediately when encountering a leaf pointer.",
      "leetcode": "https://leetcode.com/problems/search-in-a-binary-search-tree/",
      "tuf": "https://takeuforward.org/data-structure/search-in-a-binary-search-tree-2/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Definition of TreeNode\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n\n    TreeNode(int data) {\n        val = data;\n        left = right = nullptr;\n    }\n};\n\nclass Solution {\npublic:\n    // Function to search for a node with given key in BST\n    TreeNode* searchBST(TreeNode* root, int target) {\n\n        // Traverse until we reach a null node or the target is found\n        while (root != nullptr && root->val != target) {\n\n            // If target is less than current node, go left\n            if (target < root->val) {\n                root = root->left;\n            }\n\n            // If target is greater than current node, go right\n            else {\n                root = root->right;\n            }\n        }\n\n        // Return node if found, else nullptr\n        return root;\n    }\n};\n\n// Driver code\nint main() {\n    TreeNode* root = new TreeNode(4);\n    root->left = new TreeNode(2);\n    root->right = new TreeNode(7);\n    root->left->left = new TreeNode(1);\n    root->left->right = new TreeNode(3);\n\n    Solution obj;\n    TreeNode* result = obj.searchBST(root, 2);\n\n    if (result)\n        cout << \"Node found: \" << result->val << endl;\n    else\n        cout << \"Node not found\" << endl;\n\n    return 0;\n}",
      "py": "# Definition for a binary tree node\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\nclass Solution:\n    # Function to search target in BST\n    def searchBST(self, root, target):\n\n        # Loop until current node is null or matches target\n        while root and root.val != target:\n\n            # If target is smaller, go to left subtree\n            if target < root.val:\n                root = root.left\n\n            # If target is larger, go to right subtree\n            else:\n                root = root.right\n\n        # Return the node if found or None if not\n        return root\n\n# Driver code\nroot = TreeNode(4)\nroot.left = TreeNode(2)\nroot.right = TreeNode(7)\nroot.left.left = TreeNode(1)\nroot.left.right = TreeNode(3)\n\nobj = Solution()\nresult = obj.searchBST(root, 2)\n\nif result:\n    print(\"Node found:\", result.val)\nelse:\n    print(\"Node not found\")"
