      "mantra": "- Propagate open dynamic bounds $(\\text{min\\_val}, \\text{max\\_val})$ downwards through traversal.\n- Verify node value strictly inside range, then recurse left with upper bound and right with lower bound.\n- Initialize bounds with 64-bit limits to prevent overflow when nodes equal 32-bit integer limits.",
      "leetcode": "",
      "tuf": "",
      "cpp": "#include <climits>\n\n/**\n * Definition for a binary tree node.\n * struct TreeNode {\n *     int val;\n *     TreeNode *left;\n *     TreeNode *right;\n *     TreeNode() : val(0), left(nullptr), right(nullptr) {}\n *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}\n * };\n */\n\nclass Solution {\nprivate:\n    // Helper function to validate BST using 64-bit bounds to avoid overflow\n    bool validate(TreeNode* node, long long minVal, long long maxVal) {\n        // An empty subtree is always valid\n        if (node == nullptr) {\n            return true;\n        }\n\n        // Current node value must lie strictly within (minVal, maxVal)\n        if (node->val <= minVal || node->val >= maxVal) {\n            return false;\n        }\n\n        // Left subtree must be in (minVal, node->val)\n        // Right subtree must be in (node->val, maxVal)\n        return validate(node->left, minVal, node->val) &&\n               validate(node->right, node->val, maxVal);\n    }\n\npublic:\n    bool isValidBST(TreeNode* root) {\n        return validate(root, LLONG_MIN, LLONG_MAX);\n    }\n};",
      "py": "from typing import Optional\n\n# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\n\nclass Solution:\n    def isValidBST(self, root: Optional[TreeNode]) -> bool:\n        def validate(node: Optional[TreeNode], min_val: float, max_val: float) -> bool:\n            # An empty subtree is always valid\n            if not node:\n                return True\n            \n            # Current node value must lie strictly within (min_val, max_val)\n            if not (min_val < node.val < max_val):\n                return False\n            \n            # Left subtree must be in (min_val, node.val)\n            # Right subtree must be in (node.val, max_val)\n            return validate(node.left, min_val, node.val) and validate(node.right, node.val, max_val)\n\n        return validate(root, float('-inf'), float('inf'))"
