      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(H)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Bisect search space while updating closest candidate ancestors.\n- Moving right records current node as predecessor candidate; moving left records successor candidate.\n- If node with key exists and has subtrees, predecessor is maximum of left; successor is minimum of right.",
      "leetcode": "https://leetcode.com/problems/inorder-successor-in-bst/",
      "tuf": "https://takeuforward.org/data-structure/inorder-successorpredecessor-in-bst",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// define tree node structure\nstruct TreeNode {\n    // value of the node\n    int val;\n    // pointer to left child\n    TreeNode* left;\n    // pointer to right child\n    TreeNode* right;\n    // constructor\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\n// solution class\nclass Solution {\npublic:\n    // find inorder successor iteratively\n    TreeNode* inorderSuccessor(TreeNode* root, TreeNode* p) {\n        // initialize successor\n        TreeNode* successor = nullptr;\n        // traverse until root becomes null\n        while (root != nullptr) {\n            // when p is greater or equal, move right\n            if (p->val >= root->val) {\n                root = root->right;\n            }\n            // otherwise update successor and move left\n            else {\n                successor = root;\n                root = root->left;\n            }\n        }\n        // return successor (may be null)\n        return successor;\n    }\n};\n\n// inorder print helper\nvoid printInOrder(TreeNode* root) {\n    // base case\n    if (root == nullptr) return;\n    // traverse left\n    printInOrder(root->left);\n    // print node\n    cout << root->val << \" \";\n    // traverse right\n    printInOrder(root->right);\n}\n\n// program entry\nint main() {\n    // construct BST\n    TreeNode* root = new TreeNode(5);\n    root->left = new TreeNode(3);\n    root->right = new TreeNode(6);\n    root->left->left = new TreeNode(2);\n    root->left->right = new TreeNode(4);\n    root->right->right = new TreeNode(7);\n\n    // show inorder\n    cout << \"BST: \";\n    printInOrder(root);\n    cout << endl;\n\n    // target node p\n    TreeNode* p = root->left->right;\n\n    // find successor\n    Solution solution;\n    TreeNode* successor = solution.inorderSuccessor(root, p);\n\n    // print result\n    if (successor != nullptr) {\n        cout << \"Inorder Successor of \" << p->val << \" is: \" << successor->val << endl;\n    } else {\n        cout << \"Inorder Successor of \" << p->val << \" does not exist.\" << endl;\n    }\n\n    // exit\n    return 0;\n}",
      "py": "# define tree node structure\nclass TreeNode:\n    # constructor\n    def __init__(self, x: int):\n        # value of the node\n        self.val = x\n        # left child reference\n        self.left = None\n        # right child reference\n        self.right = None\n\n# solution class\nclass Solution:\n    # find inorder successor iteratively\n    def inorderSuccessor(self, root: 'TreeNode', p: 'TreeNode') -> 'TreeNode | None':\n        # initialize successor\n        successor = None\n        # traverse until root becomes None\n        while root is not None:\n            # when p is greater or equal, move right\n            if p.val >= root.val:\n                root = root.right\n            # otherwise update successor and move left\n            else:\n                successor = root\n                root = root.left\n        # return successor (may be None)\n        return successor\n\n# inorder print helper\ndef print_in_order(root: 'TreeNode | None') -> None:\n    # base case\n    if root is None:\n        return\n    # traverse left\n    print_in_order(root.left)\n    # print node\n    print(root.val, end=\" \")\n    # traverse right\n    print_in_order(root.right)\n\n# program entry\ndef main():\n    # construct BST\n    root = TreeNode(5)\n    root.left = TreeNode(3)\n    root.right = TreeNode(6)\n    root.left.left = TreeNode(2)\n    root.left.right = TreeNode(4)\n    root.right.right = TreeNode(7)\n\n    # show inorder\n    print(\"BST: \", end=\"\")\n    print_in_order(root)\n    print()\n\n    # target node p\n    p = root.left.right\n\n    # find successor\n    solution = Solution()\n    successor = solution.inorderSuccessor(root, p)\n\n    # print result\n    if successor is not None:\n        print(f\"Inorder Successor of {p.val} is: {successor.val}\")\n    else:\n        print(f\"Inorder Successor of {p.val} does not exist.\")\n\n# run main\nif __name__ == \"__main__\":\n    main()"
