      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Definition for a binary tree node.\n  struct TreeNode {\n      int data;\n      TreeNode *left;\n      TreeNode *right;\n      TreeNode(int val) : data(val), left(nullptr), right(nullptr) {}\n };\n \nclass Solution {\npublic:\n    // Function to find the kth smallest element\n    int kthSmallest(TreeNode* root, int k) {\n        this->k = k;\n        this->result = -1;\n        inorder(root);\n        return result;\n    }\n\n    // Function to find the kth largest element\n    int kthLargest(TreeNode* root, int k) {\n        this->k = k;\n        this->result = -1;\n        reverse_inorder(root);\n        return result;\n    }\n\n    // Function to return kth smallest and kth largest elements\n    vector<int> kLargesSmall(TreeNode* root, int k) {\n        return {kthSmallest(root, k), kthLargest(root, k)};\n    }\n\nprivate:\n    int k;\n    int result;\n\n    // Helper function for inorder traversal\n    void inorder(TreeNode* node) {\n        if (node != nullptr) {\n            inorder(node->left);\n            if (--k == 0) {\n                result = node->data;\n                return;\n            }\n            inorder(node->right);\n        }\n    }\n\n    // Helper function for reverse inorder traversal\n    void reverse_inorder(TreeNode* node) {\n        if (node != nullptr) {\n            reverse_inorder(node->right);\n            if (--k == 0) {\n                result = node->data;\n                return;\n            }\n            reverse_inorder(node->left);\n        }\n    }\n};\n\n// Main method to demonstrate the function\nint main() {\n    // Constructing the tree: [3, 1, 4, nullptr, 2]\n    TreeNode* root = new TreeNode(3);\n    root->left = new TreeNode(1);\n    root->left->right = new TreeNode(2);\n    root->right = new TreeNode(4);\n    \n    Solution solution;\n    int k = 1;\n    vector<int> result = solution.kLargesSmall(root, k);\n    \n    // Output the result\n    cout << \"[\" << result[0] << \", \" << result[1] << \"]\" << endl; // Output: [1, 4]\n    \n    return 0;\n}",
      "py": "# Definition for a binary tree node.\nclass TreeNode(object):\n    def __init__(self, val=0, left=None, right=None):\n        self.data = val\n        self.left = left\n        self.right = right\n\nclass Solution:\n    # Function to find the kth smallest element\n    def kthSmallest(self, root, k):\n        self.k = k\n        self.result = None\n        self.inorder(root)\n        return self.result\n\n    # Helper function for inorder traversal\n    def inorder(self, node):\n        if node is not None:\n            self.inorder(node.left)\n            self.k -= 1\n            if self.k == 0:\n                self.result = node.data\n                return\n            self.inorder(node.right)\n\n    # Function to find the kth largest element\n    def kthLargest(self, root, k):\n        self.k = k\n        self.result = None\n        self.reverse_inorder(root)\n        return self.result\n\n    # Helper function for reverse inorder traversal\n    def reverse_inorder(self, node):\n        if node is not None:\n            self.reverse_inorder(node.right)\n            self.k -= 1\n            if self.k == 0:\n                self.result = node.data\n                return\n            self.reverse_inorder(node.left)\n\n    # Function to return kth smallest and kth largest elements\n    def kLargesSmall(self, root, k):\n        return [self.kthSmallest(root, k), self.kthLargest(root, k)]\n\n# Example usage\nif __name__ == \"__main__\":\n    # Constructing the tree: [3, 1, 4, None, 2]\n    root = TreeNode(3)\n    root.left = TreeNode(1)\n    root.left.right = TreeNode(2)\n    root.right = TreeNode(4)\n    \n    solution = Solution()\n    k = 1\n    result = solution.kLargesSmall(root, k)\n    \n    print(result)  # Output: [1, 4]"
