      "patternName": "Binary Search Tree Ordered Invariants",
      "problemSeq": 12,
      "title": "Merge two binary search trees into a single sorted array of all elements.",
      "canonicalName": "BST iterator",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(N_1 + N_2)$ | Space Complexity: $\\mathcal{O}(H_1 + H_2)$",
      "mantra": "- Maintain two explicit in-order generator stacks simultaneously.\n- Peek stack tops, pop the smaller element to append to output, and advance its subtree.\n- Amortized $\\mathcal{O}(1)$ push/pop operations maintain optimal linear streaming runtime.",
      "leetcode": "https://leetcode.com/problems/binary-search-tree-iterator/",
      "tuf": "https://takeuforward.org/data-structure/bst-iterator",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Structure for a binary tree node\nstruct Node {\n    int data;\n    Node* left;\n    Node* right;\n    // Constructor to initialize node\n    Node(int val) : data(val), left(NULL), right(NULL) {}\n};\n\nclass Solution {\npublic:\n    // Function to perform inorder traversal and store elements\n    void inorderTraversal(Node* root, vector<int>& arr) {\n        // Base case\n        if (!root) return;\n        // Traverse left subtree\n        inorderTraversal(root->left, arr);\n        // Store current node data\n        arr.push_back(root->data);\n        // Traverse right subtree\n        inorderTraversal(root->right, arr);\n    }\n\n    // Function to merge two sorted arrays\n    vector<int> mergeArrays(vector<int>& arr1, vector<int>& arr2) {\n        // Initialize result array\n        vector<int> merged;\n        // Initialize pointers\n        int i = 0, j = 0;\n        // Merge until one array ends\n        while (i < arr1.size() && j < arr2.size()) {\n            if (arr1[i] < arr2[j]) merged.push_back(arr1[i++]);\n            else merged.push_back(arr2[j++]);\n        }\n        // Add remaining elements\n        while (i < arr1.size()) merged.push_back(arr1[i++]);\n        while (j < arr2.size()) merged.push_back(arr2[j++]);\n        return merged;\n    }\n\n    // Function to merge two BSTs in sorted order\n    vector<int> mergeBSTs(Node* root1, Node* root2) {\n        // Arrays to store inorder traversals\n        vector<int> arr1, arr2;\n        // Perform inorder traversal on first BST\n        inorderTraversal(root1, arr1);\n        // Perform inorder traversal on second BST\n        inorderTraversal(root2, arr2);\n        // Merge and return the result\n        return mergeArrays(arr1, arr2);\n    }\n};\n\n// Driver code\nint main() {\n    // Create first BST\n    Node* root1 = new Node(3);\n    root1->left = new Node(1);\n    root1->right = new Node(5);\n\n    // Create second BST\n    Node* root2 = new Node(4);\n    root2->left = new Node(2);\n    root2->right = new Node(6);\n\n    // Create Solution object\n    Solution sol;\n    // Merge the BSTs\n    vector<int> result = sol.mergeBSTs(root1, root2);\n\n    // Print result\n    for (int val : result) cout << val << \" \";\n    return 0;\n}",
      "py": "# Node structure for BST\nclass Node:\n    def __init__(self, val):\n        self.data = val\n        self.left = None\n        self.right = None\n\nclass Solution:\n    # Function to perform inorder traversal\n    def inorderTraversal(self, root, arr):\n        # Base case\n        if not root:\n            return\n        # Traverse left subtree\n        self.inorderTraversal(root.left, arr)\n        # Store current node data\n        arr.append(root.data)\n        # Traverse right subtree\n        self.inorderTraversal(root.right, arr)\n\n    # Function to merge two sorted lists\n    def mergeArrays(self, arr1, arr2):\n        # Initialize result\n        merged = []\n        # Initialize pointers\n        i = j = 0\n        # Merge until one list ends\n        while i < len(arr1) and j < len(arr2):\n            if arr1[i] < arr2[j]:\n                merged.append(arr1[i])\n                i += 1\n            else:\n                merged.append(arr2[j])\n                j += 1\n        # Add remaining elements\n        merged.extend(arr1[i:])\n        merged.extend(arr2[j:])\n        return merged\n\n    # Function to merge two BSTs\n    def mergeBSTs(self, root1, root2):\n        # Lists to store inorder traversals\n        arr1, arr2 = [], []\n        # Perform inorder traversals\n        self.inorderTraversal(root1, arr1)\n        self.inorderTraversal(root2, arr2)\n        # Merge and return\n        return self.mergeArrays(arr1, arr2)\n\n# Driver code\nif __name__ == \"__main__\":\n    # Create first BST\n    root1 = Node(3)\n    root1.left = Node(1)\n    root1.right = Node(5)\n\n    # Create second BST\n    root2 = Node(4)\n    root2.left = Node(2)\n    root2.right = Node(6)\n\n    # Create Solution object\n    sol = Solution()\n    # Merge BSTs\n    result = sol.mergeBSTs(root1, root2)\n\n    # Print result\n    print(*result)"
