      "id": 141,
      "patternId": 12,
      "patternName": "Graph Search and Topological Sort",
      "problemSeq": 1,
      "title": "Traverse an undirected graph from a starting vertex using Depth-First Search and return the visitation order.",
      "canonicalName": "DFS",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(V + E)$ | Space Complexity: $\\mathcal{O}(V)$",
      "mantra": "- Maintain a boolean visited array to guarantee each vertex and incident edge is explored exactly once.\n- Recursively traverse unvisited adjacent nodes, appending each node to the traversal list upon entry.\n- Ensure all disconnected components are covered by looping through all vertices as potential roots.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/depth-first-search-dfs/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to perform DFS traversal\n    void dfs(int v, vector<int> adj[], \n             vector<int>& visited, \n             vector<int>& result) {\n        \n        // Mark current node as visited\n        visited[v] = 1;\n\n        // Store node in result\n        result.push_back(v);\n\n        // Traverse all neighbours\n        for (int u : adj[v]) {\n            if (!visited[u]) {\n                dfs(u, adj, visited, result);\n            }\n        }\n    }\n};\n\nint main() {\n    // Number of vertices\n    int V = 5;\n\n    // Adjacency list\n    vector<int> adj[V];\n    adj[0] = {1, 2};\n    adj[1] = {0, 3};\n    adj[2] = {0, 4};\n    adj[3] = {1};\n    adj[4] = {2};\n\n    // Visited array\n    vector<int> visited(V, 0);\n\n    // Result vector\n    vector<int> result;\n\n    // Create object\n    Solution sol;\n\n    // Run DFS from node 0\n    sol.dfs(0, adj, visited, result);\n\n    // Print traversal\n    for (int x : result) cout << x << \" \";\n    cout << endl;\n\n    return 0;\n}",
      "py": "class Solution:\n    # Function to perform DFS traversal\n    def dfs(self, v, adj, visited, result):\n        # Mark current node as visited\n        visited[v] = True\n\n        # Store node in result\n        result.append(v)\n\n        # Traverse all neighbours\n        for u in adj[v]:\n            if not visited[u]:\n                self.dfs(u, adj, visited, result)\n\n\ndef main():\n    # Number of vertices\n    V = 5\n\n    # Adjacency list\n    adj = [[] for _ in range(V)]\n    adj[0] = [1, 2]\n    adj[1] = [0, 3]\n    adj[2] = [0, 4]\n    adj[3] = [1]\n    adj[4] = [2]\n\n    # Visited array\n    visited = [False] * V\n\n    # Result list\n    result = []\n\n    # Create object\n    sol = Solution()\n\n    # Run DFS from node 0\n    sol.dfs(0, adj, visited, result)\n\n    # Print traversal\n    print(\" \".join(map(str, result)))\n\n\nif __name__ == \"__main__\":\n    main()"
