      "mantra": "- Iterate across the grid; each unvisited '1' initiates a complete component flood via BFS or DFS.\n- Increment the global island counter once per component initiation and mutate visited land cells to '0'.\n- Mutating the grid in-place eliminates auxiliary visited matrix overhead but modifies input data.",
      "leetcode": "https://leetcode.com/problems/number-of-islands/",
      "tuf": "https://takeuforward.org/data-structure/number-of-distinct-islands/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std\n\nclass Solution {\npublic:\n    // DFS traversal\n    void dfs(int row, int col, int baseRow, int baseCol,\n             vector<vector<int>>& grid, vector<vector<int>>& vis,\n             vector<pair<int, int>>& shape) {\n        // Mark as visited\n        vis[row][col] = 1;\n        // Store relative position\n        shape.push_back({row - baseRow, col - baseCol});\n\n        // All 4 directions\n        int drow[] = {-1, 0, 1, 0};\n        int dcol[] = {0, 1, 0, -1};\n\n        // Explore all directions\n        for (int i = 0; i < 4; i++) {\n            int nrow = row + drow[i];\n            int ncol = col + dcol[i];\n\n            // Check bounds and if land and not visited\n            if (nrow >= 0 && nrow < grid.size() &&\n                ncol >= 0 && ncol < grid[0].size() &&\n                !vis[nrow][ncol] && grid[nrow][ncol] == 1) {\n                dfs(nrow, ncol, baseRow, baseCol, grid, vis, shape);\n            }\n        }\n    }\n\n    // Main function to return number of distinct islands\n    int countDistinctIslands(vector<vector<int>>& grid) {\n        int n = grid.size();\n        int m = grid[0].size();\n        vector<vector<int>> vis(n, vector<int>(m, 0));\n        set<vector<pair<int, int>>> st;\n\n        // Traverse grid\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < m; j++) {\n                // If land and not visited\n                if (grid[i][j] == 1 && !vis[i][j]) {\n                    vector<pair<int, int>> shape;\n                    dfs(i, j, i, j, grid, vis, shape);\n                    st.insert(shape);\n                }\n            }\n        }\n        return st.size();\n    }\n};\n\n// Driver code\nint main() {\n    vector<vector<int>> grid = {\n        {1, 1, 0, 0},\n        {1, 0, 0, 0},\n        {0, 0, 1, 1},\n        {0, 0, 1, 1}\n    };\n    Solution obj;\n    cout << obj.countDistinctIslands(grid);\n    return 0;\n}",
      "py": "# Class to find number of distinct islands\nclass Solution:\n    # DFS function\n    def dfs(self, row, col, baseRow, baseCol, grid, vis, shape):\n        # Mark visited\n        vis[row][col] = True\n        # Add relative position\n        shape.append((row - baseRow, col - baseCol))\n\n        # 4 directions\n        drow = [-1, 0, 1, 0]\n        dcol = [0, 1, 0, -1]\n\n        # Explore all directions\n        for i in range(4):\n            nrow = row + drow[i]\n            ncol = col + dcol[i]\n            # Check bounds and unvisited land\n            if (0 <= nrow < len(grid) and 0 <= ncol < len(grid[0]) and\n                not vis[nrow][ncol] and grid[nrow][ncol] == 1):\n                self.dfs(nrow, ncol, baseRow, baseCol, grid, vis, shape)\n\n    # Main function to count distinct islands\n    def countDistinctIslands(self, grid):\n        n, m = len(grid), len(grid[0])\n        vis = [[False for _ in range(m)] for _ in range(n)]\n        st = set()\n\n        # Traverse grid\n        for i in range(n):\n            for j in range(m):\n                if grid[i][j] == 1 and not vis[i][j]:\n                    shape = []\n                    self.dfs(i, j, i, j, grid, vis, shape)\n                    st.add(tuple(shape))\n        return len(st)\n\n# Driver code\ngrid = [\n    [1, 1, 0, 0],\n    [1, 0, 0, 0],\n    [0, 0, 1, 1],\n    [0, 0, 1, 1]\n]\nobj = Solution()\nprint(obj.countDistinctIslands(grid))"
