      "leetcode": "https://leetcode.com/problems/is-graph-bipartite/",
      "tuf": "https://takeuforward.org/graph/bipartite-graph-dfs-implementation/",
      "cpp": "#include<bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\nprivate: \n    bool dfs(int node, int col, int color[], vector<int> adj[]) {\n        color[node] = col; \n        \n        // traverse adjacent nodes\n        for(auto it : adj[node]) {\n            // if uncoloured\n            if(color[it] == -1) {\n                if(dfs(it, !col, color, adj) == false) return false; \n            }\n            // if previously coloured and have the same colour\n            else if(color[it] == col) {\n                return false; \n            }\n        }\n        \n        return true; \n    }\npublic:\n\tbool isBipartite(int V, vector<int>adj[]){\n\t    int color[V];\n\t    for(int i = 0;i<V;i++) color[i] = -1; \n\t    \n\t    // for connected components\n\t    for(int i = 0;i<V;i++) {\n\t        if(color[i] == -1) {\n\t            if(dfs(i, 0, color, adj) == false) \n\t                return false; \n\t        }\n\t    }\n\t    return true; \n\t}\n};\n\nvoid addEdge(vector <int> adj[], int u, int v) {\n    adj[u].push_back(v);\n    adj[v].push_back(u);\n}\n\nint main(){\n\t\n\t// V = 4, E = 4\n\tvector<int>adj[4];\n\t\n\taddEdge(adj, 0, 2);\n   \taddEdge(adj, 0, 3);\n\taddEdge(adj, 2, 3);\n\taddEdge(adj, 3, 1);\n\n\tSolution obj;\n\tbool ans = obj.isBipartite(4, adj);    \n\tif(ans)cout << \"1\\n\";\n\telse cout << \"0\\n\";  \n\t\n\treturn 0;\n}",
      "py": "class Solution:\n    def isBipartite(self, V: int, adj: list[list[int]]) -> bool:\n        \"\"\"Determines whether an undirected graph is bipartite using DFS.\"\"\"\n        color = [-1] * V\n\n        def dfs(node: int, col: int) -> bool:\n            color[node] = col\n\n            for neighbor in adj[node]:\n                # If the neighbor is uncolored, recursively color it with the opposite color\n                if color[neighbor] == -1:\n                    if not dfs(neighbor, 1 - col):\n                        return False\n                # If the neighbor has the same color, the graph is not bipartite\n                elif color[neighbor] == col:\n                    return False\n\n            return True\n\n        # Check each component of the graph\n        for i in range(V):\n            if color[i] == -1:\n                if not dfs(i, 0):\n                    return False\n\n        return True\n\n\nif __name__ == \"__main__\":\n    V = 4\n    adj = [[] for _ in range(V)]\n\n    def add_edge(u: int, v: int) -> None:\n        adj[u].append(v)\n        adj[v].append(u)\n\n    add_edge(0, 2)\n    add_edge(0, 3)\n    add_edge(2, 3)\n    add_edge(3, 1)\n\n    obj = Solution()\n    ans = obj.isBipartite(V, adj)\n    print(\"1\" if ans else \"0\")"
