      "title": "Detect whether a directed graph contains a cycle using Depth-First Search.",
      "canonicalName": "Detect A cycle in a Directed Graph using DFS",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(V + E)$ | Space Complexity: $\\mathcal{O}(V)$",
      "mantra": "- Maintain two tracking arrays: a global visited array and an active path recursion stack array.\n- Discovering an edge leading to an active node on the current recursion path identifies a directed back-edge.\n- Crucially clear the active path flag for vertex $u$ when backtracking out of its call frame.",
      "leetcode": "https://leetcode.com/problems/course-schedule/",
      "tuf": "https://takeuforward.org/data-structure/detect-a-cycle-in-directed-graph-topological-sort-kahns-algorithm-g-23/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // Function to detect cycle in a directed graph using Kahn's Algorithm\n    bool hasCycle(int V, vector<vector<int>>& adj) {\n        // Store in-degrees of all nodes\n        vector<int> indegree(V, 0);\n        for (int u = 0; u < V; u++) {\n            for (int v : adj[u]) {\n                indegree[v]++;\n            }\n        }\n\n        // Queue for nodes with 0 in-degree\n        queue<int> q;\n        for (int i = 0; i < V; i++) {\n            if (indegree[i] == 0) q.push(i);\n        }\n\n        // Count visited nodes\n        int count = 0;\n        while (!q.empty()) {\n            int node = q.front();\n            q.pop();\n            count++;\n\n            // Reduce in-degree of neighbors\n            for (int neighbor : adj[node]) {\n                indegree[neighbor]--;\n                if (indegree[neighbor] == 0) {\n                    q.push(neighbor);\n                }\n            }\n        }\n\n        // If count != V, cycle exists\n        return count != V;\n    }\n};\n\nint main() {\n    int V = 4;\n    vector<vector<int>> adj = {\n        {1}, {2}, {3}, {1}\n    };\n\n    Solution obj;\n    if (obj.hasCycle(V, adj))\n        cout << \"Cycle detected\\n\";\n    else\n        cout << \"No cycle\\n\";\n    return 0;\n}",
      "py": "from collections import deque\n\nclass Solution:\n    # Function to detect cycle in a directed graph using Kahn's Algorithm\n    def hasCycle(self, V, adj):\n        # Store in-degrees of all nodes\n        indegree = [0] * V\n        for u in range(V):\n            for v in adj[u]:\n                indegree[v] += 1\n\n        # Queue for nodes with 0 in-degree\n        q = deque()\n        for i in range(V):\n            if indegree[i] == 0:\n                q.append(i)\n\n        # Count visited nodes\n        count = 0\n        while q:\n            node = q.popleft()\n            count += 1\n\n            # Reduce in-degree of neighbors\n            for neighbor in adj[node]:\n                indegree[neighbor] -= 1\n                if indegree[neighbor] == 0:\n                    q.append(neighbor)\n\n        # If count != V, cycle exists\n        return count != V\n\n\nif __name__ == \"__main__\":\n    V = 4\n    adj = [[1], [2], [3], [1]]\n\n    obj = Solution()\n    if obj.hasCycle(V, adj):\n        print(\"Cycle detected\")\n    else:\n        print(\"No cycle\")"
