      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(V + E)$ | Space Complexity: $\\mathcal{O}(V)$",
      "mantra": "- Compute in-degrees of all vertices and enqueue all nodes with an initial in-degree of 0.\n- Decrement in-degrees of adjacent neighbors upon dequeuing, pushing newly zeroed nodes.\n- If the total count of dequeued vertices is strictly less than $V$, a cycle exists.",
      "leetcode": "",
      "tuf": "",
      "cpp": "#include <vector>\n#include <queue>\n\nclass Solution {\npublic:\n    /**\n     * Detects if a directed graph contains a cycle using Kahn's Algorithm (BFS).\n     * \n     * @param V Number of vertices in the graph.\n     * @param adj Adjacency list representation of the directed graph.\n     * @return true if a cycle exists, false otherwise.\n     */\n    bool isCyclic(int V, const std::vector<std::vector<int>>& adj) {\n        std::vector<int> inDegree(V, 0);\n\n        // Step 1: Calculate the in-degree of each node\n        for (int u = 0; u < V; ++u) {\n            for (int v : adj[u]) {\n                inDegree[v]++;\n            }\n        }\n\n        // Step 2: Push all nodes with in-degree 0 into the queue\n        std::queue<int> q;\n        for (int i = 0; i < V; ++i) {\n            if (inDegree[i] == 0) {\n                q.push(i);\n            }\n        }\n\n        // Step 3: Process the nodes using BFS\n        int visitedCount = 0;\n        while (!q.empty()) {\n            int node = q.front();\n            q.pop();\n            visitedCount++;\n\n            for (int neighbor : adj[node]) {\n                inDegree[neighbor]--;\n                if (inDegree[neighbor] == 0) {\n                    q.push(neighbor);\n                }\n            }\n        }\n\n        // If the number of processed nodes is not equal to V, a cycle exists\n        return visitedCount != V;\n    }\n};",
      "py": "from collections import deque\nfrom typing import List\n\nclass Solution:\n    def isCyclic(self, V: int, adj: List[List[int]]) -> bool:\n        \"\"\"\n        Detects if a directed graph contains a cycle using Kahn's Algorithm (BFS).\n        \n        :param V: Number of vertices in the graph.\n        :param adj: Adjacency list representation of the directed graph.\n        :return: True if a cycle exists, False otherwise.\n        \"\"\"\n        in_degree = [0] * V\n\n        # Step 1: Compute in-degree for every vertex\n        for u in range(V):\n            for v in adj[u]:\n                in_degree[v] += 1\n\n        # Step 2: Enqueue all vertices with in-degree 0\n        queue = deque([i for i in range(V) if in_degree[i] == 0])\n\n        # Step 3: BFS processing\n        visited_count = 0\n        while queue:\n            node = queue.popleft()\n            visited_count += 1\n\n            for neighbor in adj[node]:\n                in_degree[neighbor] -= 1\n                if in_degree[neighbor] == 0:\n                    queue.append(neighbor)\n\n        # If visited count != total vertices, a cycle is present\n        return visited_count != V"
