      "title": "Find a topological ordering of a Directed Acyclic Graph using Kahn's algorithm (BFS).",
      "canonicalName": "Topological Sort BFS",
      "difficulty": "Hard",
      "bounds": "Time Complexity: $\\mathcal{O}(V + E)$ | Space Complexity: $\\mathcal{O}(V)$",
      "mantra": "- Compute in-degrees for all $V$ nodes; seed a queue with all vertices having an in-degree of 0.\n- Pop vertex $u$, append it to the topological ordering, and decrement in-degrees of its outgoing neighbors.\n- If the output size is less than $V$, the graph contains a cycle and no valid topological sort exists.",
      "leetcode": "",
      "tuf": "https://takeuforward.org/data-structure/topological-sort-bfs/",
      "cpp": "#include<bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n\tvector<int> topo(int N, vector<int> adj[]) {\n        queue<int> q; \n\t    vector<int> indegree(N, 0); \n\t    for(int i = 0;i<N;i++) {\n\t        for(auto it: adj[i]) {\n\t            indegree[it]++; \n\t        }\n\t    }\n\t    \n\t    for(int i = 0;i<N;i++) {\n\t        if(indegree[i] == 0) {\n\t            q.push(i); \n\t        }\n\t    }\n\t    vector<int> topo;\n\t    while(!q.empty()) {\n\t        int node = q.front(); \n\t        q.pop(); \n\t        topo.push_back(node);\n\t        for(auto it : adj[node]) {\n\t            indegree[it]--;\n\t            if(indegree[it] == 0) {\n\t                q.push(it); \n\t            }\n\t        }\n\t    }\n\t    return topo;\n\t}\n};\n\n\n\nint main()\n{\n\n    \tvector<int> adj[6];\n    \tadj[5].push_back(2);\n    \tadj[5].push_back(0);\n    \tadj[4].push_back(0);\n    \tadj[4].push_back(1);\n    \tadj[3].push_back(1);\n    \tadj[2].push_back(3);\n\n    \tSolution obj;\n    \tvector<int> v=obj.topo(6, adj);\n    \tfor(auto it:v)\n    \tcout<<it<<\" \";\n    \n\n    return 0;\n}",
      "py": "from collections import deque\n\n\nclass Solution:\n\n    def topo(self, n: int, adj: list[list[int]]) -> list[int]:\n        indegree = [0] * n\n\n        # Calculate indegree for each vertex\n        for u in range(n):\n            for v in adj[u]:\n                indegree[v] += 1\n\n        # Enqueue all vertices with indegree 0\n        queue = deque([i for i in range(n) if indegree[i] == 0])\n        topo_order = []\n\n        # Process vertices\n        while queue:\n            node = queue.popleft()\n            topo_order.append(node)\n\n            for neighbor in adj[node]:\n                indegree[neighbor] -= 1\n                if indegree[neighbor] == 0:\n                    queue.append(neighbor)\n\n        return topo_order\n\n\nif __name__ == \"__main__\":\n    n = 6\n    adj = [[] for _ in range(n)]\n    adj[5].extend([2, 0])\n    adj[4].extend([0, 1])\n    adj[3].append(1)\n    adj[2].append(3)\n\n    obj = Solution()\n    result = obj.topo(n, adj)\n    print(*result)"
