      "id": 163,
      "patternId": 14,
      "patternName": "Dynamic Programming",
      "problemSeq": 3,
      "title": "Find the minimum path sum from the top-left to the bottom-right of an m x n matrix moving only right or down.",
      "canonicalName": "Minimum sum path in the matrix, (count paths and similar type do, also backtrack to find the Minimum path)",
      "difficulty": "Medium",
      "bounds": "Time Complexity: $\\mathcal{O}(M \\cdot N)$ | Space Complexity: $\\mathcal{O}(1)$",
      "mantra": "- Grid min-cost path: cost[r][c] = grid[r][c] + min(cost[r-1][c], cost[r][c-1]).\n- Initialize first row and column prefixes as strict cumulative sums.\n- Overwriting grid entries in-place achieves minimal space without allocating state buffers.",
      "leetcode": "https://leetcode.com/problems/minimum-path-sum/",
      "tuf": "https://takeuforward.org/data-structure/minimum-path-sum-in-a-grid-dp-10/",
      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Class to solve the problem\nclass Solution {\npublic:\n    // Function to calculate minimum path sum\n    int minPathSum(vector<vector<int>> &matrix) {\n        int n = matrix.size();\n        int m = matrix[0].size();\n\n        // Create DP table\n        vector<vector<int>> dp(n, vector<int>(m, 0));\n\n        // Fill the table\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < m; j++) {\n\n                // First cell initialization\n                if (i == 0 && j == 0)\n                    dp[i][j] = matrix[i][j];\n                else {\n                    // Calculate from top\n                    int up = matrix[i][j];\n                    if (i > 0) up += dp[i - 1][j];\n                    else up += 1e9;\n\n                    // Calculate from left\n                    int left = matrix[i][j];\n                    if (j > 0) left += dp[i][j - 1];\n                    else left += 1e9;\n\n                    // Take minimum\n                    dp[i][j] = min(up, left);\n                }\n            }\n        }\n\n        // Return result\n        return dp[n - 1][m - 1];\n    }\n};\n\n// Driver function\nint main() {\n    vector<vector<int>> matrix{\n        {5, 9, 6},\n        {11, 5, 2}\n    };\n\n    Solution obj;\n    cout << \"Minimum sum path: \" << obj.minPathSum(matrix) << endl;\n    return 0;\n}",
      "py": "class Solution:\n    # Function to calculate minimum path sum\n    def minPathSum(self, matrix):\n        n = len(matrix)\n        m = len(matrix[0])\n\n        # Create DP table\n        dp = [[0 for _ in range(m)] for _ in range(n)]\n\n        # Fill the table\n        for i in range(n):\n            for j in range(m):\n\n                # First cell initialization\n                if i == 0 and j == 0:\n                    dp[i][j] = matrix[i][j]\n                else:\n                    # Calculate from top\n                    up = matrix[i][j]\n                    if i > 0:\n                        up += dp[i-1][j]\n                    else:\n                        up += int(1e9)\n\n                    # Calculate from left\n                    left = matrix[i][j]\n                    if j > 0:\n                        left += dp[i][j-1]\n                    else:\n                        left += int(1e9)\n\n                    # Take minimum\n                    dp[i][j] = min(up, left)\n\n        # Return result\n        return dp[n-1][m-1]\n\n# Driver code\nmatrix = [\n    [5, 9, 6],\n    [11, 5, 2]\n]\n\nobj = Solution()\nprint(\"Minimum sum path:\", obj.minPathSum(matrix))"
