      "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Class that contains the KMP algorithm and LPS array construction\nclass Solution {\npublic:\n    // Function to compute the LPS (Longest Prefix Suffix) array\n    vector<int> computeLPS(string pattern) {\n        // Create LPS array initialized with 0\n        vector<int> lps(pattern.length(), 0);\n\n        // Length of the previous longest prefix which is also a suffix\n        int len = 0;\n\n        // Start from the second character of the pattern\n        int i = 1;\n\n        // Loop to fill the LPS array\n        while (i < pattern.length()) {\n            // If current character matches the character at len\n            if (pattern[i] == pattern[len]) {\n                // Increase length of current matching prefix\n                len++;\n                // Assign it to lps[i]\n                lps[i] = len;\n                // Move to next index\n                i++;\n            } else {\n                // If mismatch and len is not 0, try shorter previous prefix\n                if (len != 0) {\n                    len = lps[len - 1];\n                } else {\n                    // If no prefix match found, set lps[i] to 0\n                    lps[i] = 0;\n                    // Move to next index\n                    i++;\n                }\n            }\n        }\n        // Return the complete LPS array\n        return lps;\n    }\n\n    // Function to search pattern in text using KMP\n    vector<int> KMP(string text, string pattern) {\n        // Preprocess the pattern and compute LPS array\n        vector<int> lps = computeLPS(pattern);\n        // Vector to store the starting indices of all matches\n        vector<int> result;\n        // Pointers for text and pattern\n        int i = 0;\n        int j = 0;\n\n        // Loop through the text\n        while (i < text.length()) {\n            // If characters match, move both pointers\n            if (text[i] == pattern[j]) {\n                i++;\n                j++;\n            }\n            // If the whole pattern is matched\n            if (j == pattern.length()) {\n                // Store the index of match\n                result.push_back(i - j);\n\n                // Use LPS to continue searching\n                j = lps[j - 1];\n            }\n            // If mismatch occurs after some matches\n            else if (i < text.length() && text[i] != pattern[j]) {\n                // Use LPS to avoid unnecessary comparisons\n                if (j != 0) {\n                    j = lps[j - 1];\n                } else {\n\n                    // Move forward in text if j is at start\n                    i++;\n                }\n            }\n        }\n        // Return all found indices\n        return result;\n    }\n};\n\n// Main function to test the KMP search\nint main() {\n    // Define the text string\n    string text = \"ababcababcabc\";\n    // Define the pattern to search\n    string pattern = \"abc\";\n\n    // Create an object of the Solution class\n    Solution sol;\n\n    // Call the KMP function to get all match indices\n    vector<int> matches = sol.KMP(text, pattern);\n\n    // Output the results\n    cout << \"Pattern found at indices: \";\n    for (int idx : matches) {\n        cout << idx << \" \";\n    }\n    cout << endl;\n\n    return 0;\n}",
      "py": "class Solution:\n\n    # Function to compute the LPS array\n    def computeLPS(self, pattern):\n\n        # Create lps array\n        lps = [0] * len(pattern)\n\n        # Length of the previous longest prefix suffix\n        length = 0\n\n        # Start from second character\n        i = 1\n\n        # Build the lps array\n        while i < len(pattern):\n\n            # If characters match\n            if pattern[i] == pattern[length]:\n                length += 1\n                lps[i] = length\n                i += 1\n            else:\n\n                # If mismatch and length > 0\n                if length != 0:\n                    length = lps[length - 1]\n                else:\n\n                    # Set lps[i] to 0 and move on\n                    lps[i] = 0\n                    i += 1\n\n        # Return computed lps\n        return lps\n\n    # KMP search function\n    def KMP(self, text, pattern):\n\n        # Compute the LPS array\n        lps = self.computeLPS(pattern)\n\n        # List to store match indices\n        result = []\n\n        # Indices for text and pattern\n        i = j = 0\n\n        # Scan through the text\n        while i < len(text):\n\n            # If characters match\n            if text[i] == pattern[j]:\n                i += 1\n                j += 1\n\n            # Full match found\n            if j == len(pattern):\n                result.append(i - j)\n                j = lps[j - 1]\n\n            # Mismatch after some matches\n            elif i < len(text) and text[i] != pattern[j]:\n                if j != 0:\n                    j = lps[j - 1]\n                else:\n                    i += 1\n\n        # Return the result\n        return result\n\n\n# Main test\nsol = Solution()\ntext = \"ababcababcabc\"\npattern = \"abc\"\nprint(\"Pattern found at indices:\", sol.KMP(text, pattern))"
